 19	/// A Vitis HLS invocation is considered transient iff its stdout
 20	/// contains `Pre-synthesis
 21	/// failed.` and does **not** contain `\nERROR:`.
 22	#[must_use]
 23	pub(crate) fn is_transient_hls_output(stdout: &str, _stderr: &str) -> bool {
 24	    stdout.contains("Pre-synthesis failed.") && !stdout.contains("\nERROR:")
 25	}
