100	/// Build the Vitis HLS TCL script for the given job.
101	///
102	/// Build the HLS command sequence: `open_project` → `set_top` →
103	/// `add_files` → `open_solution` → `set_part` → `create_clock` →
104	/// `config_compile` → `config_interface` → `{config}` →
105	/// `{other_configs}` → `config_rtl` → `csynth_design` → `exit`.
106	fn build_rtl_config(reset_low: bool, auto_prefix: bool) -> String {
107	    let mut line = format!(
108	        "config_rtl -reset_level {}",
109	        if reset_low { "low" } else { "high" }
110	    );
111	    if auto_prefix {
112	        // Vitis HLS accepts `-module_auto_prefix` here.
113	        line.push_str(" -module_auto_prefix");
114	    }
115	    line
116	}
117	
118	/// Collect every `-I<dir>` / `-isystem<dir>` destination from the
119	/// job's CFLAGS.  Existing directories are uploaded verbatim so the
120	/// remote `vitis_hls` resolves sibling headers the same way the local
121	/// run would. Relative paths are absolutized against the current
122	/// working directory.
123	/// Handles both fused (`-I/dir`) and split (`-I`, `/dir`) forms.
124	fn kernel_include_dirs(cflags: &[String]) -> Vec<Utf8PathBuf> {
125	    let mut out: Vec<Utf8PathBuf> = Vec::new();
126	    let mut i = 0;
127	    while i < cflags.len() {
128	        let trimmed = cflags[i].trim();
129	        let (dir_str, consumed) = if let Some(rest) = trimmed.strip_prefix("-isystem") {
130	            let rest = rest.trim();
131	            if rest.is_empty() && i + 1 < cflags.len() {
132	                (cflags[i + 1].trim(), 2)
133	            } else {
134	                (rest, 1)
135	            }
136	        } else if let Some(rest) = trimmed.strip_prefix("-I") {
137	            let rest = rest.trim();
138	            if rest.is_empty() && i + 1 < cflags.len() {
139	                (cflags[i + 1].trim(), 2)
140	            } else {
141	                (rest, 1)
142	            }
143	        } else {
144	            i += 1;
145	            continue;
146	        };
147	        if !dir_str.is_empty() {
148	            let p = crate::util::absolutize(&Utf8PathBuf::from(dir_str));
149	            if p.is_dir() {
150	                out.push(p);
151	            }
152	        }
153	        i += consumed;
154	    }
155	    out
156	}
