158	/// Kernel metadata passed through the
159	/// `TAPA_KERNEL_COUNT / TAPA_KERNEL_PATH_$i / TAPA_KERNEL_CFLAGS_$i`
160	/// environment contract. Keeping the
161	/// per-task paths in env entries (instead of baking them into the
162	/// TCL body) lets the remote runner rewrite them through its
163	/// rootfs-mirroring path-rewriter just like every other absolute
164	/// local path.
165	fn kernel_env_entries(job: &HlsJob) -> Vec<(String, String)> {
166	    let mut env: Vec<(String, String)> = Vec::new();
167	    env.push(("TAPA_KERNEL_COUNT".into(), "1".into()));
168	    env.push((
169	        "TAPA_KERNEL_PATH_0".into(),
170	        job.cpp_source.as_str().to_string(),
171	    ));
172	    // Vitis `add_files -cflags` receives the value as a Tcl string,
173	    // not a shell command — shell quoting is treated literally and
174	    // breaks flags like `-D__builtin_FILE()=__FILE__`.
175	    let cflags = job.cflags.join(" ");
176	    env.push(("TAPA_KERNEL_CFLAGS_0".into(), cflags));
177	    env
178	}
