209	fn is_transient(job: &HlsJob, stdout: &str, stderr: &str) -> bool {
210	    match job.transient_patterns.as_deref() {
211	        Some(v) => v
212	            .iter()
213	            .any(|p| stdout.contains(p.as_str()) || stderr.contains(p.as_str())),
214	        None => is_transient_hls_output(stdout, stderr),
215	    }
216	}
