281	/// Name of the HLS solution subdirectory — mirrors the TCL template's
282	/// `open_solution "<solution>"` value.
283	fn solution_name(job: &HlsJob) -> String {
284	    if job.solution_name.is_empty() {
285	        job.top_name.clone()
286	    } else {
287	        job.solution_name.clone()
288	    }
289	}
