314	fn harvest_and_stage(
315	    job: &HlsJob,
316	    stage_dir: &camino::Utf8Path,
317	    out: ToolOutput,
318	) -> Result<HlsOutput> {
319	    // The runner already ensured the HLS project tree is on the
320	    // local filesystem (Local: it wrote directly under `cwd`; Remote:
321	    // `run_once` downloaded `cwd` back into place via the rootfs
322	    // mirror). We just need to copy the caller-facing slices out.
323	    let solution = solution_name(job);
324	    let syn_rel: Utf8PathBuf = ["project", &solution, "syn"].iter().collect();
325	
326	    // Copy the real HLS artifacts into the caller-visible output dirs.
327	    let syn_abs = stage_dir.join(&syn_rel);
328	    fs_err::create_dir_all(&job.reports_out_dir)?;
329	    fs_err::create_dir_all(&job.hdl_out_dir)?;
330	    copy_tree(&syn_abs.join("report"), &job.reports_out_dir).map_err(|e| {
331	        XilinxError::HlsReportParse(format!(
332	            "stage reports {} → {}: {e}",
333	            syn_abs.join("report").as_str(),
334	            job.reports_out_dir.as_str()
335	        ))
336	    })?;
337	    copy_tree(&syn_abs.join("verilog"), &job.hdl_out_dir).map_err(|e| {
338	        XilinxError::HlsReportParse(format!(
339	            "stage verilog {} → {}: {e}",
340	            syn_abs.join("verilog").as_str(),
341	            job.hdl_out_dir.as_str()
342	        ))
343	    })?;
344	
345	    let report_xml = job
346	        .reports_out_dir
347	        .join(format!("{}_csynth.xml", job.top_name));
348	    let fallback = job
349	        .reports_out_dir
350	        .join(format!("{}.csynth.xml", job.top_name));
351	    let report_xml = if report_xml.is_file() {
352	        report_xml
353	    } else {
354	        fallback
355	    };
356	    let bytes = fs_err::read(&report_xml).map_err(|_| {
357	        XilinxError::HlsReportParse(format!("missing csynth.xml at {}", report_xml.as_str()))
358	    })?;
359	    let csynth = parse_csynth_xml(&bytes)?;
360	
361	    let verilog_files = collect_files(&job.hdl_out_dir)?;
362	    if verilog_files.is_empty() {
363	        return Err(XilinxError::ToolFailure {
364	            program: "vitis_hls".into(),
365	            code: 0,
366	            stderr: format!("no HDL output produced in {}", job.hdl_out_dir.as_str()),
367	        });
368	    }
369	    let report_paths = collect_files(&job.reports_out_dir)?;
370	    Ok(HlsOutput {
371	        csynth,
372	        verilog_files,
373	        report_paths,
374	        stdout: out.stdout,
375	        stderr: out.stderr,
376	    })
377	}
378	
379	fn collect_files(dir: &camino::Utf8Path) -> Result<Vec<Utf8PathBuf>> {
380	    if !dir.exists() {
381	        return Ok(Vec::new());
382	    }
383	    let mut out = Vec::new();
384	    for ent in fs_err::read_dir(dir)? {
385	        let ent = ent?;
386	        if ent.file_type()?.is_file() {
387	            out.push(crate::util::utf8(ent.path()));
388	        }
389	    }
390	    out.sort();
391	    Ok(out)
392	}
