181	pub fn build_hls_tcl(job: &HlsJob) -> String {
182	    let solution = if job.solution_name.is_empty() {
183	        job.top_name.as_str()
184	    } else {
185	        job.solution_name.as_str()
186	    };
187	    let other = if job.other_configs.is_empty() {
188	        String::new()
189	    } else {
190	        format!("{}\n", job.other_configs)
191	    };
192	    let rtl = build_rtl_config(job.reset_low, job.auto_prefix);
193	    let mut env = minijinja::Environment::new();
194	    env.add_template("run_hls", include_str!("templates/run_hls.tcl.j2"))
195	        .expect("template parses");
196	    env.get_template("run_hls")
197	        .expect("template exists")
198	        .render(minijinja::context! {
199	            top => job.top_name,
200	            solution,
201	            part => job.target_part,
202	            clock => job.clock_period,
203	            other,
204	            rtl,
205	        })
206	        .expect("render succeeds")
207	}
