223	/// Run a single Vitis HLS invocation inside `stage_dir`. The runner
224	/// executes with cwd set to `stage_dir`; after the tool exits, the
225	/// `project/<solution>/syn/` subtree lives at
226	/// `stage_dir/project/<solution>/syn` on local runners or inside
227	/// the runner's remote work dir on remote runners (pulled back in
228	/// place via the invocation's `downloads`).
229	fn run_hls_attempt(
230	    runner: &dyn ToolRunner,
231	    job: &HlsJob,
232	    stage_dir: &camino::Utf8Path,
233	) -> Result<ToolOutput> {
234	    let tcl = build_hls_tcl(job);
235	    let tcl_path = stage_dir.join("run_hls.tcl");
236	    fs_err::write(&tcl_path, tcl.as_bytes())?;
237	    let mut inv = ToolInvocation::new("vitis_hls")
238	        .arg("-f")
239	        .arg(tcl_path.as_str());
240	    inv.cwd = Some(stage_dir.to_path_buf());
241	    // Pin `HOME` to the per-run stage dir. Vitis HLS otherwise writes shared
242	    // `~/.Xilinx` state that pollutes the workspace and races under
243	    // sandboxed/parallel Bazel builds. Using `inv.env` (vs
244	    // `Command::env`) lets the remote runner's path rewriter remap
245	    // the value to its rootfs counterpart.
246	    inv.env
247	        .insert("HOME".into(), stage_dir.as_str().to_string());
248	    // Uploads: TCL, the kernel source, every `-I` / `-isystem`
249	    // include directory referenced by the cflags, plus any caller extras.
250	    inv.uploads.push(tcl_path);
251	    if let Some(src_dir) = job.cpp_source.parent() {
252	        if src_dir.is_absolute() && src_dir.is_dir() {
253	            inv.uploads.push(src_dir.to_path_buf());
254	        } else {
255	            inv.uploads.push(job.cpp_source.clone());
256	        }
257	    } else {
258	        inv.uploads.push(job.cpp_source.clone());
259	    }
260	    inv.uploads.extend(kernel_include_dirs(&job.cflags));
261	    inv.uploads.extend(job.uploads.iter().cloned());
262	
263	    // Kernel metadata via env entries — the `TAPA_*` prefix passes
264	    // the remote-env forwarding allowlist, and the remote runner's
265	    // path rewriter remaps absolute local paths in the values to
266	    // their rootfs counterparts.
267	    for (k, v) in kernel_env_entries(job) {
268	        inv.env.insert(k, v);
269	    }
270	
271	    // Ask the runner to bring the HLS project tree — at least the
272	    // `syn/{report,verilog}` subtree — back onto the local filesystem
273	    // alongside everything else the caller requested. On local runs
274	    // the files are already under `cwd` (stage_dir); on remote runs
275	    // the runner tar-pipes the rootfs mirror back in place.
276	    inv.downloads.push(stage_dir.to_path_buf());
277	    inv.downloads.extend(job.downloads.iter().cloned());
278	    runner.run(&inv)
279	}
