394	/// How the per-attempt staging directory is sourced.
395	#[derive(Debug, Clone, Copy)]
396	enum StageDir<'a> {
397	    /// Fresh tempdir created (and cleaned up) per retry attempt.
398	    Ephemeral,
399	    /// Caller-owned directory reused across retries; the caller owns cleanup.
400	    Borrowed(&'a camino::Utf8Path),
401	}
402	
403	/// Bounded retry wrapper keyed on the transient-failure predicate. The
404	/// default budget is 3 attempts; callers can override per job via
405	/// `transient_patterns`.
406	fn run_hls_with_retry_impl(
407	    runner: &dyn ToolRunner,
408	    job: &HlsJob,
409	    max_attempts: u32,
410	    stage: StageDir<'_>,
411	) -> Result<HlsOutput> {
412	    let max_attempts = max_attempts.max(1);
413	    let backoff = ExponentialBuilder::default()
414	        .with_min_delay(Duration::from_millis(500))
415	        .with_max_delay(Duration::from_secs(30))
416	        .with_max_times(max_attempts.saturating_sub(1) as usize);
417	
418	    let delay_fn = job.delay_fn.clone();
419	
420	    let result = (|| -> std::result::Result<HlsOutput, RetryError> {
421	        // Resolve the stage path for this attempt. For `Ephemeral`, the
422	        // tempdir guard is kept alive in `_guard` for the whole closure
423	        // body so the directory exists during run + harvest.
424	        let (stage_path, _guard): (camino::Utf8PathBuf, Option<tempfile::TempDir>) = match &stage {
425	            StageDir::Ephemeral => {
426	                let dir = tempfile::tempdir().map_err(|e| RetryError::Fatal(XilinxError::Io(e)))?;
427	                let path = crate::util::utf8(dir.path());
428	                (path, Some(dir))
429	            }
430	            StageDir::Borrowed(p) => (p.to_path_buf(), None),
431	        };
432	        let out = run_hls_attempt(runner, job, &stage_path).map_err(RetryError::Fatal)?;
433	        if out.exit_code == 0 {
434	            return harvest_and_stage(job, &stage_path, out).map_err(RetryError::Fatal);
435	        }
436	        let transient = is_transient(job, &out.stdout, &out.stderr);
437	        if !transient {
438	            let stderr = if out.stderr.is_empty() {
439	                out.stdout
440	            } else {
441	                out.stderr
442	            };
443	            return Err(RetryError::Fatal(XilinxError::ToolFailure {
444	                program: "vitis_hls".into(),
445	                code: out.exit_code,
446	                stderr,
447	            }));
448	        }
449	        Err(RetryError::Transient)
450	    })
451	    .retry(backoff)
452	    .when(|err| matches!(err, RetryError::Transient))
453	    .sleep(move |dur| {
454	        if let Some(f) = &delay_fn {
455	            f(dur);
456	        } else {
457	            std::thread::sleep(dur);
458	        }
459	    })
460	    .call();

