  1	//! Narrow parser for the kernel clock rows in a Vivado timing summary.
  2	
  3	use crate::error::{Result, XilinxError};
  4	
  5	/// Tolerance for matching a reported clock frequency against the requested
  6	/// kernel frequency. Vivado reports platform clocks to three decimals, and the
  7	/// conservative whole-MHz `--kernel_frequency` rounds, so allow ±1 MHz.
  8	const FREQUENCY_MATCH_TOLERANCE_MHZ: f64 = 1.0;
  9	
 10	#[derive(Debug, Clone, Copy, PartialEq)]
 11	pub struct KernelTiming {
 12	    pub reported_target_period_ns: f64,
 13	    pub reported_target_mhz: f64,
 14	    pub wns_ns: f64,
 15	    pub achieved_period_ns: f64,
 16	    pub fmax_mhz: f64,
 17	}
 18	
 19	/// Parse the kernel clock rows from the `Clock Summary` and `Intra Clock Table`.
 20	///
 21	/// The report-wide timing summary can be dominated by an unrelated platform
 22	/// clock, so the kernel result is derived only from these two clock-specific
 23	/// rows.
 24	///
 25	/// `target_mhz` is the whole-MHz frequency passed to `v++ --kernel_frequency`.
 26	/// The kernel clock is identified by its reported `Frequency(MHz)` matching
 27	/// `target_mhz`, which is robust to platform-specific clock names: Vitis names
 28	/// it `ap_clk` on some platforms and `clk_kernel_00_unbuffered_net` (or
 29	/// similar) on Alveo shell platforms. When the target is unknown (`None`),
 30	/// the parser falls back to the historical `ap_clk` name.
 31	pub fn parse_kernel_timing_summary(report: &str, target_mhz: Option<u32>) -> Result<KernelTiming> {
 32	    let kernel_clock = identify_kernel_clock(report, target_mhz)?;
 33	
 34	    let clock_row = unique_clock_row(report, "Clock Summary", &kernel_clock)?;
 35	    let intra_row = unique_clock_row(report, "Intra Clock Table", &kernel_clock)?;
 36	
 37	    let reported_target_period_ns =
 38	        positive_finite("kernel Period(ns)", parse_field(&clock_row, "Period(ns)")?)?;
 39	    let reported_target_mhz = positive_finite(
 40	        "kernel Frequency(MHz)",
 41	        parse_field(&clock_row, "Frequency(MHz)")?,
 42	    )?;
 43	    let wns_ns = finite("kernel WNS(ns)", parse_field(&intra_row, "WNS(ns)")?)?;
 44	    let achieved_period_ns = reported_target_period_ns - wns_ns;
 45	    let achieved_period_ns = positive_finite("kernel achieved period", achieved_period_ns)?;
 46	    let fmax_mhz = positive_finite("kernel Fmax", 1000.0 / achieved_period_ns)?;
 47	
 48	    Ok(KernelTiming {
 49	        reported_target_period_ns,
 50	        reported_target_mhz,
 51	        wns_ns,
 52	        achieved_period_ns,
 53	        fmax_mhz,
 54	    })
 55	}
 56	
 57	/// Decide which clock row in the `Clock Summary` is the kernel clock.
 58	///
 59	/// Preference order:
 60	/// 1. A clock whose reported `Frequency(MHz)` matches `target_mhz` (within
 61	///    tolerance). This is the robust, platform-agnostic signal.
 62	/// 2. Otherwise a clock literally named `ap_clk` (the historical TAPA / HLS
 63	///    convention).
 64	fn identify_kernel_clock(report: &str, target_mhz: Option<u32>) -> Result<String> {
 65	    let clocks = clock_rows(report, "Clock Summary")?;
 66	    let by_frequency = target_mhz.map(f64::from).and_then(|target| {
 67	        clocks
 68	            .iter()
 69	            .find_map(|row| {
 70	                let freq = parse_field(row, "Frequency(MHz)").ok()?;
 71	                ((freq - target).abs() <= FREQUENCY_MATCH_TOLERANCE_MHZ).then(|| row.clock_name())
 72	            })
 73	            .map(str::to_string)
 74	    });
 75	    if let Some(clock) = by_frequency {
 76	        return Ok(clock);
 77	    }
 78	
 79	    clocks
 80	        .iter()
 81	        .find_map(|row| (row.clock_name() == "ap_clk").then(|| row.clock_name().to_string()))
 82	        .ok_or_else(|| {
 83	            let detail = match target_mhz {
 84	                Some(target) => {
 85	                    format!(
 86	                        "no kernel clock matching target frequency {target} MHz or named `ap_clk` \
 87	                         in `Clock Summary`"
 88	                    )
 89	                }
 90	                None => "missing `ap_clk` row in `Clock Summary`".to_string(),
 91	            };
 92	            XilinxError::TimingSummaryParse(detail)
 93	        })
 94	}
 95	
 96	/// Collect every clock data row in a named section's table.
 97	fn clock_rows(report: &str, title: &str) -> Result<Vec<TableRow>> {
 98	    let lines: Vec<&str> = report.lines().collect();
 99	    let marker = format!("| {title}");
100	    let section_starts: Vec<usize> = lines
101	        .iter()
102	        .enumerate()
103	        .filter_map(|(index, line)| (line.trim() == marker).then_some(index))
104	        .collect();
105	    let section_start = match section_starts.as_slice() {
106	        [index] => *index,
107	        [] => return parse_error(format!("missing `{title}` section")),
108	        _ => return parse_error(format!("ambiguous `{title}` sections")),
109	    };
110	
111	    let header_index = lines
112	        .iter()
113	        .enumerate()
114	        .skip(section_start + 1)
115	        .take(16)
116	        .find_map(|(index, line)| {
117	            let columns = split_columns(line);
118	            (columns.first() == Some(&"Clock") && columns.len() >= 2).then_some(index)
119	        })
120	        .ok_or_else(|| {
121	            XilinxError::TimingSummaryParse(format!("missing table header in `{title}`"))
122	        })?;
123	    let headers: Vec<String> = split_columns(lines[header_index])
124	        .into_iter()
125	        .map(str::to_string)
126	        .collect();
127	
128	    let mut rows = Vec::new();
129	    let mut saw_separator = false;
130	    for line in lines.iter().skip(header_index + 1) {
131	        let trimmed = line.trim();
132	        if !saw_separator {
133	            if trimmed.starts_with('-') {
134	                saw_separator = true;
135	            }
136	            continue;
137	        }
138	        if trimmed.is_empty() {
139	            break;
140	        }
141	        let values = split_columns(line);
142	        if !values.is_empty() {
143	            rows.push(TableRow {
144	                headers: headers.clone(),
145	                values: values.into_iter().map(str::to_string).collect(),
146	            });
147	        }
148	    }
149	    Ok(rows)
150	}
151	
152	fn unique_clock_row(report: &str, title: &str, clock: &str) -> Result<TableRow> {
153	    let mut matching = clock_rows(report, title)?
154	        .into_iter()
155	        .filter(|row| row.clock_name() == clock)
156	        .collect::<Vec<_>>();
157	    let values = match matching.as_mut_slice() {
158	        [row] => row.values.clone(),
159	        [] => return parse_error(format!("missing `{clock}` row in `{title}`")),
160	        _ => return parse_error(format!("ambiguous `{clock}` rows in `{title}`")),
161	    };
162	    let headers = matching[0].headers.clone();
163	    if headers.len() != values.len() {
164	        return parse_error(format!(
165	            "malformed `{clock}` row in `{title}`: expected {} columns, found {}",
166	            headers.len(),
167	            values.len()
168	        ));
169	    }
170	    Ok(TableRow { headers, values })
171	}
