296	/// Run one hardware link and return its kernel-clock timing result.
297	pub fn run_vitis_link(runner: &dyn ToolRunner, job: &VitisLinkJob) -> Result<VitisLinkOutput> {
298	    let resolved = ResolvedJob::new(job)?;
299	    validate_input(&resolved.xo, "XO")?;
300	    if let Some(xdc) = &resolved.floorplan_xdc {
301	        validate_input(xdc, "floorplan XDC")?;
302	    }
303	    if let Some(config) = &resolved.connectivity_config {
304	        validate_input(config, "connectivity config")?;
305	    }
306	
307	    fs_err::create_dir_all(&resolved.work_dir)?;
308	    let output_parent = resolved
309	        .output_xclbin
310	        .parent()
311	        .ok_or_else(|| XilinxError::VitisLink("xclbin path has no parent directory".into()))?;
312	    fs_err::create_dir_all(output_parent)?;
313	    fs_err::create_dir_all(&resolved.report_dir)?;
314	    fs_err::create_dir_all(&resolved.log_dir)?;
315	    remove_stale_output(&resolved.output_xclbin)?;
316	    remove_stale_output(&resolved.timing_report)?;
317	    fs_err::write(&resolved.timing_hook, final_timing_tcl().as_bytes())?;
318	
319	    let invocation = build_invocation(&resolved);
320	    let tool_output = runner.run(&invocation)?;
321	    if tool_output.exit_code != 0 {
322	        return Err(XilinxError::ToolFailure {
323	            program: "v++".into(),
324	            code: tool_output.exit_code,
325	            stderr: super::merged_failure_output(tool_output.stdout, tool_output.stderr),
326	        });
327	    }
328	    if !resolved.timing_report.is_file() {
329	        return link_error(format!(
330	            "v++ exited successfully but did not produce timing report `{}`",
331	            resolved.timing_report
332	        ));
333	    }
334	    let timing_text = fs_err::read_to_string(&resolved.timing_report)?;
335	    let timing = parse_kernel_timing_summary(&timing_text, Some(job.target_mhz))?;
336	
337	    Ok(VitisLinkOutput {
338	        timing_report: resolved.timing_report,
339	        timing,
340	        stdout: tool_output.stdout,
341	        stderr: tool_output.stderr,
342	    })
343	}
344	
345	fn remove_stale_output(path: &Utf8Path) -> Result<()> {
346	    match fs_err::remove_file(path) {
347	        Ok(()) => Ok(()),
348	        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
349	        Err(error) => Err(error.into()),
350	    }
351	}
