  1	//! Subprocess abstraction: the `ToolRunner` trait plus the local
  2	//! `std::process::Command`-backed implementation and a test-only mock.
  3	//!
  4	//! Every tool wrapper speaks through this trait so unit tests never
  5	//! need `vitis_hls` or `vivado` on the host.
  6	
  7	use std::collections::HashMap;
  8	use std::path::{Path, PathBuf};
  9	use std::sync::Mutex;
 10	use std::time::Duration;
 11	
 12	use camino::Utf8PathBuf;
 13	
