 15	
 16	#[derive(Debug, Clone, Default)]
 17	pub struct ToolInvocation {
 18	    pub program: String,
 19	    pub args: Vec<String>,
 20	    pub env: HashMap<String, String>,
 21	    pub stdin: Option<Vec<u8>>,
 22	    pub cwd: Option<Utf8PathBuf>,
 23	    pub uploads: Vec<Utf8PathBuf>,
 24	    pub downloads: Vec<Utf8PathBuf>,
 25	    pub timeout: Option<Duration>,
 26	}
 27	
 28	impl ToolInvocation {
 29	    pub fn new(program: impl Into<String>) -> Self {
 30	        Self {
 31	            program: program.into(),
 32	            ..Self::default()
 33	        }
 34	    }
 35	
 36	    #[must_use]
 37	    pub fn arg(mut self, arg: impl Into<String>) -> Self {
 38	        self.args.push(arg.into());
 39	        self
 40	    }
 41	
 42	    #[must_use]
 43	    pub fn env(mut self, key: impl Into<String>, value: impl Into<String>) -> Self {
 44	        self.env.insert(key.into(), value.into());
 45	        self
 46	    }
 47	
 48	    #[must_use]
 49	    pub fn timeout(mut self, timeout: Duration) -> Self {
 50	        self.timeout = Some(timeout);
 51	        self
 52	    }
 53	}
 54	
 55	#[derive(Debug, Clone, Default, PartialEq, Eq)]
 56	pub struct ToolOutput {
 57	    pub exit_code: i32,
 58	    pub stdout: String,
 59	    pub stderr: String,
 60	}
 61	
 62	pub trait ToolRunner: Send + Sync {
 63	    fn run(&self, inv: &ToolInvocation) -> Result<ToolOutput>;
 64	}
 65	
 66	/// Local subprocess runner: inherits the parent process's environment.
 67	/// For Xilinx tools, an existing `settings64.sh` under the applicable
 68	/// `XILINX_*` root is sourced before execution; otherwise bare program names
 69	/// resolve through the caller's `PATH`. `ToolInvocation::env` entries overlay
 70	/// the inherited environment.
 71	///
 72	/// Remote env allowlisting lives in `RemoteToolRunner` where the env
 73	/// crosses a machine boundary. On a single host, the child sees the
 74	/// parent shell's state. When
 75	/// `ToolInvocation::timeout` is set, the child is killed on expiry
 76	/// and the call returns `XilinxError::ToolTimeout`.
 77	#[derive(Debug, Default)]
 78	pub struct LocalToolRunner;
 79	
 80	impl LocalToolRunner {
 81	    pub const fn new() -> Self {
 82	        Self
 83	    }
 84	}
 85	
 86	/// Tool name → env vars that may hold its installation root, in
 87	/// precedence order. Adding a Xilinx tool is a one-line table edit.
 88	const XILINX_TOOL_ENVS: &[(&str, &[&str])] = &[
 89	    ("vitis_hls", &["XILINX_HLS", "XILINX_VITIS"]),
 90	    ("vivado", &["XILINX_VIVADO", "XILINX_VITIS"]),
 91	    ("v++", &["XILINX_VITIS"]),
 92	];
 93	
 94	fn xilinx_settings_envs(program: &str) -> &'static [&'static str] {
 95	    let tool = Path::new(program)
 96	        .file_name()
 97	        .and_then(|name| name.to_str())
 98	        .unwrap_or(program)
 99	        .trim_end_matches(".exe");
100	    XILINX_TOOL_ENVS
101	        .iter()
102	        .find_map(|(name, envs)| (*name == tool).then_some(*envs))
103	        .unwrap_or(&[])
104	}
105	
106	fn invocation_env_path(inv: &ToolInvocation, name: &str) -> Option<PathBuf> {
107	    if let Some(value) = inv.env.get(name) {
108	        return (!value.trim().is_empty()).then(|| PathBuf::from(value));
109	    }
110	    std::env::var_os(name)
111	        .filter(|value| !value.is_empty())
112	        .map(PathBuf::from)
113	}
114	
115	fn local_xilinx_settings(inv: &ToolInvocation) -> Option<PathBuf> {
116	    xilinx_settings_envs(&inv.program).iter().find_map(|name| {
117	        let root = invocation_env_path(inv, name)?;
118	        if root.is_file() && root.extension().is_some_and(|ext| ext == "sh") {
119	            return Some(root);
120	        }
121	        let settings = root.join("settings64.sh");
122	        settings.is_file().then_some(settings)
123	    })
124	}
125	
126	fn local_command(inv: &ToolInvocation) -> std::process::Command {
127	    let Some(settings) = local_xilinx_settings(inv) else {
128	        let mut cmd = std::process::Command::new(&inv.program);
129	        cmd.args(&inv.args);
130	        return cmd;
131	    };
132	
133	    // Keep the settings path and tool argv out of the shell program
134	    // text. Positional parameters preserve spaces and shell
135	    // metacharacters exactly while settings64.sh populates PATH and
136	    // the XILINX_* environment before exec.
137	    let mut cmd = std::process::Command::new("bash");
138	    cmd.arg("-c")
139	        .arg("source \"$1\" && shift && exec \"$@\"")
140	        .arg("tapa-xilinx-settings")
141	        .arg(settings)
142	        .arg(&inv.program)
143	        .args(&inv.args);
144	    cmd
145	}
146	
147	fn wait_with_deadline(
148	    child: &mut std::process::Child,
149	    deadline: std::time::Instant,
150	) -> std::io::Result<Option<std::process::ExitStatus>> {
151	    use wait_timeout::ChildExt as _;
152	    child.wait_timeout(deadline.saturating_duration_since(std::time::Instant::now()))
153	}
154	
155	impl ToolRunner for LocalToolRunner {
156	    fn run(&self, inv: &ToolInvocation) -> Result<ToolOutput> {
157	        use std::io::{Read, Write};
158	        use std::process::Stdio;
