164	            cmd.env(k, v);
165	        }
166	        if let Some(cwd) = &inv.cwd {
167	            cmd.current_dir(cwd.as_str());
168	        }
169	        cmd.stdin(if inv.stdin.is_some() {
170	            Stdio::piped()
171	        } else {
172	            Stdio::null()
173	        })
174	        .stdout(Stdio::piped())
175	        .stderr(Stdio::piped());
176	
177	        #[cfg(unix)]
