 1	//! `tapa` binary entry point. Parses globals + chained subcommands via
 2	//! clap, applies remote-config bootstrap, and walks the chained-step
 3	//! linked list.
 4	
 5	use std::process::ExitCode;
 6	
 7	use clap::Parser;
 8	
 9	use tapa_cli::context::CliContext;
10	use tapa_cli::error::CliError;
11	use tapa_cli::globals::Cli;
12	use tapa_cli::logging;
13	use tapa_cli::remote::bootstrap_remote;
14	
15	fn main() -> ExitCode {
16	    match run() {
17	        Ok(()) => ExitCode::SUCCESS,
18	        Err(err) => {
19	            eprintln!("tapa: {err}");
20	            ExitCode::from(err.exit_code())
21	        }
22	    }
23	}
24	
25	fn run() -> Result<(), CliError> {
26	    let cli = Cli::parse();
27	
28	    // A bare `tapa` invocation with no subcommand prints `--help`
29	    // and exits non-zero.
30	    if cli.step.is_none() {
31	        use clap::CommandFactory;
32	        let _ = Cli::command().print_help();
33	        eprintln!();
34	        return Err(CliError::InvalidArg(
35	            "no subcommand supplied — see `tapa --help`".to_string(),
36	        ));
37	    }
38	
39	    logging::install(cli.globals.verbose, cli.globals.quiet);
40	
41	    let mut ctx = CliContext::from_globals(&cli.globals);
42	    let work_dir = ctx.work_dir.clone();
43	    ctx.switch_work_dir(work_dir.clone())
44	        .map_err(|e| CliError::WorkDir(work_dir.clone(), e.to_string()))?;
45	
46	    if let Some(temp_dir) = cli.globals.temp_dir.as_deref() {
47	        std::env::set_var("TMPDIR", temp_dir);
48	    }
49	
50	    // Bootstrap remote config (~/.taparc + CLI overrides) before any
51	    // compiler step runs. Sync failures inside this call are non-fatal so
52	    // local-only flows are unaffected.
53	    ctx.remote_config = bootstrap_remote(&cli.globals)?;
54	
55	    if let Some(step) = cli.step {
56	        step.execute(&mut ctx)?;
57	    }
58	    Ok(())
59	}

