 1	//! Per-invocation execution context shared by the chained step pipeline.
 2	
 3	use std::path::PathBuf;
 4	
 5	use tapa_xilinx::RemoteConfig;
 6	
 7	use crate::globals::GlobalArgs;
 8	
 9	#[derive(Debug)]
10	pub struct CliContext {
11	    pub work_dir: PathBuf,
12	    pub temp_dir: Option<PathBuf>,
13	    pub clang_format_quota_in_bytes: u64,
14	    /// Resolved remote config (`~/.taparc` + CLI overrides). `None`
15	    /// means the run is purely local.
16	    pub remote_config: Option<RemoteConfig>,
17	    /// Verbosity counts for downstream command invocations.
18	    pub verbose: u8,
19	    pub quiet: u8,
20	}
21	
22	impl CliContext {
23	    pub fn from_globals(globals: &GlobalArgs) -> Self {
24	        Self {
25	            work_dir: absolutize_for_storage(&globals.work_dir),
26	            temp_dir: globals.temp_dir.clone(),
27	            clang_format_quota_in_bytes: globals.clang_format_quota_in_bytes,
28	            remote_config: None,
29	            verbose: globals.verbose,
30	            quiet: globals.quiet,
31	        }
32	    }
33	
34	    /// Dispatch `f` with the remote tool runner when a remote config
35	    /// is active (`~/.taparc` / `--remote-host`), otherwise the local
36	    /// runner.
37	    pub fn with_tool_runner<R>(&self, f: impl FnOnce(&dyn tapa_xilinx::ToolRunner) -> R) -> R {
38	        if let Some(cfg) = self.remote_config.as_ref() {
39	            let session = std::sync::Arc::new(tapa_xilinx::SshSession::new(
40	                cfg.clone(),
41	                tapa_xilinx::SshMuxOptions::default(),
42	            ));
43	            let runner = tapa_xilinx::RemoteToolRunner::new(session);
44	            f(&runner)
45	        } else {
46	            let runner = tapa_xilinx::LocalToolRunner::new();
47	            f(&runner)
48	        }
49	    }
50	
51	    pub fn switch_work_dir(&mut self, path: PathBuf) -> std::io::Result<()> {
52	        std::fs::create_dir_all(&path)?;
53	        let abs = absolutize_for_storage(&path);
54	        drop(path);
55	        self.work_dir = abs;
56	        Ok(())
57	    }
58	}
59	
60	/// Normalize a user-supplied `--work-dir` into an absolute path at
61	/// storage time. The remote transport rewrites absolute local paths
62	/// into the remote rootfs; a relative `./work.out` would sneak
63	/// through unrewritten, leaving the remote command looking for
64	/// `work.out/cpp/Foo.cpp` in its temporary cwd and failing.
65	///
66	/// Non-existent paths still get a plain `current_dir().join(...)` —
67	/// `canonicalize` would fail before the first step creates the
68	/// directory.
69	fn absolutize_for_storage(path: &std::path::Path) -> PathBuf {
70	    if path.is_absolute() {
71	        return path.to_path_buf();
72	    }
73	    let joined = std::env::current_dir()
74	        .unwrap_or_else(|_| PathBuf::from("."))
75	        .join(path);
76	    std::fs::canonicalize(&joined).unwrap_or(joined)
77	}

