152	    )?;
153	    let target_str = args.target.as_str();
154	    let stdout = run_tapacc(
155	        &tapacc,
156	        &flatten_files,
157	        &args.top,
158	        &all_cflags,
159	        target_str,
160	        work_dir,
161	    )?;
