  1	//! `tapa pack` orchestration.
  2	//!
  3	//! Reloads `<work_dir>/tapa.json`, projects the top
  4	//! task's external ports into a [`PackageXoInputs`] block, and drives
  5	//! `tapa_xilinx::pack_xo` against `<work_dir>/rtl` to produce the
  6	//! `.xo`. Three optional overlays are applied around the core pack:
  7	//!
  8	//! * `--custom-rtl <PATH>` (may repeat) — validate user-supplied
  9	//!   Verilog files against `<work_dir>/templates_info.json` and copy
 10	//!   them into `<work_dir>/rtl` before Vivado runs. An active floorplan
 11	//!   rejects this late RTL mutation.
 12	//! * `--bitstream-script <FILE>` — after `.xo` emission, render the
 13	//!   `get_vitis_script` helper and drop it at the requested
 14	//!   path (executable on Unix).
 15	//!
 16	//! The Vitis target emits an `.xo`; the HLS target emits a
 17	//! reproducible `.zip` archive.
 18	
 19	use std::path::{Path, PathBuf};
 20	
 21	use clap::Parser;
 22	use fs_err;
 23	use path_slash::PathExt;
 24	use tapa_ir::Target;
 25	
 26	use crate::context::CliContext;
 27	use crate::error::{CliError, Result};
 28	use crate::state::work::{self as work_io, WorkState};
 29	
 30	mod bitstream_script;
 31	mod custom_rtl;
 32	mod kernel_xml_ports;
 33	pub(crate) mod vitis_packaging;
 34	
 35	use custom_rtl::{apply_custom_rtl, load_templates_info};
 36	use vitis_packaging::pack_vitis;
 37	
 38	#[derive(Debug, Clone, Parser)]
 39	#[command(
 40	    name = "pack",
 41	    about = "Pack the generated RTL into a Xilinx object file."
 42	)]
 43	pub struct PackArgs {
 44	    /// Output `.xo` (Vitis target) or `.zip` (HLS target).
 45	    #[arg(short = 'o', long = "output", value_name = "FILE")]
 46	    pub output: Option<PathBuf>,
 47	
 48	    /// Bitstream-generation script path.
 49	    #[arg(short = 's', long = "bitstream-script", value_name = "FILE")]
 50	    pub bitstream_script: Option<PathBuf>,
 51	
 52	    /// Memory connectivity `.ini` (v++ `sp=` bank assignments). When set, the
 53	    /// emitted bitstream script adds it as a `--config`, so `v++ --link` binds
 54	    /// each M-AXI to its bank — required for HBM/DDR designs.
 55	    #[arg(long = "connectivity", value_name = "FILE")]
 56	    pub connectivity: Option<PathBuf>,
 57	
 58	    /// Custom RTL files / folders (may repeat; unavailable after floorplan).
 59	    #[arg(long = "custom-rtl", value_name = "PATH")]
 60	    pub custom_rtl: Vec<PathBuf>,
 61	}
 62	
 63	pub(super) fn published_floorplan_xdc(
 64	    work_dir: &Path,
 65	    state: &WorkState,
 66	) -> Result<Option<PathBuf>> {
 67	    if state.floorplan.is_none() {
 68	        return Ok(None);
 69	    }
 70	    let path = work_dir.join(crate::steps::floorplan::FLOORPLAN_XDC);
 71	    if !path.is_file() {
 72	        return Err(CliError::MissingState {
 73	            name: "published floorplan constraints (rerun `tapa floorplan`)".to_string(),
 74	            path,
 75	        });
 76	    }
 77	    Ok(Some(path))
 78	}
 79	
 80	/// Dispatch packaging according to the target stored by `analyze`.
 81	pub fn run(args: &PackArgs, ctx: &CliContext) -> Result<()> {
 82	    let state = work_io::load(&ctx.work_dir)?;
 83	    if !state.flow.synthed {
 84	        return Err(CliError::MissingState {
 85	            name: "completed synthesis (run `tapa synth` first)".to_string(),
 86	            path: work_io::path_in(&ctx.work_dir),
 87	        });
 88	    }
 89	    published_floorplan_xdc(&ctx.work_dir, &state)?;
 90	    if state.floorplan.is_some() && !args.custom_rtl.is_empty() {
 91	        return Err(CliError::InvalidArg(
 92	            "`--custom-rtl` cannot modify RTL after floorplanning; omit it or rerun synthesis and packaging without the active floorplan"
 93	                .to_string(),
 94	        ));
 95	    }
 96	    // The graph's `target` is the single home of the flow; this exhaustive
 97	    // match is the dispatch site a new `Target` variant would break.
 98	    match state.graph.target {
 99	        Target::XilinxVitis => pack_vitis(args, ctx, &state),
100	        Target::XilinxHls => pack_hls_zip(args, ctx, &state),
101	    }
102	}
103	
104	/// Package the `xilinx-hls` target. Bundles the synthesized RTL tree
105	/// under `rtl/`, every HLS
106	/// `_csynth.rpt` under `report/` (with timestamp redaction so the
107	/// archive is reproducible), the TAPA report yaml at the archive root
108	/// when the synth step emitted one, plus a verbatim copy of the
109	/// `tapa.json` state file carrying the compile context. Output
110	/// defaults to `work.zip` in the caller's CWD and is always normalized
111	/// to a `.zip` suffix.
112	/// Yield `(task_name, report_dir)` for every
113	/// `<work_dir>/hls/<task>/report/` directory. The zip and xo paths
114	/// both walk this layout; file selection, staging, and redaction stay
115	/// per-path.
116	pub(super) fn hls_task_report_dirs(work_dir: &Path) -> Result<Vec<(String, PathBuf)>> {
117	    let hls_root = work_dir.join("hls");
118	    let mut out = Vec::new();
119	    if !hls_root.is_dir() {
120	        return Ok(out);
121	    }
122	    for task_entry in fs_err::read_dir(&hls_root)? {
123	        let task_entry = task_entry?;
124	        if !task_entry.file_type()?.is_dir() {
125	            continue;
126	        }
127	        let report_dir = task_entry.path().join("report");
128	        if !report_dir.is_dir() {
129	            continue;
130	        }
131	        let task_name = task_entry.file_name().to_string_lossy().into_owned();
132	        out.push((task_name, report_dir));
133	    }
134	    Ok(out)
135	}
136	
137	fn pack_hls_zip(args: &PackArgs, ctx: &CliContext, state: &WorkState) -> Result<()> {
138	    use std::io::Write as _;
139	    let work_dir = ctx.work_dir.as_path();
140	    let rtl_dir = work_dir.join("rtl");
141	    if !rtl_dir.is_dir() {
142	        return Err(CliError::MissingState {
143	            name: "RTL directory (run `tapa synth` first)".to_string(),
144	            path: rtl_dir,
145	        });
146	    }
147	    if !args.custom_rtl.is_empty() {
148	        let templates = load_templates_info(&ctx.work_dir)?;
149	        apply_custom_rtl(&rtl_dir, &args.custom_rtl, &templates)?;
150	    }
151	    let output_path = enforce_zip_suffix(args.output.as_ref());
152	    if let Some(parent) = output_path.parent() {
153	        if !parent.as_os_str().is_empty() {
154	            fs_err::create_dir_all(parent)?;
155	        }
156	    }
157	    let file = fs_err::File::create(&output_path)?;
158	    let mut z = zip::ZipWriter::new(std::io::BufWriter::new(file));
159	    let opts: zip::write::FileOptions<'_, ()> =
160	        zip::write::FileOptions::default().compression_method(zip::CompressionMethod::Deflated);
161	
162	    let mut rtl_files: Vec<std::path::PathBuf> = Vec::new();
163	    for entry in walkdir::WalkDir::new(&rtl_dir) {
164	        let entry = entry.map_err(std::io::Error::other)?;
165	        if entry.file_type().is_file() {
166	            rtl_files.push(entry.path().to_path_buf());
167	        }
168	    }
169	    rtl_files.sort();
170	    for rtl_file in &rtl_files {
171	        let rel = rtl_file
172	            .strip_prefix(&rtl_dir)
173	            .map_err(|e| CliError::Archive(format!("rtl strip_prefix: {e}")))?;
174	        let name = format!("rtl/{}", rel.to_slash_lossy());
175	        z.start_file(name, opts)
176	            .map_err(|e| CliError::Archive(format!("zip entry: {e}")))?;
177	        z.write_all(&fs_err::read(rtl_file)?)?;
178	    }
179	
180	    // Include the TAPA report at archive root when synth emitted it.
181	    // Its absence does not make an otherwise complete RTL archive
182	    // invalid.
183	    let report_yaml = work_dir.join("report.yaml");
184	    if report_yaml.is_file() {
185	        z.start_file("report.yaml", opts)
186	            .map_err(|e| CliError::Archive(format!("zip entry: {e}")))?;
187	        z.write_all(&fs_err::read(&report_yaml)?)?;
188	    }
189	
190	    // The state file itself, byte-for-byte: one schema, one format, one
191	    // definition. `frt-cosim` parses this entry back with the very
192	    // `tapa_ir::WorkState` types written here, so the archive's compile
193	    // metadata cannot drift from the work dir's.
194	    z.start_file(work_io::FILE_NAME, opts)
195	        .map_err(|e| CliError::Archive(format!("zip entry: {e}")))?;
196	    z.write_all(&work_io::to_bytes(state)?)?;
197	
198	    // Store the curated per-task HLS `_csynth.rpt` files under
199	    // `report/<task>/<file>` and replace the per-run `Date:` line with the fixed
200	    // 1980-01-01 stamp so re-running HLS produces a byte-identical
201	    // archive (the same redaction `program.pack_xo` applies to xo).
202	    let task_report_dirs = hls_task_report_dirs(work_dir)?;
203	    if !task_report_dirs.is_empty() {
204	        let mut rpt_files: Vec<(std::path::PathBuf, String)> = Vec::new();
205	        for (task_name, report_root) in &task_report_dirs {
206	            for entry in walkdir::WalkDir::new(report_root) {
207	                let entry = entry.map_err(std::io::Error::other)?;
208	                if !entry.file_type().is_file() {
209	                    continue;
210	                }
211	                let path = entry.path();
212	                if !path
213	                    .file_name()
214	                    .and_then(|s| s.to_str())
215	                    .is_some_and(|n| n.ends_with("_csynth.rpt"))
216	                {
217	                    continue;
218	                }
219	                let rel = path
220	                    .strip_prefix(report_root)
221	                    .map_err(|e| CliError::Archive(format!("rpt strip_prefix: {e}")))?;
222	                let name = format!("report/{task_name}/{}", rel.to_slash_lossy());
223	                rpt_files.push((path.to_path_buf(), name));
224	            }
225	        }
226	        rpt_files.sort();
227	        for (rpt, name) in &rpt_files {
228	            z.start_file(name, opts)
229	                .map_err(|e| CliError::Archive(format!("zip entry: {e}")))?;
230	            z.write_all(&redact_rpt(&fs_err::read(rpt)?))?;
231	        }
232	    }
233	
234	    z.finish()
235	        .map_err(|e| CliError::Archive(format!("zip finish: {e}")))?;
236	    Ok(())
237	}
