219	            }
220	            other => panic!("expected Analyze, got {other:?}"),
221	        }
222	    }
223	
224	    #[test]
225	    fn flag_value_equal_to_subcommand_name_is_not_a_boundary() {
226	        // `synth` is the value of `--top`, not a chained subcommand
227	        // boundary.
228	        let cli = parse(&[
229	            "analyze", "--input", "a.cpp", "--top", "synth", "pack", "--output", "out.xo",
230	        ])
231	        .expect("flag value `synth` must not boundary the chunk");
232	        match cli.step {
233	            Some(Step::Analyze { args, chain_tail }) => {
234	                assert_eq!(args.top, "synth");
235	                assert_eq!(chain_tail.first().map(String::as_str), Some("pack"));
236	            }
237	            other => panic!("expected Analyze, got {other:?}"),
