240	
241	    #[test]
242	    fn global_flag_value_equal_to_subcommand_name_is_not_a_boundary() {
243	        let cli = parse(&["--work-dir", "synth", "version"])
244	            .expect("global `--work-dir synth` must not boundary on subcommand name");
245	        assert_eq!(
246	            cli.globals.work_dir.display().to_string(),
247	            "synth",
248	            "the literal `synth` must be captured as the work-dir value",
249	        );
250	        assert!(matches!(cli.step, Some(Step::Version { .. })));
251	    }
