 1	//! `tapa g++` — invokes `g++` with TAPA include and link flags.
 2	
 3	use std::path::PathBuf;
 4	use std::process::Command;
 5	
 6	use clap::Parser;
 7	
 8	use crate::context::CliContext;
 9	use crate::error::Result;
10	use crate::tapacc::cflags::{get_tapa_cflags, get_tapa_ldflags};
11	
12	#[derive(Debug, Parser)]
13	#[command(
14	    name = "g++",
15	    about = "Invoke g++ with TAPA include and library paths."
16	)]
17	pub struct GccArgs {
18	    /// Run the specified executable instead of `g++`.
19	    #[arg(long = "executable", default_value = "g++")]
20	    pub executable: PathBuf,
21	
22	    /// Pass-through arguments forwarded to `g++` verbatim.
23	    #[arg(trailing_var_arg = true, allow_hyphen_values = true)]
24	    pub argv: Vec<String>,
25	}
26	
27	pub fn run(args: &GccArgs, _ctx: &CliContext) -> Result<()> {
28	    let mut cmd = Command::new(&args.executable);
29	    cmd.arg("-std=c++17");
30	    cmd.arg("-DHLS_NO_XIL_FPO_LIB");
31	    cmd.args(get_tapa_cflags());
32	
33	    if let Some(include) = crate::util::vendor_hls_root().map(|r| r.join("include")) {
34	        cmd.arg(format!("-isystem{}", include.display()));
35	    }
36	
37	    cmd.args(&args.argv);
38	    cmd.args(get_tapa_ldflags());
39	
40	    let status = cmd.status()?;
41	    if !status.success() {
42	        std::process::exit(status.code().unwrap_or(1));
43	    }
44	    Ok(())
45	}

