  1	//! Per-task Vitis HLS invocation with parallel dispatch and
  2	//! mtime-based skipping.
  3	
  4	use camino::Utf8PathBuf;
  5	use rayon::prelude::*;
  6	use std::fs;
  7	use std::path::Path;
  8	
  9	use tapa_ir::{Design, SynthTarget};
 10	use tapa_xilinx::{run_hls_with_retry, run_hls_with_retry_in_stage, HlsJob, HlsOutput, ToolRunner};
 11	
 12	use crate::error::{CliError, Result};
 13	use crate::steps::synth::cpp_extract::cpp_path_for;
 14	
 15	use super::resolve_worker_count;
 16	
 17	/// Up to 3 attempts total. Vitis HLS occasionally fails with a
 18	/// transient `Pre-synthesis failed.` diagnostic that re-runs clean,
 19	/// so the retry wrapper keys off that substring.
 20	const HLS_MAX_ATTEMPTS: u32 = 3;
 21	
 22	#[derive(Debug, Clone)]
 23	pub struct TaskHlsLayout {
 24	    pub reports_dir: Utf8PathBuf,
 25	    pub hdl_dir: Utf8PathBuf,
 26	}
 27	
 28	impl TaskHlsLayout {
 29	    pub fn new(work_dir: &Path, task_name: &str) -> Self {
 30	        let base = work_dir.join("hls").join(task_name);
 31	        Self {
 32	            reports_dir: crate::util::utf8(base.join("report")),
 33	            hdl_dir: crate::util::utf8(base.join("verilog")),
 34	        }
 35	    }
 36	}
 37	
 38	#[derive(Debug, Clone)]
 39	pub struct HlsRunOptions {
 40	    pub part_num: String,
 41	    pub clock_period: String,
 42	    pub other_configs: String,
 43	    pub cflags: Vec<String>,
 44	    pub skip_based_on_mtime: bool,
 45	    /// Number of HLS runs executed in parallel. `None` or 1 → serial.
 46	    pub jobs: Option<u32>,
 47	    /// When `--keep-hls-work-dir` is set,
 48	    /// `run_hls` stages under `<work_dir>/hls/<task>/project` (kept
 49	    /// on disk) instead of a tempdir so the Vitis project + logs
 50	    /// survive after a failure.
 51	    pub keep_work_dir: bool,
 52	}
 53	
 54	/// Run HLS for every task that targets HLS — **all** tasks
 55	/// (not just leaves) — the upper-task shell is needed by codegen so
 56	/// the parent module's port surface is parseable. Tasks whose
 57	/// `target == "ignore"` are skipped (promotes them to
 58	/// `gen_templates`).
 59	pub fn run_hls_for_leaves(
 60	    runner: &dyn ToolRunner,
 61	    work_dir: &Path,
 62	    design: &Design,
 63	    options: &HlsRunOptions,
 64	) -> Result<Vec<(String, TaskHlsLayout, HlsOutput)>> {
 65	    // Plan pass: enumerate every task that needs HLS, resolve its
 66	    // layout + cpp source, and either record a cache-hit short-circuit
 67	    // or a live Vitis job. This keeps the parallel loop straightforward
 68	    // (just dispatch the live jobs) and preserves the original output
 69	    // order even when jobs run out-of-order.
 70	    let mut plan: Vec<(String, TaskHlsLayout, Work)> = Vec::new();
 71	    for (task_name, task) in &design.tasks {
 72	        if task.synth == SynthTarget::Ignore {
 73	            continue;
 74	        }
 75	        let layout = TaskHlsLayout::new(work_dir, task_name);
 76	
 77	        let cpp_source = cpp_path_for(work_dir, task_name);
 78	        let cpp_source = crate::util::utf8(cpp_source);
 79	        if !cpp_source.is_file() {
 80	            return Err(CliError::Codegen(format!(
 81	                "missing extracted C++ source `{}` for task `{task_name}`",
 82	                cpp_source.as_str(),
 83	            )));
 84	        }
 85	
 86	        // Check freshness before creating `layout.hdl_dir`, and require
 87	        // at least one `.v` file so a directory containing only generator
 88	        // sidecars is not a cache hit.
 89	        if options.skip_based_on_mtime && layout.hdl_dir.is_dir() {
 90	            let hdl_files = list_hdl_files(&layout.hdl_dir)?;
 91	            if hdl_files.iter().any(|path| is_verilog(path))
 92	                && hdl_files_are_newer_than(&hdl_files, &cpp_source)
 93	            {
 94	                log::info!(
 95	                    "skipping HLS for `{task_name}` (mtime cache hit at {})",
 96	                    layout.hdl_dir.as_str(),
 97	                );
 98	                // `reports_dir` must still exist for downstream
 99	                // readers; the skip path does not touch `hdl_dir`.
100	                fs::create_dir_all(&layout.reports_dir)?;
101	                // Reload existing csynth data so downstream report
102	                // generation and the persisted graph keep correct metrics.
103	                let csynth =
104	                    find_and_parse_csynth(&layout.reports_dir, task_name).unwrap_or_else(|e| {
105	                        log::warn!(
106	                            "could not reload cached csynth for `{task_name}`: {e}; using defaults"
107	                        );
108	                        tapa_xilinx::CsynthReport::default()
109	                    });
110	                let report_paths = walkdir::WalkDir::new(&layout.reports_dir)
111	                    .into_iter()
112	                    .filter_map(std::result::Result::ok)
113	                    .filter(|e| e.file_type().is_file())
114	                    .map(|e| crate::util::utf8(e.path()))
115	                    .collect();
116	                plan.push((
117	                    task_name.clone(),
118	                    layout,
119	                    Work::Skip(HlsOutput {
120	                        csynth,
121	                        verilog_files: hdl_files,
122	                        report_paths,
123	                        stdout: String::new(),
124	                        stderr: String::new(),
125	                    }),
126	                ));
127	                continue;
128	            }
129	        }
130	
131	        fs::create_dir_all(&layout.reports_dir)?;
132	        fs::create_dir_all(&layout.hdl_dir)?;
133	
134	        let job = HlsJob::builder()
135	            .task_name(task_name.clone())
136	            .cpp_source(cpp_source)
137	            .cflags(options.cflags.clone())
138	            .target_part(options.part_num.clone())
139	            .top_name(task_name.clone())
140	            .clock_period(options.clock_period.clone())
141	            .reports_out_dir(layout.reports_dir.clone())
142	            .hdl_out_dir(layout.hdl_dir.clone())
143	            .other_configs(options.other_configs.clone())
144	            .build();
145	
146	        // `--keep-hls-work-dir`: stage under
147	        // `<work_dir>/hls/<task>/project` so the Vitis project + logs
148	        // survive the run for post-mortem inspection. The retry
149	        // wrapper reuses that single dir across attempts (a
150	        // partially-failed `project/` may contaminate the next
151	        // attempt, but the operator opted in).
152	        //
153	        // Default path: hand the job off to `run_hls_with_retry`,
154	        // which allocates a *fresh* `tempfile::tempdir()` for every
155	        // attempt. Each transient `Pre-synthesis failed.` retry starts
156	        // from a clean project tree.
157	        let work = if options.keep_work_dir {
158	            let persistent =
159	                crate::util::utf8(work_dir.join("hls").join(task_name).join("project"));
160	            // Clear any leftover from a previous run so the first
161	            // attempt doesn't trip Vitis's project-already-open logic.
162	            if persistent.exists() {
163	                let _ = fs::remove_dir_all(&persistent);
164	            }
165	            fs::create_dir_all(&persistent)?;
166	            Work::RunInStage(job, persistent)
167	        } else {
168	            Work::RunFresh(job)
169	        };
170	
171	        plan.push((task_name.clone(), layout, work));
172	    }
173	
174	    let worker_count = resolve_worker_count(options.jobs, plan.len());
175	    let results: Vec<Result<Option<HlsOutput>>> = dispatch_plan(runner, &plan, worker_count);
176	
177	    // No explicit cleanup: `RunFresh` lets `run_hls_with_retry` own
178	    // its per-attempt tempdir and drop it. `RunInStage` is kept on
179	    // disk intentionally under `<work_dir>/hls/<task>/project`.
180	
181	    // Assemble output in the original plan order, surfacing the first
182	    // error.
183	    let mut out = Vec::with_capacity(plan.len());
184	    for ((task_name, layout, work), result) in plan.into_iter().zip(results) {
185	        let hls_out = match work {
186	            Work::Skip(pre) => pre,
187	            Work::RunInStage(..) | Work::RunFresh(_) => result?.expect("Run must yield Some"),
188	        };
189	        out.push((task_name, layout, hls_out));
190	    }
191	    Ok(out)
192	}
193	
194	fn dispatch_plan(
195	    runner: &dyn ToolRunner,
196	    plan: &[(String, TaskHlsLayout, Work)],
197	    worker_count: usize,
198	) -> Vec<Result<Option<HlsOutput>>> {
199	    let pool = rayon::ThreadPoolBuilder::new()
200	        .num_threads(worker_count.max(1))
201	        .build()
202	        .expect("rayon thread pool builds");
203	    pool.install(|| {
204	        plan.par_iter()
205	            .map(|(_, _, work)| work.execute(runner))
206	            .collect()
207	    })
208	}
209	
210	impl Work {
211	    fn execute(&self, runner: &dyn ToolRunner) -> Result<Option<HlsOutput>> {
212	        match self {
213	            Self::Skip(_) => Ok(None),
214	            Self::RunInStage(job, stage_dir) => {
215	                let out = run_hls_with_retry_in_stage(runner, job, HLS_MAX_ATTEMPTS, stage_dir)
216	                    .map_err(CliError::from)?;
217	                Ok(Some(out))
218	            }
219	            Self::RunFresh(job) => {
220	                // Each retry gets a fresh temporary staging directory.
221	                let out =
222	                    run_hls_with_retry(runner, job, HLS_MAX_ATTEMPTS).map_err(CliError::from)?;
223	                Ok(Some(out))
224	            }
225	        }
226	    }
227	}
228	
229	/// Internal work state for the plan pass. Kept module-private.
230	#[allow(
231	    clippy::large_enum_variant,
232	    reason = "Work is held briefly; \
233	    boxing adds allocations without removing the size difference \
234	    between the large `HlsJob + PathBuf` variant and the trivial Skip"
235	)]
236	enum Work {
237	    Skip(HlsOutput),
238	    /// `--keep-hls-work-dir`: persistent project under
239	    /// `<work_dir>/hls/<task>/project` reused across retries.
240	    RunInStage(HlsJob, Utf8PathBuf),
241	    /// Default: each retry attempt gets its own fresh tempdir so a
242	    /// partially-failed `project/` cannot contaminate the next try.
243	    RunFresh(HlsJob),
244	}
245	
246	fn hdl_files_are_newer_than(hdl_files: &[Utf8PathBuf], cpp_source: &camino::Utf8Path) -> bool {
247	    if hdl_files.is_empty() {
248	        return false;
249	    }
250	    let Ok(cpp_meta) = fs::metadata(cpp_source) else {
251	        return false;
252	    };
253	    let Ok(cpp_t) = cpp_meta.modified() else {
254	        return false;
255	    };
256	    hdl_files.iter().all(|hdl| {
257	        fs::metadata(hdl)
258	            .and_then(|metadata| metadata.modified())
259	            .is_ok_and(|hdl_t| hdl_t > cpp_t)
260	    })

