  1	//! Resource discovery for sibling TAPA tools and headers.
  2	//!
  3	//! The installed package places the CLI at `usr/bin/tapa` and shared
  4	//! resources under the same install prefix. Bazel runfiles and source-tree
  5	//! layouts are handled by walking parent directories and trying each resource
  6	//! suffix below.
  7	
  8	use std::path::{Path, PathBuf};
  9	use std::process::Command;
 10	use std::sync::OnceLock;
 11	
 12	use regex::Regex;
 13	
 14	use crate::error::{CliError, Result};
 15	
 16	/// Resource-name → candidate relative paths, in priority order: the
 17	/// first existing match wins.
 18	static POTENTIAL_PATHS: &[(&str, &[&str])] = &[
 19	    ("fpga-runtime-include", &["fpga-runtime", "usr/include"]),
 20	    (
 21	        "fpga-runtime-lib",
 22	        &["fpga-runtime/cargo", "fpga-runtime", "usr/lib"],
 23	    ),
 24	    (
 25	        "tapa-cpp-binary",
 26	        &["tapa-cpp/tapa-cpp", "usr/bin/tapa-cpp"],
 27	    ),
 28	    (
 29	        "tapa-extra-runtime-include",
 30	        &[
 31	            "tapa-system-include/tapa-extra-runtime-include",
 32	            "tapa-lib/extra-runtime-include",
 33	            "usr/include",
 34	        ],
 35	    ),
 36	    ("tapa-lib-include", &["tapa-lib", "usr/include"]),
 37	    ("tapa-lib-lib", &["tapa-lib", "usr/lib"]),
 38	    (
 39	        "tapa-system-include",
 40	        &[
 41	            "tapa-system-include/tapa-system-include",
 42	            "usr/share/tapa/system-include",
 43	        ],
 44	    ),
 45	    ("tapacc-binary", &["tapacc/tapacc", "usr/bin/tapacc"]),
 46	];
 47	
 48	/// Override the search anchor for tests: when the override is set, we
 49	/// walk its parents instead of the binary's parents.
 50	fn search_anchor() -> PathBuf {
 51	    static OVERRIDE: OnceLock<Option<PathBuf>> = OnceLock::new();
 52	    OVERRIDE
 53	        .get_or_init(|| std::env::var_os("TAPA_CLI_SEARCH_ANCHOR").map(PathBuf::from))
 54	        .clone()
 55	        .unwrap_or_else(|| {
 56	            std::env::current_exe()
 57	                .or_else(|_| std::env::current_dir())
 58	                .unwrap_or_else(|_| PathBuf::from("."))
 59	        })
 60	}
 61	
 62	/// Resolve a `POTENTIAL_PATHS` key to an absolute path. Walks the parents
 63	/// of [`search_anchor`] in order, trying each candidate suffix; the first
 64	/// existing path wins.
 65	pub fn find_resource(name: &str) -> Result<PathBuf> {
 66	    find_resource_from(name, &search_anchor())
 67	}
 68	
 69	/// Same as [`find_resource`] but with an explicit anchor (used in tests).
 70	pub fn find_resource_from(name: &str, anchor: &Path) -> Result<PathBuf> {
 71	    let suffixes = POTENTIAL_PATHS
 72	        .iter()
 73	        .find(|(k, _)| *k == name)
 74	        .map(|(_, v)| *v)
 75	        .ok_or_else(|| CliError::TapaccNotFound {
 76	            name: name.to_string(),
 77	            searched: format!("unknown resource key `{name}`"),
 78	        })?;
 79	
 80	    let mut tried: Vec<String> = Vec::new();
 81	    for suffix in suffixes {
 82	        for root in search_roots(anchor) {
 83	            let candidate = root.join(suffix);
 84	            if candidate.exists() {
 85	                return Ok(candidate);
 86	            }
 87	            tried.push(candidate.display().to_string());
 88	        }
 89	    }
 90	    Err(CliError::TapaccNotFound {
 91	        name: name.to_string(),
 92	        searched: tried.join(", "),
 93	    })
 94	}
 95	
 96	fn search_roots(anchor: &Path) -> Vec<PathBuf> {
 97	    let mut roots = Vec::new();
 98	    if let Some(prefix) = install_prefix_from_usr_bin(anchor) {
 99	        roots.push(prefix);
100	    }
101	
102	    let mut cursor = Some(anchor);
103	    while let Some(path) = cursor {
104	        push_unique(&mut roots, path.to_path_buf());
105	        cursor = path.parent();
106	    }
107	    roots
108	}
109	
110	fn install_prefix_from_usr_bin(anchor: &Path) -> Option<PathBuf> {
111	    let bin = anchor.parent()?;
112	    if bin.file_name()? != "bin" {
113	        return None;
114	    }
115	    let usr = bin.parent()?;
116	    if usr.file_name()? != "usr" {
117	        return None;
118	    }
119	    usr.parent().map(Path::to_path_buf)
120	}
121	
122	fn push_unique(paths: &mut Vec<PathBuf>, path: PathBuf) {
123	    if !paths.iter().any(|existing| existing == &path) {
124	        paths.push(path);
125	    }
126	}
127	
128	/// Resolve a clang-family helper (`tapacc-binary`, `tapa-cpp-binary`).
129	/// Verifies the resolved file prints a parseable `--version`; otherwise
130	/// surfaces a typed error.
131	pub fn find_clang_binary(name: &str) -> Result<PathBuf> {
132	    let path = find_resource(name)?;
133	    verify_clang_version(&path)?;
134	    Ok(path.canonicalize().unwrap_or(path))
135	}
136	
137	/// Require the literal `"version "` followed by at least one numeric
138	/// segment so unparseable
139	/// `--version` output (e.g. plain "ok") fails fast.
140	fn version_regex() -> &'static Regex {
141	    static RE: OnceLock<Regex> = OnceLock::new();
142	    RE.get_or_init(|| Regex::new(r"version (\d+)(\.\d+)*").expect("regex compile"))
143	}
144	
145	fn verify_clang_version(path: &Path) -> Result<()> {
146	    let output = Command::new(path).arg("--version").output().map_err(|e| {
147	        CliError::TapaccNotExecutable {
148	            path: path.to_path_buf(),
149	            reason: e.to_string(),
150	        }
151	    })?;
152	    if !output.status.success() {
153	        return Err(CliError::TapaccNotExecutable {
154	            path: path.to_path_buf(),
155	            reason: format!("`--version` exited {}", output.status),
156	        });
157	    }
158	    let stdout = String::from_utf8_lossy(&output.stdout);
159	    if version_regex().is_match(&stdout) {
160	        Ok(())
161	    } else {
162	        Err(CliError::TapaccNotExecutable {
163	            path: path.to_path_buf(),
164	            reason: format!(
165	                "`--version` output does not match `version (\\d+)(\\.\\d+)*`: {stdout}"
166	            ),
167	        })
168	    }
169	}
170	
171	#[cfg(test)]
172	mod tests {
173	    use super::*;
174	    use std::fs;
175	
176	    #[test]
177	    fn resolves_via_first_suffix() {
178	        let dir = tempfile::tempdir().unwrap();
179	        let nested = dir.path().join("nested/deep");
180	        fs::create_dir_all(&nested).unwrap();
181	        let target = dir.path().join("tapacc/tapacc");
182	        fs::create_dir_all(target.parent().unwrap()).unwrap();
183	        fs::write(&target, b"#!/bin/sh\nexit 0").unwrap();
184	
185	        let resolved = find_resource_from("tapacc-binary", &nested).unwrap();
186	        assert_eq!(resolved, target);
187	    }
188	
189	    #[test]
190	    fn falls_back_to_usr_layout() {
191	        let dir = tempfile::tempdir().unwrap();
192	        let nested = dir.path().join("nested");
193	        fs::create_dir_all(&nested).unwrap();
194	        let target = dir.path().join("usr/bin/tapacc");
195	        fs::create_dir_all(target.parent().unwrap()).unwrap();
196	        fs::write(&target, b"#!/bin/sh\nexit 0").unwrap();
197	
198	        let resolved = find_resource_from("tapacc-binary", &nested).unwrap();
199	        assert_eq!(resolved, target);
200	    }
201	
202	    #[test]
203	    fn direct_usr_bin_tapa_anchor_resolves_install_prefix_resources() {
204	        let dir = tempfile::tempdir().unwrap();
