214	        let resolved_cpp = find_resource_from("tapa-cpp-binary", &anchor).unwrap();
215	        assert_eq!(resolved_cpp, tapa_cpp);
216	        let resolved_include = find_resource_from("tapa-system-include", &anchor).unwrap();
