228	                "searched paths must mention the suffix; got `{searched}`",
229	            );
230	        } else {
231	            panic!("expected TapaccNotFound, got {err:?}");
232	        }
233	    }
234	
235	    #[test]
236	    fn unknown_resource_key_errors() {
237	        let dir = tempfile::tempdir().unwrap();
238	        let err = find_resource_from("does-not-exist", dir.path()).unwrap_err();
239	        assert!(matches!(err, CliError::TapaccNotFound { .. }));
240	    }
241	
