 1	//! `tapa version` — prints the contents of the `VERSION` file with no
 2	//! trailing newline.
 3	
 4	use std::io::Write;
 5	
 6	use clap::Parser;
 7	
 8	use crate::context::CliContext;
 9	use crate::error::Result;
10	
11	#[derive(Debug, Parser)]
12	#[command(name = "version", about = "Print TAPA version to standard output.")]
13	pub struct VersionArgs {}
14	
15	/// `VERSION` file content baked at compile time with the trailing
16	/// newline stripped (clap's `version = ...` attribute needs a
17	/// `&'static str` at parse time).
18	pub const VERSION: &str = {
19	    const RAW: &str = include_str!("../../../../VERSION");
20	    match const_str::strip_suffix!(RAW, "\n") {
21	        Some(s) => match const_str::strip_suffix!(s, "\r") {
22	            Some(s2) => s2,
23	            None => s,
24	        },
25	        None => RAW,
26	    }
27	};
28	
29	pub fn run(_args: &VersionArgs, _ctx: &CliContext) -> Result<()> {
30	    let mut stdout = std::io::stdout().lock();
31	    stdout.write_all(VERSION.as_bytes())?;
32	    Ok(())
33	}
34	
35	#[cfg(test)]
36	mod tests {
37	    use super::*;
38	
39	    #[test]
40	    fn version_is_non_empty_and_trimmed() {
41	        assert!(!VERSION.is_empty());
42	        assert!(!VERSION.starts_with(char::is_whitespace));
43	        assert!(!VERSION.ends_with(char::is_whitespace));
44	    }
45	
46	    #[test]
47	    fn version_uses_expected_format() {
48	        // The version is `major.minor.date[.patch]` — at least 3 segments.
49	        let segment_count = VERSION.split('.').count();
50	        assert!(segment_count >= 3, "version must have at least 3 segments");
51	    }
52	}

