  1	//! CFLAGS/LDFLAGS construction for compiling TAPA programs.
  2	//!
  3	//! The vendor include resolution and macOS sysroot probe live behind
  4	//! pluggable closures so unit tests can drive deterministic fixtures.
  5	
  6	use std::path::{Path, PathBuf};
  7	use std::process::Command;
  8	
  9	use crate::tapacc::discover::find_resource;
 10	
 11	/// Base TAPA include flags plus warning suppressions. Order is
 12	/// significant so vendor headers cascade correctly through `tapacc`.
 13	pub fn get_tapa_cflags() -> Vec<String> {
 14	    let mut flags = Vec::<String>::new();
 15	
 16	    if let Ok(tapa_lib_include) = find_resource("tapa-lib-include") {
 17	        if tapa_lib_include.join("tapa.h").exists() {
 18	            flags.push(format!("-isystem{}", tapa_lib_include.display()));
 19	            for resource in ["fpga-runtime-include", "tapa-extra-runtime-include"] {
 20	                if let Ok(extra) = find_resource(resource) {
 21	                    if extra != tapa_lib_include {
 22	                        flags.push(format!("-isystem{}", extra.display()));
 23	                    }
 24	                }
 25	            }
 26	        }
 27	    }
 28	
 29	    flags.extend(
 30	        [
 31	            "-Wno-attributes",
 32	            "-Wno-unknown-pragmas",
 33	            "-Wno-unused-label",
 34	            "-D__builtin_FILE()=__FILE__",
 35	            "-D__builtin_LINE()=__LINE__",
 36	        ]
 37	        .iter()
 38	        .map(ToString::to_string),
 39	    );
 40	
 41	    flags
 42	}
 43	
 44	/// Compose the CFLAGS that `tapacc` itself wants.
 45	pub fn get_tapacc_cflags(for_remote_hls: bool) -> Vec<String> {
 46	    let include_gcc = is_linux() || for_remote_hls;
 47	    let mut flags = Vec::<String>::new();
 48	
 49	    let vendor_paths = vendor_include_paths(include_gcc);
 50	    let mut vendor_flags: Vec<String> = vendor_paths
 51	        .iter()
 52	        .map(|p| format!("-isystem{}", p.display()))
 53	        .collect();
 54	
 55	    let nostdinc = !vendor_flags.is_empty() && include_gcc;
 56	    if nostdinc {
 57	        flags.push("-nostdinc++".to_string());
 58	    }
 59	    flags.extend(get_tapa_cflags());
 60	    flags.append(&mut vendor_flags);
 61	
 62	    if for_remote_hls && is_macos() {
 63	        flags.push(
 64	            "-D__assert_rtn(func,file,line,expr)=__assert_fail(expr,file,line,func)".to_string(),
 65	        );
 66	    }
 67	
 68	    flags
 69	}
 70	
 71	/// CFLAGS for remote-HLS C++ compilation.
 72	pub fn get_remote_hls_cflags() -> Vec<String> {
 73	    let mut flags = get_tapa_cflags();
 74	    if is_macos() {
 75	        flags.push(
 76	            "-D__assert_rtn(func,file,line,expr)=__assert_fail(expr,file,line,func)".to_string(),
 77	        );
 78	    }
 79	    flags
 80	}
 81	
 82	/// CFLAGS for compiling C++ with the system clang/llvm: `-isysroot`
 83	/// from `xcrun --show-sdk-path` on macOS plus
 84	/// `-idirafter <tapa-system-include>` if available.
 85	pub fn get_system_cflags() -> Vec<String> {
 86	    let mut flags = macos_sysroot_flags();
 87	    if let Ok(p) = find_resource("tapa-system-include") {
 88	        flags.push(format!("-idirafter{}", p.display()));
 89	    }
 90	    flags
 91	}
 92	
 93	/// LDFLAGS for linking TAPA programs.
 94	///
 95	/// Derives `-L` and
 96	/// `-Wl,-rpath` from `find_resource("fpga-runtime-lib")` /
 97	/// `find_resource("tapa-lib-lib")`, plus every external library
 98	/// directory the Bazel runfiles tree provides (gflags, glog, boost).
 99	/// Without the runfiles dirs, links from
100	/// the `bazel run //tapa-core:tapa -- g++` wrapper would fail to resolve
101	/// `-lgflags`, `-lglog`, etc.
102	pub fn get_tapa_ldflags() -> Vec<String> {
103	    use std::collections::BTreeSet;
104	    let mut libs: BTreeSet<PathBuf> = BTreeSet::new();
105	    if let Ok(p) = find_resource("fpga-runtime-lib") {
106	        libs.insert(p);
107	    }
108	    if let Ok(p) = find_resource("tapa-lib-lib") {
109	        libs.insert(p);
110	    }
111	    libs.extend(find_external_lib_in_runfiles());
112	    let mut out = Vec::<String>::new();
113	    for lib in &libs {
114	        out.push(format!("-Wl,-rpath,{}", lib.display()));
115	    }
116	    for lib in &libs {
117	        out.push(format!("-L{}", lib.display()));
118	    }
119	    // The `-lfrt_cpp` C++ shim is folded into libtapa; `-lfrt` now resolves to
120	    // the static libfrt.a (no shared libfrt.so is shipped). A shared library
121	    // used to carry FRT's native dependencies transitively — with static
122	    // linking they must be listed explicitly, after `-lfrt` (see
123	    // `rustc --print native-static-libs` for the `frt` crate).
124	    let mut names = vec![
125	        "tapa", "frt", "context", "thread", "glog", "gflags", "stdc++fs",
