  1	//! CFLAGS/LDFLAGS construction for compiling TAPA programs.
  2	//!
  3	//! The vendor include resolution and macOS sysroot probe live behind
  4	//! pluggable closures so unit tests can drive deterministic fixtures.
  5	
  6	use std::path::{Path, PathBuf};
  7	use std::process::Command;
  8	
  9	use crate::tapacc::discover::find_resource;
 10	
 11	/// Base TAPA include flags plus warning suppressions. Order is
 12	/// significant so vendor headers cascade correctly through `tapacc`.
 13	pub fn get_tapa_cflags() -> Vec<String> {
 14	    let mut flags = Vec::<String>::new();
 15	
 16	    if let Ok(tapa_lib_include) = find_resource("tapa-lib-include") {
 17	        if tapa_lib_include.join("tapa.h").exists() {
 18	            flags.push(format!("-isystem{}", tapa_lib_include.display()));
 19	            for resource in ["fpga-runtime-include", "tapa-extra-runtime-include"] {
 20	                if let Ok(extra) = find_resource(resource) {
 21	                    if extra != tapa_lib_include {
 22	                        flags.push(format!("-isystem{}", extra.display()));
 23	                    }
 24	                }
 25	            }
 26	        }
 27	    }
 28	
 29	    flags.extend(
 30	        [
 31	            "-Wno-attributes",
 32	            "-Wno-unknown-pragmas",
 33	            "-Wno-unused-label",
 34	            "-D__builtin_FILE()=__FILE__",
 35	            "-D__builtin_LINE()=__LINE__",
 36	        ]
 37	        .iter()
 38	        .map(ToString::to_string),
 39	    );
 40	
 41	    flags
 42	}
 43	
 44	/// Compose the CFLAGS that `tapacc` itself wants.
 45	pub fn get_tapacc_cflags(for_remote_hls: bool) -> Vec<String> {
 46	    let include_gcc = is_linux() || for_remote_hls;
 47	    let mut flags = Vec::<String>::new();
 48	
 49	    let vendor_paths = vendor_include_paths(include_gcc);
 50	    let mut vendor_flags: Vec<String> = vendor_paths
 51	        .iter()
 52	        .map(|p| format!("-isystem{}", p.display()))
 53	        .collect();
 54	
 55	    let nostdinc = !vendor_flags.is_empty() && include_gcc;
 56	    if nostdinc {
 57	        flags.push("-nostdinc++".to_string());
 58	    }
 59	    flags.extend(get_tapa_cflags());
 60	    flags.append(&mut vendor_flags);
 61	
 62	    if for_remote_hls && is_macos() {
 63	        flags.push(
 64	            "-D__assert_rtn(func,file,line,expr)=__assert_fail(expr,file,line,func)".to_string(),
 65	        );
 66	    }
 67	
 68	    flags
 69	}
