 71	/// CFLAGS for remote-HLS C++ compilation.
 72	pub fn get_remote_hls_cflags() -> Vec<String> {
 73	    let mut flags = get_tapa_cflags();
 74	    if is_macos() {
 75	        flags.push(
 76	            "-D__assert_rtn(func,file,line,expr)=__assert_fail(expr,file,line,func)".to_string(),
 77	        );
 78	    }
 79	    flags
 80	}
