 82	/// CFLAGS for compiling C++ with the system clang/llvm: `-isysroot`
 83	/// from `xcrun --show-sdk-path` on macOS plus
 84	/// `-idirafter <tapa-system-include>` if available.
 85	pub fn get_system_cflags() -> Vec<String> {
 86	    let mut flags = macos_sysroot_flags();
 87	    if let Ok(p) = find_resource("tapa-system-include") {
 88	        flags.push(format!("-idirafter{}", p.display()));
 89	    }
 90	    flags
 91	}
 92	
 93	/// LDFLAGS for linking TAPA programs.
 94	///
 95	/// Derives `-L` and
 96	/// `-Wl,-rpath` from `find_resource("fpga-runtime-lib")` /
 97	/// `find_resource("tapa-lib-lib")`, plus every external library
 98	/// directory the Bazel runfiles tree provides (gflags, glog, boost).
 99	/// Without the runfiles dirs, links from
100	/// the `bazel run //tapa-core:tapa -- g++` wrapper would fail to resolve
101	/// `-lgflags`, `-lglog`, etc.
102	pub fn get_tapa_ldflags() -> Vec<String> {
103	    use std::collections::BTreeSet;
104	    let mut libs: BTreeSet<PathBuf> = BTreeSet::new();
105	    if let Ok(p) = find_resource("fpga-runtime-lib") {
106	        libs.insert(p);
107	    }
108	    if let Ok(p) = find_resource("tapa-lib-lib") {
109	        libs.insert(p);
110	    }
111	    libs.extend(find_external_lib_in_runfiles());
112	    let mut out = Vec::<String>::new();
113	    for lib in &libs {
114	        out.push(format!("-Wl,-rpath,{}", lib.display()));
115	    }
116	    for lib in &libs {
117	        out.push(format!("-L{}", lib.display()));
118	    }
119	    // The `-lfrt_cpp` C++ shim is folded into libtapa; `-lfrt` now resolves to
120	    // the static libfrt.a (no shared libfrt.so is shipped). A shared library
121	    // used to carry FRT's native dependencies transitively — with static
122	    // linking they must be listed explicitly, after `-lfrt` (see
123	    // `rustc --print native-static-libs` for the `frt` crate).
124	    let mut names = vec![
125	        "tapa", "frt", "context", "thread", "glog", "gflags", "stdc++fs",
126	    ];
127	    if cfg!(target_os = "macos") {
128	        names.push("iconv");
129	    } else {
130	        names.extend(["OpenCL", "pthread", "dl", "rt", "m"]);
131	    }
132	    for name in names {
133	        out.push(format!("-l{name}"));
134	    }
135	    out
136	}
