  1	//! Vivado TCL runner for `vivado -mode batch -source <tcl>`.
  2	
  3	use camino::Utf8PathBuf;
  4	
  5	use crate::error::Result;
  6	use crate::runtime::process::{ToolInvocation, ToolRunner};
  7	
  8	#[derive(Debug, Clone)]
  9	pub struct VivadoJob {
 10	    pub tcl: String,
 11	    pub uploads: Vec<Utf8PathBuf>,
 12	    pub downloads: Vec<Utf8PathBuf>,
 13	    pub work_dir: Option<Utf8PathBuf>,
 14	    pub env: Vec<(String, String)>,
 15	    /// Arguments forwarded to the TCL script after `-tclargs`.
 16	    pub tclargs: Vec<String>,
 17	}
 18	
 19	impl VivadoJob {
 20	    pub fn new(tcl: impl Into<String>) -> Self {
 21	        Self {
 22	            tcl: tcl.into(),
 23	            uploads: Vec::new(),
 24	            downloads: Vec::new(),
 25	            work_dir: None,
 26	            env: Vec::new(),
 27	            tclargs: Vec::new(),
 28	        }
 29	    }
 30	}
 31	
 32	#[derive(Debug, Clone, Default)]
 33	pub struct VivadoOutput {
 34	    pub stdout: String,
 35	    pub stderr: String,
 36	    pub produced: Vec<Utf8PathBuf>,
 37	}
 38	
 39	pub(crate) fn build_invocation(job: &VivadoJob, tcl_path: &camino::Utf8Path) -> ToolInvocation {
 40	    let mut inv = ToolInvocation::new("vivado")
 41	        .arg("-mode")
 42	        .arg("batch")
 43	        .arg("-source")
 44	        .arg(tcl_path.as_str())
 45	        .arg("-nojournal")
 46	        .arg("-nolog");
 47	    if !job.tclargs.is_empty() {
 48	        inv = inv.arg("-tclargs");
 49	        for a in &job.tclargs {
 50	            inv = inv.arg(a.clone());
 51	        }
 52	    }
 53	    for (k, v) in &job.env {
 54	        inv = inv.env(k.clone(), v.clone());
 55	    }
 56	    if let Some(cwd) = job.work_dir.clone() {
 57	        inv.cwd = Some(cwd);
 58	    }
 59	    inv.uploads = job.uploads.clone();
 60	    inv.downloads = job.downloads.clone();
 61	    inv
 62	}
 63	
 64	/// Invoke Vivado via the provided runner. Writes the TCL script into a
 65	/// tempfile on the local side and points `vivado -source` at it.
 66	///
 67	/// When `job.work_dir` is unset, the runner allocates a per-call
 68	/// temporary directory and uses it as both `cwd` and `HOME`. Vivado
 69	/// otherwise writes `~/.Xilinx` state
 70	/// into the caller's home dir, which breaks under sandboxed or
 71	/// unwritable homes (e.g. Bazel exec) and races between parallel
 72	/// runs.
 73	pub fn run_vivado(runner: &dyn ToolRunner, job: &VivadoJob) -> Result<VivadoOutput> {
 74	    let tmp = tempfile::NamedTempFile::new()?;
 75	    std::fs::write(tmp.path(), job.tcl.as_bytes())?;
 76	    let tmp_path = crate::util::utf8(tmp.path());
 77	    let scratch = if job.work_dir.is_none() {
 78	        Some(tempfile::tempdir()?)
 79	    } else {
 80	        None
 81	    };
 82	    let mut inv = build_invocation(job, &tmp_path);
 83	    inv.uploads.push(tmp_path);
 84	    let home_dir = match (&job.work_dir, &scratch) {
 85	        (Some(p), _) => p.clone(),
 86	        (None, Some(t)) => {
 87	            let p = crate::util::utf8(t.path());
 88	            inv.cwd = Some(p.clone());
 89	            p
 90	        }
 91	        (None, None) => unreachable!("scratch tempdir is allocated when work_dir is None"),
 92	    };
 93	    inv.env.insert("HOME".into(), home_dir.as_str().to_string());
 94	    let out = runner.run(&inv)?;
 95	    if out.exit_code != 0 {
 96	        return Err(crate::error::XilinxError::ToolFailure {
 97	            program: "vivado".into(),
 98	            code: out.exit_code,
 99	            stderr: super::merged_failure_output(out.stdout, out.stderr),
100	        });
101	    }
102	    Ok(VivadoOutput {
103	        stdout: out.stdout,
104	        stderr: out.stderr,
105	        produced: job.downloads.clone(),
106	    })
107	}
108	
109	#[cfg(test)]
110	mod tests {
111	    use super::*;
112	    use crate::runtime::process::{MockToolRunner, ToolOutput};
113	
114	    #[test]
115	    fn run_vivado_builds_expected_invocation() {
116	        let runner = MockToolRunner::new();
117	        runner.push_ok("vivado", ToolOutput::default());
118	        let job = VivadoJob::new("puts hi\nexit");
119	        run_vivado(&runner, &job).unwrap();
120	        let call = &runner.calls()[0];
121	        assert_eq!(call.program, "vivado");
122	        assert!(call.args.contains(&"-mode".to_string()));
123	        assert!(call.args.contains(&"batch".to_string()));
124	        assert!(call.args.contains(&"-source".to_string()));
125	    }
126	
127	    #[test]
128	    fn run_vivado_surfaces_tool_failure() {
129	        let runner = MockToolRunner::new();
130	        runner.push_ok(
131	            "vivado",
132	            ToolOutput {
133	                exit_code: 1,
134	                stdout: "TCL command context".into(),
135	                stderr: "bad TCL".into(),
136	            },
137	        );
138	        let err = run_vivado(&runner, &VivadoJob::new("exit 1")).unwrap_err();
139	        let crate::error::XilinxError::ToolFailure {
140	            code,
141	            stderr: output,
142	            ..
143	        } = err
144	        else {
145	            panic!("expected tool failure");
146	        };
147	        assert_eq!(code, 1);
148	        assert!(output.contains("stdout:\nTCL command context"));
149	        assert!(output.contains("stderr:\nbad TCL"));
150	    }
151	}

