125	/// Build the `.xo` for the given inputs using the provided runner.
126	///
127	/// 1. Allocate a staging tempdir and emit `kernel.xml` into it.
128	/// 2. Render the packaging TCL with the kernel's `bus_ifaces`,
129	///    `cpp_kernels`, and `-part` argument, and invoke Vivado via
130	///    [`run_vivado`].
131	/// 3. Require that Vivado has produced the `.xo` at `kernel_out_path`.
132	/// 4. Run [`redact::redact_xo`] on the output so two invocations on the same
133	///    inputs are byte-equal.
134	///
135	/// `tclargs` to Vivado: `$tmpdir $hdl_dir $xo_file $kernel_xml_path`.
136	pub fn pack_xo(runner: &dyn ToolRunner, inputs: &PackageXoInputs) -> Result<Utf8PathBuf> {
137	    let out = pack_xo_without_redaction(runner, inputs)?;
138	    // Bundle the HLS report files (report.{json,yaml} +
139	    // `report/*_csynth.xml`) into the packaged `.xo` before the
140	    // reproducibility redaction pass; downstream inspection tooling
141	    // reads these archived reports.
142	    if !inputs.report_paths.is_empty() {
143	        bundle_report_paths_into_xo(&out, &inputs.report_paths)?;
144	    }
145	    redact::redact_xo(&out)?;
