149	/// Append each report into the `.xo` under its caller-provided archive
150	/// name. Any
151	/// existing archive entry with the same name is overwritten so callers
152	/// can use task-relative names (e.g. `report/<task>/csynth.xml`)
153	/// without colliding with the basename layout the raw `.xo` already
154	/// carries.
155	fn bundle_report_paths_into_xo(
156	    xo: &camino::Utf8Path,
157	    report_paths: &[(Utf8PathBuf, String)],
158	) -> Result<()> {
159	    use std::io::{Read, Write};
160	    if report_paths.is_empty() {
161	        return Ok(());
162	    }
163	    let raw = std::fs::read(xo)?;
164	    let mut z_in = zip::ZipArchive::new(std::io::Cursor::new(raw))
165	        .map_err(|e| XilinxError::XoRedaction(format!("open xo for bundling: {e}")))?;
166	    let tmp = tempfile::NamedTempFile::new_in(
167	        xo.parent()
168	            .unwrap_or_else(|| camino::Utf8Path::new("."))
169	            .as_std_path(),
170	    )?;
171	    let written: std::collections::HashSet<&str> =
172	        report_paths.iter().map(|(_, name)| name.as_str()).collect();
173	    {
174	        let mut z_out = zip::ZipWriter::new(tmp.reopen()?);
175	        let dir_opts = SimpleFileOptions::default()
176	            .compression_method(zip::CompressionMethod::Deflated)
177	            .unix_permissions(0o755);
178	        for i in 0..z_in.len() {
179	            let mut entry = z_in
180	                .by_index(i)
181	                .map_err(|e| XilinxError::XoRedaction(format!("read xo entry {i}: {e}")))?;
182	            let name = entry.name().to_owned();
183	            if written.contains(name.as_str()) {
184	                continue;
185	            }
186	            if name.ends_with('/') {
187	                z_out
188	                    .add_directory(name, dir_opts)
189	                    .map_err(|e| XilinxError::XoRedaction(format!("copy directory entry: {e}")))?;
190	                continue;
191	            }
192	            let file_opts = SimpleFileOptions::default()
193	                .compression_method(zip::CompressionMethod::Deflated)
194	                .unix_permissions(entry.unix_mode().unwrap_or(0o644) & 0o777);
195	            z_out
196	                .start_file(name, file_opts)
197	                .map_err(|e| XilinxError::XoRedaction(format!("start entry: {e}")))?;
198	            let mut buf = Vec::new();
199	            entry.read_to_end(&mut buf)?;
200	            z_out.write_all(&buf)?;
201	        }
202	        for (rpt, name) in report_paths {
203	            if !rpt.is_file() {
204	                continue;
205	            }
206	            z_out
207	                .start_file(
208	                    name.clone(),
209	                    SimpleFileOptions::default()
210	                        .compression_method(zip::CompressionMethod::Deflated)
211	                        .unix_permissions(0o644),
212	                )
213	                .map_err(|e| XilinxError::XoRedaction(format!("bundle entry: {e}")))?;
214	            z_out.write_all(&std::fs::read(rpt)?)?;
215	        }
216	        z_out
217	            .finish()
218	            .map_err(|e| XilinxError::XoRedaction(format!("finish bundled xo: {e}")))?;
219	    }
220	    tmp.persist(xo)
221	        .map_err(|e| XilinxError::XoRedaction(format!("persist bundled xo: {e}")))?;
222	    Ok(())
223	}
