225	/// Same as [`pack_xo`] but returns the raw Vivado-produced `.xo`
226	/// without running the reproducibility redaction pass. Primarily
227	/// useful for tests that need a pre-redaction artifact to exercise
228	/// [`redact::redact_xo`] directly.
229	#[doc(hidden)] // public only for integration tests
230	pub fn pack_xo_without_redaction(
231	    runner: &dyn ToolRunner,
232	    inputs: &PackageXoInputs,
233	) -> Result<Utf8PathBuf> {
234	    if !inputs.hdl_dir.is_dir() {
235	        return Err(XilinxError::KernelXml(format!(
236	            "pack_xo hdl_dir does not exist: {}",
237	            inputs.hdl_dir.as_str()
238	        )));
239	    }
240	    // The Vivado job runs with `cwd = tmp.path()`, so a relative
241	    // `--output` would end up inside the temp dir and vanish after
242	    // run_vivado returns (and the downstream `is_file` / redaction
243	    // check would miss it or pick up a stale file from the caller's
244	    // cwd). Absolutize before wiring the TCL args and the download
245	    // list so remote + local paths agree on one absolute target.
246	    let kernel_out_path = crate::util::absolutize(&inputs.kernel_out_path);
247	    let tmp = tempfile::tempdir()?;
248	    let kernel_xml_path = crate::util::utf8(tmp.path().join("kernel.xml"));
249	    let xml = emit_kernel_xml(&inputs.kernel_xml)?;
250	    std::fs::write(&kernel_xml_path, xml.as_bytes())?;
251	
252	    let s_axi = if inputs.s_axi_ifaces.is_empty() {
253	        PackageXoInputs::default_s_axi()
254	    } else {
255	        inputs.s_axi_ifaces.clone()
256	    };
257	    let m_axi = m_axi_port_names(&inputs.kernel_xml);
258	    let bus_ifaces = render_bus_ifaces(&s_axi, &m_axi, &inputs.m_axi_params);
259	    let cpp_kernels = render_cpp_kernels(&inputs.cpp_kernels);
260	    let tcl = format_package_xo_tcl(
261	        &inputs.top_name,
262	        &bus_ifaces,
263	        &cpp_kernels,
264	        &inputs.device_info.part_num,
265	    );
266	
267	    if let Some(parent) = kernel_out_path.parent() {
268	        std::fs::create_dir_all(parent)?;
269	    }
270	    let tmp_path = crate::util::utf8(tmp.path());
271	    let tclargs = [
272	        tmp_path.as_str().to_string(),
273	        inputs.hdl_dir.as_str().to_string(),
274	        kernel_out_path.as_str().to_string(),
275	        kernel_xml_path.as_str().to_string(),
276	    ];
277	
278	    let mut job = VivadoJob::new(tcl);
279	    job.work_dir = Some(tmp_path.clone());
280	    job.uploads = vec![inputs.hdl_dir.clone(), tmp_path, kernel_xml_path];
281	    if let Some(parent) = kernel_out_path.parent() {
282	        job.downloads = vec![parent.to_path_buf()];
283	    }
284	    job.tclargs = tclargs.to_vec();
285	
286	    let _out = run_vivado(runner, &job)?;
287	    if !kernel_out_path.is_file() {
288	        return Err(XilinxError::XoRedaction(format!(
289	            "pack_xo: Vivado returned success but {} is missing",
290	            kernel_out_path.as_str()
291	        )));
292	    }
293	    Ok(kernel_out_path)
294	}
