326	    /// A relative `--output` path is absolutized before reaching
327	    /// Vivado; otherwise the TCL writes the `.xo`
328	    /// into the per-invocation temp `cwd` while the post-run
329	    /// existence check looks in the caller's cwd.
330	    #[test]
331	    fn relative_xo_output_is_absolutized_for_tclargs() {
332	        use crate::runtime::process::ToolOutput;
333	        let tmp = tempfile::tempdir().unwrap();
334	        let hdl_dir = Utf8PathBuf::from_path_buf(tmp.path().join("hdl")).unwrap();
335	        std::fs::create_dir_all(&hdl_dir).unwrap();
336	        std::fs::write(hdl_dir.join("top.v"), b"// stub\n").unwrap();
337	        // Scope current-dir into the tmp so a relative output still
338	        // lands in a writable place.
339	        let orig_cwd = std::env::current_dir().unwrap();
340	        std::env::set_current_dir(tmp.path()).unwrap();
341	        // Stage a minimal .xo the mock runner will "produce".
342	        let staged = Utf8PathBuf::from_path_buf(tmp.path().join("__staged.xo")).unwrap();
343	        write_xo(&staged, &[("stub.txt", "ok")]);
344	        let staged_bytes = std::fs::read(&staged).unwrap();
345	
346	        let runner = MockToolRunner::new();
347	        runner.push_ok("vivado", ToolOutput::default());
348	        let expected_abs =
349	            Utf8PathBuf::from_path_buf(tmp.path().canonicalize().unwrap().join("out.xo")).unwrap();
350	        runner.attach_download(&expected_abs, staged_bytes);
351	
352	        let inputs = minimal_inputs(hdl_dir, Utf8PathBuf::from("out.xo"));
353	        let out = pack_xo(&runner, &inputs).unwrap();
354	
355	        std::env::set_current_dir(orig_cwd).unwrap();
356	        assert!(
357	            out.is_absolute(),
358	            "pack_xo must return an absolute path; got `{}`",
