191	            }
192	            let file_opts = SimpleFileOptions::default()
193	                .compression_method(zip::CompressionMethod::Deflated)
194	                .unix_permissions(entry.unix_mode().unwrap_or(0o644) & 0o777);
195	            z_out
196	                .start_file(name, file_opts)
197	                .map_err(|e| XilinxError::XoRedaction(format!("start entry: {e}")))?;
198	            let mut buf = Vec::new();
199	            entry.read_to_end(&mut buf)?;
200	            z_out.write_all(&buf)?;
201	        }
202	        for (rpt, name) in report_paths {
203	            if !rpt.is_file() {
204	                continue;
205	            }
206	            z_out
207	                .start_file(
208	                    name.clone(),
209	                    SimpleFileOptions::default()
210	                        .compression_method(zip::CompressionMethod::Deflated)
211	                        .unix_permissions(0o644),
212	                )
213	                .map_err(|e| XilinxError::XoRedaction(format!("bundle entry: {e}")))?;
214	            z_out.write_all(&std::fs::read(rpt)?)?;
215	        }
216	        z_out
217	            .finish()
218	            .map_err(|e| XilinxError::XoRedaction(format!("finish bundled xo: {e}")))?;
219	    }
220	    tmp.persist(xo)
221	        .map_err(|e| XilinxError::XoRedaction(format!("persist bundled xo: {e}")))?;
222	    Ok(())
223	}
224	
225	/// Same as [`pack_xo`] but returns the raw Vivado-produced `.xo`
226	/// without running the reproducibility redaction pass. Primarily
227	/// useful for tests that need a pre-redaction artifact to exercise
228	/// [`redact::redact_xo`] directly.
229	#[doc(hidden)] // public only for integration tests
230	pub fn pack_xo_without_redaction(
231	    runner: &dyn ToolRunner,
232	    inputs: &PackageXoInputs,
233	) -> Result<Utf8PathBuf> {
234	    if !inputs.hdl_dir.is_dir() {
235	        return Err(XilinxError::KernelXml(format!(
236	            "pack_xo hdl_dir does not exist: {}",
237	            inputs.hdl_dir.as_str()
238	        )));
239	    }
240	    // The Vivado job runs with `cwd = tmp.path()`, so a relative
241	    // `--output` would end up inside the temp dir and vanish after
242	    // run_vivado returns (and the downstream `is_file` / redaction
243	    // check would miss it or pick up a stale file from the caller's
244	    // cwd). Absolutize before wiring the TCL args and the download
245	    // list so remote + local paths agree on one absolute target.
246	    let kernel_out_path = crate::util::absolutize(&inputs.kernel_out_path);
247	    let tmp = tempfile::tempdir()?;
248	    let kernel_xml_path = crate::util::utf8(tmp.path().join("kernel.xml"));
249	    let xml = emit_kernel_xml(&inputs.kernel_xml)?;
250	    std::fs::write(&kernel_xml_path, xml.as_bytes())?;
251	
252	    let s_axi = if inputs.s_axi_ifaces.is_empty() {
253	        PackageXoInputs::default_s_axi()
254	    } else {
255	        inputs.s_axi_ifaces.clone()
256	    };
257	    let m_axi = m_axi_port_names(&inputs.kernel_xml);
258	    let bus_ifaces = render_bus_ifaces(&s_axi, &m_axi, &inputs.m_axi_params);
259	    let cpp_kernels = render_cpp_kernels(&inputs.cpp_kernels);
260	    let tcl = format_package_xo_tcl(
261	        &inputs.top_name,
262	        &bus_ifaces,
263	        &cpp_kernels,
264	        &inputs.device_info.part_num,
265	    );
266	
267	    if let Some(parent) = kernel_out_path.parent() {
268	        std::fs::create_dir_all(parent)?;
269	    }
270	    let tmp_path = crate::util::utf8(tmp.path());
271	    let tclargs = [
272	        tmp_path.as_str().to_string(),
273	        inputs.hdl_dir.as_str().to_string(),
274	        kernel_out_path.as_str().to_string(),
275	        kernel_xml_path.as_str().to_string(),
276	    ];
277	
278	    let mut job = VivadoJob::new(tcl);
279	    job.work_dir = Some(tmp_path.clone());
280	    job.uploads = vec![inputs.hdl_dir.clone(), tmp_path, kernel_xml_path];
281	    if let Some(parent) = kernel_out_path.parent() {
282	        job.downloads = vec![parent.to_path_buf()];
283	    }
284	    job.tclargs = tclargs.to_vec();
285	
286	    let _out = run_vivado(runner, &job)?;
287	    if !kernel_out_path.is_file() {
288	        return Err(XilinxError::XoRedaction(format!(
289	            "pack_xo: Vivado returned success but {} is missing",
290	            kernel_out_path.as_str()
291	        )));
292	    }
293	    Ok(kernel_out_path)
294	}
295	
296	#[cfg(test)]
297	mod tests {
298	    use super::*;
299	    use crate::runtime::process::MockToolRunner;
300	    use std::io::{Read, Write};
301	
302	    fn minimal_inputs(hdl_dir: Utf8PathBuf, kernel_out_path: Utf8PathBuf) -> PackageXoInputs {
303	        PackageXoInputs::builder()
304	            .top_name("k".into())
305	            .hdl_dir(hdl_dir)
306	            .device_info(DeviceInfo {
307	                part_num: "xcu250-figd2104-2L-e".into(),
308	                clock_period: "3.33".into(),
309	            })
310	            .clock_period("3.33".into())
311	            .kernel_xml(KernelXmlArgs {
312	                top_name: "k".into(),
313	                clock_period: "3.33".into(),
314	                ports: vec![KernelXmlPort {
315	                    name: "gmem0".into(),
316	                    category: PortCategory::MAxi,
317	                    width: 512,
318	                    port: String::new(),
319	                    ctype: "ap_uint<512>".into(),
320	                }],
321	            })
322	            .kernel_out_path(kernel_out_path)
323	            .build()
324	    }
325	
326	    /// A relative `--output` path is absolutized before reaching
327	    /// Vivado; otherwise the TCL writes the `.xo`
328	    /// into the per-invocation temp `cwd` while the post-run
329	    /// existence check looks in the caller's cwd.
330	    #[test]
331	    fn relative_xo_output_is_absolutized_for_tclargs() {
332	        use crate::runtime::process::ToolOutput;
333	        let tmp = tempfile::tempdir().unwrap();
334	        let hdl_dir = Utf8PathBuf::from_path_buf(tmp.path().join("hdl")).unwrap();
335	        std::fs::create_dir_all(&hdl_dir).unwrap();
336	        std::fs::write(hdl_dir.join("top.v"), b"// stub\n").unwrap();
337	        // Scope current-dir into the tmp so a relative output still
338	        // lands in a writable place.
339	        let orig_cwd = std::env::current_dir().unwrap();
340	        std::env::set_current_dir(tmp.path()).unwrap();
341	        // Stage a minimal .xo the mock runner will "produce".
342	        let staged = Utf8PathBuf::from_path_buf(tmp.path().join("__staged.xo")).unwrap();
343	        write_xo(&staged, &[("stub.txt", "ok")]);
344	        let staged_bytes = std::fs::read(&staged).unwrap();
345	
346	        let runner = MockToolRunner::new();
347	        runner.push_ok("vivado", ToolOutput::default());
348	        let expected_abs =
349	            Utf8PathBuf::from_path_buf(tmp.path().canonicalize().unwrap().join("out.xo")).unwrap();
350	        runner.attach_download(&expected_abs, staged_bytes);
351	
352	        let inputs = minimal_inputs(hdl_dir, Utf8PathBuf::from("out.xo"));
353	        let out = pack_xo(&runner, &inputs).unwrap();
354	
355	        std::env::set_current_dir(orig_cwd).unwrap();
356	        assert!(
357	            out.is_absolute(),
358	            "pack_xo must return an absolute path; got `{}`",
359	            out.as_str(),
360	        );

