  1	//! HLS report parsers: `csynth.xml` and utilization `.rpt`.
  2	//!
  3	//! `parse_csynth_xml` pulls the well-known top-level scalars that TAPA
  4	//! consumes (top module name, target part, target and estimated clock
  5	//! periods) out of the HLS report XML. `parse_utilization_rpt` walks
  6	//! Vivado's hierarchical ASCII table.
  7	
  8	use std::collections::HashMap;
  9	
 10	use indexmap::IndexMap;
 11	use serde::{Deserialize, Serialize};
 12	
 13	use crate::error::{Result, XilinxError};
 14	
 15	#[derive(Debug, Clone, Default, Serialize, Deserialize, PartialEq, Eq)]
 16	pub struct CsynthReport {
 17	    pub top: String,
 18	    pub part: String,
 19	    pub target_clock_period_ns: String,
 20	    pub estimated_clock_period_ns: String,
 21	    #[serde(default)]
 22	    pub area: IndexMap<String, String>,
 23	}
 24	
 25	#[derive(Debug, Clone, Default, Serialize, Deserialize, PartialEq, Eq)]
 26	pub struct UtilizationReport {
 27	    pub device: String,
 28	    pub instance: String,
 29	    pub metrics: HashMap<String, String>,
 30	    pub children: Vec<Self>,
 31	}
 32	
 33	#[derive(Debug, Deserialize)]
 34	struct CsynthXml {
 35	    #[serde(rename = "UserAssignments")]
 36	    user_assignments: UserAssignments,
 37	    #[serde(rename = "PerformanceEstimates")]
 38	    performance_estimates: PerformanceEstimates,
 39	    #[serde(rename = "AreaEstimates", default)]
 40	    area_estimates: Option<AreaEstimates>,
 41	}
 42	
 43	#[derive(Debug, Deserialize)]
 44	struct UserAssignments {
 45	    #[serde(rename = "TopModelName", default)]
 46	    top_model_name: Option<String>,
 47	    #[serde(rename = "TopModuleName", default)]
 48	    top_module_name: Option<String>,
 49	    #[serde(rename = "Part")]
 50	    part: String,
 51	    #[serde(rename = "TargetClockPeriod", default)]
 52	    target_clock_period: Option<String>,
 53	    #[serde(rename = "CTargetClockPeriod", default)]
 54	    c_target_clock_period: Option<String>,
 55	}
 56	
 57	#[derive(Debug, Deserialize)]
 58	struct PerformanceEstimates {
 59	    #[serde(rename = "SummaryOfTimingAnalysis")]
 60	    summary_of_timing_analysis: SummaryOfTimingAnalysis,
 61	}
 62	
 63	#[derive(Debug, Deserialize)]
 64	struct SummaryOfTimingAnalysis {
 65	    #[serde(rename = "EstimatedClockPeriod")]
 66	    estimated_clock_period: String,
 67	}
 68	
 69	#[derive(Debug, Deserialize)]
 70	struct AreaEstimates {
 71	    #[serde(rename = "Resources")]
 72	    resources: Option<Resources>,
 73	}
 74	
 75	#[derive(Debug, Deserialize)]
 76	struct Resources {
 77	    #[serde(rename = "BRAM_18K", default)]
 78	    bram_18k: Option<String>,
 79	    #[serde(rename = "DSP", default)]
 80	    dsp: Option<String>,
 81	    #[serde(rename = "FF", default)]
 82	    ff: Option<String>,
 83	    #[serde(rename = "LUT", default)]
 84	    lut: Option<String>,
 85	    #[serde(rename = "URAM", default)]
 86	    uram: Option<String>,
 87	}
 88	
 89	pub fn parse_csynth_xml(bytes: &[u8]) -> Result<CsynthReport> {
 90	    let parsed: CsynthXml = quick_xml::de::from_reader(bytes)
 91	        .map_err(|e| XilinxError::HlsReportParse(format!("csynth.xml parse failed: {e}")))?;
 92	
 93	    let top = parsed
 94	        .user_assignments
 95	        .top_model_name
 96	        .or(parsed.user_assignments.top_module_name)
 97	        .filter(|s| !s.trim().is_empty())
 98	        .ok_or_else(|| XilinxError::HlsReportParse("csynth.xml: TopModuleName not found".into()))?;
 99	
100	    let target_cp = parsed
101	        .user_assignments
102	        .target_clock_period
103	        .or(parsed.user_assignments.c_target_clock_period)
104	        .filter(|s| !s.trim().is_empty())
105	        .ok_or_else(|| {
106	            XilinxError::HlsReportParse("csynth.xml: TargetClockPeriod not found".into())
107	        })?;
108	
109	    let mut area = IndexMap::new();
110	    if let Some(ae) = parsed.area_estimates {
111	        if let Some(res) = ae.resources {
112	            if let Some(v) = res.bram_18k {
113	                area.insert("BRAM_18K".to_string(), v.trim().to_string());
114	            }
115	            if let Some(v) = res.dsp {
116	                area.insert("DSP".to_string(), v.trim().to_string());
117	            }
118	            if let Some(v) = res.ff {
119	                area.insert("FF".to_string(), v.trim().to_string());
120	            }
121	            if let Some(v) = res.lut {
122	                area.insert("LUT".to_string(), v.trim().to_string());
123	            }
124	            if let Some(v) = res.uram {
125	                area.insert("URAM".to_string(), v.trim().to_string());
126	            }
127	        }
128	    }
129	
130	    Ok(CsynthReport {
131	        top: top.trim().to_string(),
132	        part: parsed.user_assignments.part.trim().to_string(),
133	        target_clock_period_ns: target_cp.trim().to_string(),
134	        estimated_clock_period_ns: parsed
135	            .performance_estimates
136	            .summary_of_timing_analysis
137	            .estimated_clock_period
138	            .trim()
139	            .to_string(),
140	        area,
141	    })
142	}
