144	/// Parse a Vivado hierarchical utilization `.rpt`.
145	pub fn parse_utilization_rpt(text: &str) -> Result<UtilizationReport> {
146	    #[derive(Clone, Copy, PartialEq, Eq)]
147	    enum State {
148	        Prolog,
149	        Header,
150	        Body,
151	    }
152	
153	    let mut state = State::Prolog;
154	    let mut device = String::new();
155	    let mut schema: Vec<String> = Vec::new();
156	    let mut root: Option<UtilizationReport> = None;
157	    let mut stack: Vec<(usize, Vec<usize>)> = Vec::new(); // (depth, index path into root)
158	
159	    for raw in text.lines() {
160	        let line = raw.trim();
161	        let words: Vec<&str> = line.split_whitespace().collect();
162	        if words.len() == 4 && words[0..3] == ["|", "Device", ":"] {
163	            device = words[3].to_string();
164	            continue;
165	        }
166	        if is_ascii_table_rule(line) {
167	            state = match state {
168	                State::Prolog => State::Header,
169	                State::Header => State::Body,
170	                State::Body => break,
171	            };
172	            continue;
173	        }
174	
175	        match state {
176	            State::Header => {
177	                let (_, cols) = split_row(line);
178	                schema = cols.iter().map(|s| s.trim().to_string()).collect();
179	            }
180	            State::Body => {
181	                let (inst_raw, cols) = split_row(line);
182	                let depth = (inst_raw.len() - inst_raw.trim_start_matches(' ').len()) / 2;
183	                let instance = inst_raw.trim().to_string();
184	                if schema.len() != cols.len() {
185	                    return Err(XilinxError::HlsReportParse(
186	                        "utilization.rpt: column count mismatch".into(),
187	                    ));
188	                }
189	                let metrics: HashMap<String, String> = schema
190	                    .iter()
191	                    .cloned()
192	                    .zip(cols.into_iter().map(|s| s.trim().to_string()))
193	                    .collect();
194	
195	                let new = UtilizationReport {
196	                    device: device.clone(),
197	                    instance,
198	                    metrics,
199	                    children: Vec::new(),
200	                };
201	
202	                while stack.last().is_some_and(|(d, _)| *d >= depth) {
203	                    stack.pop();
204	                }
205	                if let Some((_, path)) = stack.last().cloned() {
206	                    let mut node = root.as_mut().unwrap();
207	                    for i in &path {
208	                        node = &mut node.children[*i];
209	                    }
210	                    node.children.push(new);
211	                    let idx = node.children.len() - 1;
212	                    let mut new_path = path;
213	                    new_path.push(idx);
214	                    stack.push((depth, new_path));
215	                } else {
216	                    root = Some(new);
217	                    stack.push((depth, Vec::new()));
218	                }
219	            }
220	            State::Prolog => {}
221	        }
222	    }
223	
224	    root.ok_or_else(|| XilinxError::HlsReportParse("utilization.rpt: no rows parsed".into()))
225	}
226	
227	fn split_row(line: &str) -> (&str, Vec<&str>) {
228	    let trimmed = line.trim().trim_matches('|');
229	    let mut parts = trimmed.split('|');
230	    let instance = parts.next().unwrap_or("");
231	    let cols: Vec<&str> = parts.collect();
232	    (instance, cols)
233	}
234	
235	fn is_ascii_table_rule(line: &str) -> bool {
236	    !line.is_empty()
237	        && line.starts_with('+')
238	        && line
239	            .chars()
240	            .all(|c| c == '+' || c == '-' || c.is_ascii_whitespace())
241	}
242	
243	#[cfg(test)]
244	mod tests {
245	    use super::*;
246	
247	    const CSYNTH: &str = "<?xml version=\"1.0\"?>
248	<profile>
249	  <UserAssignments>
250	    <TopModelName>vadd</TopModelName>
251	    <Part>xcu250-figd2104-2L-e</Part>
252	    <TargetClockPeriod>3.333</TargetClockPeriod>
253	  </UserAssignments>
254	  <PerformanceEstimates>
255	    <SummaryOfTimingAnalysis>
256	      <EstimatedClockPeriod>2.871</EstimatedClockPeriod>
257	    </SummaryOfTimingAnalysis>
258	  </PerformanceEstimates>
259	</profile>";
260	
261	    #[test]
262	    fn parses_csynth_top_fields() {
263	        let r = parse_csynth_xml(CSYNTH.as_bytes()).unwrap();
264	        assert_eq!(r.top, "vadd");
265	        assert_eq!(r.part, "xcu250-figd2104-2L-e");
266	        assert_eq!(r.target_clock_period_ns, "3.333");
267	        assert_eq!(r.estimated_clock_period_ns, "2.871");
268	        assert!(r.area.is_empty(), "fixture has no AreaEstimates");
269	    }
270	
271	    #[test]
272	    fn parses_csynth_area_fields() {
273	        let xml = "<?xml version=\"1.0\"?>\
274	<profile>\
275	  <UserAssignments>\
276	    <TopModelName>vadd</TopModelName>\
277	    <Part>xcu250-figd2104-2L-e</Part>\
278	    <TargetClockPeriod>3.333</TargetClockPeriod>\
279	  </UserAssignments>\
280	  <PerformanceEstimates>\
281	    <SummaryOfTimingAnalysis>\
282	      <EstimatedClockPeriod>2.871</EstimatedClockPeriod>\
283	    </SummaryOfTimingAnalysis>\
284	  </PerformanceEstimates>\
285	  <AreaEstimates>\
286	    <Resources>\
287	      <BRAM_18K>1</BRAM_18K>\
288	      <DSP>2</DSP>\
289	      <FF>3</FF>\
290	      <LUT>4</LUT>\
291	      <URAM>5</URAM>\
292	    </Resources>\
293	  </AreaEstimates>\
294	</profile>";
295	        let r = parse_csynth_xml(xml.as_bytes()).unwrap();
296	        assert_eq!(r.area.get("BRAM_18K"), Some(&"1".to_string()));
297	        assert_eq!(r.area.get("DSP"), Some(&"2".to_string()));
298	        assert_eq!(r.area.get("FF"), Some(&"3".to_string()));
299	        assert_eq!(r.area.get("LUT"), Some(&"4".to_string()));
300	        assert_eq!(r.area.get("URAM"), Some(&"5".to_string()));
301	    }
302	
303	    #[test]
304	    fn csynth_missing_field_is_typed_error() {
305	        let xml =
306	            "<profile><UserAssignments><TopModelName>k</TopModelName></UserAssignments></profile>";
307	        let err = parse_csynth_xml(xml.as_bytes()).unwrap_err();
308	        assert!(matches!(err, XilinxError::HlsReportParse(_)));
309	    }
310	
311	    const RPT: &str = "Hierarchical Utilization Report\n\
312	| Device : xcu250\n\
313	+----------+-------+------+\n\
314	| Instance | LUT   | REG  |\n\
315	+----------+-------+------+\n\
316	| top      | 100   | 200  |\n\
317	|   sub    | 30    | 40   |\n\
318	+----------+-------+------+\n";
319	
320	    #[test]
321	    fn parses_hierarchical_utilization() {
322	        let r = parse_utilization_rpt(RPT).unwrap();
323	        assert_eq!(r.device, "xcu250");
324	        assert_eq!(r.instance, "top");
325	        assert_eq!(r.metrics.get("LUT").unwrap(), "100");
326	        assert_eq!(r.children.len(), 1);
327	        assert_eq!(r.children[0].instance, "sub");
328	        assert_eq!(r.children[0].metrics.get("REG").unwrap(), "40");
329	    }
330	
331	    #[test]
332	    fn parses_vivado_report_with_banner_rules() {
333	        const RPT: &str = "\
334	Copyright 1986-2022 Xilinx, Inc. All Rights Reserved.\n\
335	--------------------------------------------------------------------\n\
336	| Tool Version : Vivado v.2024.2\n\
337	| Device       : xcv80-lsva4737-2MHP-e-S\n\
338	| Design State : Optimized\n\
339	--------------------------------------------------------------------\n\
340	\n\
341	Utilization Design Information\n\
342	\n\
343	+----------+--------+------------+-----+------+--------+--------+------+\n\
344	| Instance | Module | Total LUTs | FFs | URAM | RAMB36 | RAMB18 | DSP Blocks |\n\
345	+----------+--------+------------+-----+------+--------+--------+------+\n\
346	| Add      |  (top) |        107 | 140 |    0 |      0 |      0 |          1 |\n\
347	|   child  |    Add |          5 |   6 |    0 |      0 |      0 |          0 |\n\
348	+----------+--------+------------+-----+------+--------+--------+------+\n";
349	
350	        let r = parse_utilization_rpt(RPT).unwrap();
351	        assert_eq!(r.device, "xcv80-lsva4737-2MHP-e-S");
352	        assert_eq!(r.instance, "Add");
353	        assert_eq!(r.metrics.get("Total LUTs").unwrap(), "107");
354	        assert_eq!(r.metrics.get("FFs").unwrap(), "140");
355	        assert_eq!(r.metrics.get("DSP Blocks").unwrap(), "1");
356	        assert_eq!(r.children[0].instance, "child");
357	    }
358	}

