144	/// Parse a Vivado hierarchical utilization `.rpt`.
145	pub fn parse_utilization_rpt(text: &str) -> Result<UtilizationReport> {
146	    #[derive(Clone, Copy, PartialEq, Eq)]
147	    enum State {
148	        Prolog,
149	        Header,
150	        Body,
151	    }
152	
153	    let mut state = State::Prolog;
154	    let mut device = String::new();
155	    let mut schema: Vec<String> = Vec::new();
156	    let mut root: Option<UtilizationReport> = None;
157	    let mut stack: Vec<(usize, Vec<usize>)> = Vec::new(); // (depth, index path into root)
158	
159	    for raw in text.lines() {
160	        let line = raw.trim();
161	        let words: Vec<&str> = line.split_whitespace().collect();
162	        if words.len() == 4 && words[0..3] == ["|", "Device", ":"] {
163	            device = words[3].to_string();
164	            continue;
165	        }
166	        if is_ascii_table_rule(line) {
167	            state = match state {
168	                State::Prolog => State::Header,
169	                State::Header => State::Body,
170	                State::Body => break,
171	            };
172	            continue;
173	        }
174	
175	        match state {
176	            State::Header => {
177	                let (_, cols) = split_row(line);
178	                schema = cols.iter().map(|s| s.trim().to_string()).collect();
179	            }
180	            State::Body => {
181	                let (inst_raw, cols) = split_row(line);
182	                let depth = (inst_raw.len() - inst_raw.trim_start_matches(' ').len()) / 2;
183	                let instance = inst_raw.trim().to_string();
184	                if schema.len() != cols.len() {
185	                    return Err(XilinxError::HlsReportParse(
186	                        "utilization.rpt: column count mismatch".into(),
187	                    ));
188	                }
189	                let metrics: HashMap<String, String> = schema
190	                    .iter()
191	                    .cloned()
192	                    .zip(cols.into_iter().map(|s| s.trim().to_string()))
193	                    .collect();
194	
195	                let new = UtilizationReport {
196	                    device: device.clone(),
197	                    instance,
198	                    metrics,
199	                    children: Vec::new(),
200	                };
201	
202	                while stack.last().is_some_and(|(d, _)| *d >= depth) {
203	                    stack.pop();
204	                }
205	                if let Some((_, path)) = stack.last().cloned() {
206	                    let mut node = root.as_mut().unwrap();
207	                    for i in &path {
208	                        node = &mut node.children[*i];
209	                    }
210	                    node.children.push(new);
211	                    let idx = node.children.len() - 1;
212	                    let mut new_path = path;
213	                    new_path.push(idx);
214	                    stack.push((depth, new_path));
215	                } else {
216	                    root = Some(new);
217	                    stack.push((depth, Vec::new()));
218	                }
219	            }
220	            State::Prolog => {}
221	        }
222	    }
223	
224	    root.ok_or_else(|| XilinxError::HlsReportParse("utilization.rpt: no rows parsed".into()))
225	}
226	
227	fn split_row(line: &str) -> (&str, Vec<&str>) {
228	    let trimmed = line.trim().trim_matches('|');
229	    let mut parts = trimmed.split('|');
230	    let instance = parts.next().unwrap_or("");
231	    let cols: Vec<&str> = parts.collect();
232	    (instance, cols)
233	}
234	
235	fn is_ascii_table_rule(line: &str) -> bool {
236	    !line.is_empty()
237	        && line.starts_with('+')
238	        && line
239	            .chars()
240	            .all(|c| c == '+' || c == '-' || c.is_ascii_whitespace())
241	}
