 38	fn expand_tilde(p: &Utf8PathBuf) -> Utf8PathBuf {
 39	    let s = p.as_str();
 40	    let expanded = shellexpand::tilde(s);
 41	    Utf8PathBuf::from(expanded.as_ref())
 42	}
