159	/// Canonical rule used everywhere we need a remote `xilinx_settings`
160	/// path: prefer an explicit settings script, otherwise treat a
161	/// tool-root value as `<root>/settings64.sh`. The Rust layer only
162	/// ever `source`s the resulting path, so handing it a directory —
163	/// as `VARS.local.bzl`'s `REMOTE_XILINX_TOOL_PATH` commonly does —
164	/// would otherwise silently fail at bash-time.
165	#[must_use]
166	pub(crate) fn resolve_xilinx_settings(
167	    explicit_settings: Option<&str>,
168	    tool_root: Option<&str>,
169	) -> Option<String> {
170	    if let Some(s) = explicit_settings {
171	        let s = s.trim();
172	        if !s.is_empty() {
173	            return Some(s.to_string());
174	        }
175	    }
176	    if let Some(root) = tool_root {
177	        let root = root.trim();
178	        if root.is_empty() {
179	            return None;
180	        }
181	        // Already looks like a settings script (file ending in .sh)?
182	        // Leave it alone so pointing at a custom path still works.
183	        if root.ends_with(".sh") {
184	            return Some(root.to_string());
185	        }
186	        let trimmed = root.trim_end_matches('/');
187	        return Some(format!("{trimmed}/settings64.sh"));
188	    }
189	    None
190	}
