106	/// Apply the raw metrics reported by HLS to a task.
107	///
108	/// `clock_period` stores the achieved estimate, not the requested target.
109	/// `total_area` is cleared because it is either re-populated by optional
110	/// out-of-context synthesis or derived recursively from `self_area` by report
111	/// and topology consumers.
112	fn apply_hls_metrics(task: &mut Task, report: &CsynthReport) {
113	    task.clock_period
114	        .clone_from(&report.estimated_clock_period_ns);
115	    task.self_area.clear();
116	    task.total_area.clear();
117	    for (key, value) in &report.area {
118	        if let Ok(value) = value.parse::<i64>() {
119	            task.self_area.insert(key.clone(), Value::from(value));
120	        } else {
121	            task.self_area
122	                .insert(key.clone(), Value::String(value.clone()));
123	        }
124	    }
125	}
