  1	//! Remote-config bootstrap for the `tapa` CLI entry.
  2	//!
  3	//! Resolution happens in three stages:
  4	//!
  5	//! 1. `load_remote_config(remote_host)` — read `~/.taparc` (YAML),
  6	//!    optionally splice in `--remote-host=user@host[:port]`. Returns
  7	//!    `None` when neither source provides a `host`.
  8	//! 2. `_apply_remote_overrides(...)` — overlay the remaining
  9	//!    `--remote-*` CLI flags onto the loaded config. CLI wins.
 10	//! 3. `sync_remote_vendor_includes(config)` — when a config is
 11	//!    active, mirror `$XILINX_HLS/include` (and `gcc-*/include`)
 12	//!    into a local cache and export `XILINX_HLS` / `XILINX_VITIS`
 13	//!    via `setenv`-with-default semantics. Sync failures are
 14	//!    non-fatal: the loader logs a warning and continues so
 15	//!    the in-tree `tapacc` flow can still run.
 16	//!
 17	//! The `~/.taparc` location is resolved via:
 18	//!   - `TAPA_RC_PATH` env var (test override), then
 19	//!   - `$HOME/.taparc`, then
 20	//!   - silently skipped if `HOME` is unset.
 21	//!
 22	//! The function is deliberately small — anything more complex belongs
 23	//! in `tapa-xilinx` (where the `RemoteConfig` schema lives).
 24	
 25	use camino::Utf8PathBuf;
 26	use std::path::{Path, PathBuf};
 27	
 28	use tapa_xilinx::{sync_remote_vendor_includes, RemoteConfig, SshMuxOptions, SshSession};
 29	
 30	use crate::error::{CliError, Result};
 31	use crate::globals::GlobalArgs;
 32	
 33	/// Env var consulted before falling back to `$HOME/.taparc`. Tests use
 34	/// this to point the loader at a temporary directory; production users
 35	/// do not need to set it.
 36	pub const TAPARC_PATH_ENV: &str = "TAPA_RC_PATH";
 37	
 38	/// Resolve the on-disk path to `~/.taparc`. Returns `None` when neither
 39	/// `TAPA_RC_PATH` nor `HOME` is set.
 40	fn taparc_path() -> Option<PathBuf> {
 41	    if let Some(p) = std::env::var_os(TAPARC_PATH_ENV) {
 42	        return Some(PathBuf::from(p));
 43	    }
 44	    std::env::var_os("HOME").map(|h| PathBuf::from(h).join(".taparc"))
 45	}
 46	
 47	/// Parse `user@host[:port]` into the three optional pieces.
 48	fn parse_remote_host_spec(spec: &str) -> std::result::Result<RemoteHostSpec, String> {
 49	    let (user, rest) = match spec.split_once('@') {
 50	        Some((u, r)) => (Some(u.to_string()), r),
 51	        None => (None, spec),
 52	    };
 53	    let (host, port) = match rest.rsplit_once(':') {
 54	        Some((h, p)) => {
 55	            let port: u16 = p
 56	                .parse()
 57	                .map_err(|e| format!("invalid port `{p}` in `--remote-host`: {e}"))?;
 58	            (h.to_string(), Some(port))
 59	        }
 60	        None => (rest.to_string(), None),
 61	    };
 62	    if host.is_empty() {
 63	        return Err(format!("`--remote-host` is missing a host: `{spec}`"));
 64	    }
 65	    Ok(RemoteHostSpec { user, host, port })
 66	}
 67	
 68	#[derive(Debug)]
 69	struct RemoteHostSpec {
 70	    user: Option<String>,
 71	    host: String,
 72	    port: Option<u16>,
 73	}
 74	
 75	/// Read `~/.taparc` and return the `remote` mapping as a YAML value.
 76	/// Returns `None` when the file is absent, unreadable, malformed, or
 77	/// its `remote:` section is missing. Every one of these cases is
 78	/// deliberately non-fatal (warn and continue): a stale `~/.taparc`
 79	/// must not block unrelated commands like `tapa version`.
 80	fn load_taparc_remote_section(path: &Path) -> Option<serde_yaml::Value> {
 81	    let text = match std::fs::read_to_string(path) {
 82	        Ok(t) => t,
 83	        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return None,
 84	        Err(e) => {
 85	            log::warn!("ignoring `{}`: {}", path.display(), e);
 86	            return None;
 87	        }
 88	    };
 89	    let value: serde_yaml::Value = match serde_yaml::from_str(&text) {
 90	        Ok(v) => v,
 91	        Err(e) => {
 92	            log::warn!(
 93	                "ignoring `{}`: invalid YAML ({e}); proceeding without remote config",
 94	                path.display(),
 95	            );
 96	            return None;
 97	        }
 98	    };
 99	    let map = match value {
100	        serde_yaml::Value::Mapping(m) => m,
101	        serde_yaml::Value::Null => return None,
102	        other @ (serde_yaml::Value::Bool(_)
103	        | serde_yaml::Value::Number(_)
104	        | serde_yaml::Value::String(_)
105	        | serde_yaml::Value::Sequence(_)
106	        | serde_yaml::Value::Tagged(_)) => {
107	            log::warn!(
108	                "ignoring `{}`: expected a top-level YAML mapping, got {other:?}",
109	                path.display(),
110	            );
111	            return None;
112	        }
113	    };
114	    map.get("remote").cloned()
115	}
116	
117	/// Splice the CLI `--remote-host=user@host[:port]` triple into a YAML
118	/// mapping (creating one if needed). The CLI value wins on every key.
119	fn apply_remote_host_to_yaml(
120	    base: Option<serde_yaml::Value>,
121	    spec: &RemoteHostSpec,
122	) -> serde_yaml::Mapping {
123	    let mut map = match base {
124	        Some(serde_yaml::Value::Mapping(m)) => m,
125	        _ => serde_yaml::Mapping::new(),
126	    };
127	    map.insert(
128	        serde_yaml::Value::String("host".into()),
129	        serde_yaml::Value::String(spec.host.clone()),
130	    );
131	    if let Some(u) = spec.user.as_ref() {
132	        map.insert(
133	            serde_yaml::Value::String("user".into()),
134	            serde_yaml::Value::String(u.clone()),
135	        );
136	    }
137	    if let Some(p) = spec.port {
138	        map.insert(
139	            serde_yaml::Value::String("port".into()),
140	            serde_yaml::Value::Number(serde_yaml::Number::from(p)),
141	        );
142	    }
143	    map
144	}
145	
146	/// Apply non-host CLI overrides to the resolved remote configuration.
147	fn apply_cli_overrides(cfg: &mut RemoteConfig, globals: &GlobalArgs) {
148	    if let Some(p) = globals.remote_key_file.as_deref() {
149	        cfg.key_file = Some(crate::util::utf8(shellexpand::tilde(p).into_owned()));
150	    }
151	    if let Some(s) = globals.remote_xilinx_settings.as_deref() {
152	        cfg.xilinx_settings = Some(s.to_string());
153	    }
154	    if let Some(d) = globals.remote_ssh_control_dir.as_deref() {
155	        cfg.ssh_control_dir = Some(crate::util::utf8(shellexpand::tilde(d).into_owned()));
156	    }
157	    if let Some(p) = globals.remote_ssh_control_persist.as_deref() {
158	        cfg.ssh_control_persist = p.to_string();
159	    }
160	    if globals.remote_disable_ssh_mux {
161	        cfg.ssh_multiplex = false;
162	    }
163	}
