165	/// Build the active `RemoteConfig` (or `None`) from `~/.taparc` plus
166	/// the CLI override flags. Pure: does not touch the network or env.
167	pub fn build_remote_config(globals: &GlobalArgs) -> Result<Option<RemoteConfig>> {
168	    let cli_spec = match globals.remote_host.as_deref() {
169	        Some(s) => Some(parse_remote_host_spec(s).map_err(CliError::InvalidArg)?),
170	        None => None,
171	    };
172	
173	    let file_remote = taparc_path().and_then(|p| load_taparc_remote_section(&p));
174	
175	    if cli_spec.is_none() && file_remote.is_none() {
176	        return Ok(None);
177	    }
178	
179	    let map = match cli_spec.as_ref() {
180	        Some(spec) => apply_remote_host_to_yaml(file_remote, spec),
181	        None => match file_remote {
182	            Some(serde_yaml::Value::Mapping(m)) => m,
183	            _ => return Ok(None),
184	        },
185	    };
186	
187	    if !map.contains_key(serde_yaml::Value::String("host".into())) {
188	        return Ok(None);
189	    }
190	
191	    // Re-emit the spliced mapping under `remote:` so we can reuse the
192	    // canonical `RemoteConfig::from_yaml_str` path-expansion + default
193	    // logic that lives in `tapa-xilinx`.
194	    let mut top = serde_yaml::Mapping::new();
195	    top.insert(
196	        serde_yaml::Value::String("remote".into()),
197	        serde_yaml::Value::Mapping(map),
198	    );
199	    let yaml_text = serde_yaml::to_string(&serde_yaml::Value::Mapping(top)).map_err(|e| {
200	        CliError::RemoteConfigParse {
201	            path: PathBuf::from("<merged>"),
202	            message: e.to_string(),
203	        }
204	    })?;
205	    let mut cfg =
206	        RemoteConfig::from_yaml_str(&yaml_text, Utf8PathBuf::from("<merged>")).map_err(|e| {
207	            CliError::RemoteConfigParse {
208	                path: PathBuf::from("<merged>"),
209	                message: e.to_string(),
210	            }
211	        })?;
212	    apply_cli_overrides(&mut cfg, globals);
213	    Ok(Some(cfg))
214	}
215	
216	/// Side effects after a config is resolved: sync vendor includes from
217	/// the remote and export `XILINX_HLS`/`XILINX_VITIS` defaults into the
218	/// process environment. Sync failures are logged and swallowed so test
219	/// environments without SSH still run.
220	fn sync_and_export_env(cfg: &RemoteConfig) {
221	    let session = SshSession::new(cfg.clone(), SshMuxOptions::default());
222	    match sync_remote_vendor_includes(&session) {
223	        Ok(cache_dir) => {
224	            let s = cache_dir.as_str().to_string();
225	            // `setdefault` semantics: never clobber an explicit
226	            // `XILINX_HLS=...` already exported by the user.
227	            if std::env::var_os("XILINX_HLS").is_none() {
228	                std::env::set_var("XILINX_HLS", &s);
229	            }
230	            if std::env::var_os("XILINX_VITIS").is_none() {
231	                std::env::set_var("XILINX_VITIS", &s);
232	            }
233	        }
234	        Err(e) => {
235	            log::warn!("remote vendor-header sync failed: {e}");
236	        }
237	    }
238	}
239	
240	/// Top-level bootstrap. Reads `~/.taparc`, applies CLI overrides,
241	/// triggers the vendor-include sync, exports `XILINX_HLS` /
242	/// `XILINX_VITIS`, and returns the active config (or `None`).
243	pub fn bootstrap_remote(globals: &GlobalArgs) -> Result<Option<RemoteConfig>> {
244	    let cfg = build_remote_config(globals)?;
245	    if let Some(c) = cfg.as_ref() {
246	        log::info!(
247	            "using remote host {}@{}:{} for vendor tools",
248	            c.user,
249	            c.host,
250	            c.port,
251	        );
252	        sync_and_export_env(c);
253	    }
254	    Ok(cfg)
255	}
