 98	#[cfg(test)]
 99	mod tests {
100	    use super::*;
101	    use std::collections::BTreeMap;
102	
103	    use tapa_ir::{SynthTarget, Target, Task, TaskGraph, TaskLevel};
104	
105	    fn sample_state() -> WorkState {
106	        let mut tasks = BTreeMap::new();
107	        tasks.insert(
108	            "Top".to_string(),
109	            Task {
110	                level: TaskLevel::Lower,
111	                code: "void Top() {}".to_string(),
112	                ports: Vec::new(),
113	                tasks: BTreeMap::new(),
114	                fifos: BTreeMap::new(),
115	                readable_name: "Top".to_string(),
116	                synth: SynthTarget::Hls,
117	                self_area: indexmap::IndexMap::new(),
118	                total_area: indexmap::IndexMap::new(),
119	                clock_period: "0".to_string(),
120	            },
121	        );
122	        WorkState::new(TaskGraph {
123	            top: "Top".to_string(),
124	            target: Target::XilinxHls,
125	            tasks,
126	            cflags: Vec::new(),
127	        })
128	    }
129	
130	    #[test]
131	    fn round_trip_via_disk() {
132	        let dir = tempfile::tempdir().expect("tempdir");
133	        let mut state = sample_state();
134	        state.flow.part_num = Some("xcvu37p".to_string());
135	        state.flow.clock_period = Some("3.33".to_string());
136	        state.flow.synthed = true;
137	        store(dir.path(), &state).expect("store");
138	        let loaded = load(dir.path()).expect("load");
139	        assert_eq!(loaded, state);
140	    }
141	
142	    #[test]
143	    fn missing_state_is_typed_error() {
144	        let dir = tempfile::tempdir().expect("tempdir");
145	        let err = load(dir.path()).expect_err("must fail");
146	        assert!(
147	            matches!(err, CliError::MissingState { ref name, .. } if name == FILE_NAME),
148	            "missing tapa.json must surface as MissingState; got {err}",
149	        );
150	    }
151	
152	    #[test]
153	    fn stored_state_is_pretty_printed() {
154	        let dir = tempfile::tempdir().expect("tempdir");
155	        store(dir.path(), &sample_state()).expect("store");
156	        let raw = fs_err::read_to_string(path_in(dir.path())).expect("read");
157	        assert!(
158	            raw.starts_with("{\n  \"version\": 3,\n"),
159	            "state file must be pretty-printed for human diffing; got {raw}",
160	        );
161	        assert!(raw.ends_with("}\n"), "state file must end with a newline");
162	    }
163	
164	    #[test]
165	    fn stored_bytes_are_the_packed_bytes() {
166	        // `pack` puts `to_bytes` into the archive; if it ever diverged from
167	        // what `store` writes, the archive and the work dir would carry two
168	        // different serializations of one schema.
169	        let dir = tempfile::tempdir().expect("tempdir");
170	        let state = sample_state();
171	        store(dir.path(), &state).expect("store");
172	        let on_disk = fs_err::read(path_in(dir.path())).expect("read");
173	        assert_eq!(
174	            on_disk,
175	            to_bytes(&state).expect("to_bytes"),
176	            "the archive entry and the work-dir file must be the same bytes",
177	        );
178	    }
179	
180	    #[test]
181	    fn foreign_version_is_typed_error_not_serde_noise() {
182	        let dir = tempfile::tempdir().expect("tempdir");
183	        store(dir.path(), &sample_state()).expect("store");
184	        // Restamp with a future version and drop the graph the way a
185	        // schema change would, so a plain parse would fail on a field
186	        // long before it noticed the version.
187	        fs_err::write(
188	            path_in(dir.path()),
189	            br#"{"version": 4, "graph": {"whatever": true}}"#,
190	        )
191	        .expect("write v4 state");
192	        let err = load(dir.path()).expect_err("foreign version must fail");
193	        let CliError::StaleWorkState {
194	            found, expected, ..
195	        } = &err
196	        else {
197	            panic!("expected StaleWorkState, got {err}");
198	        };
199	        assert_eq!(found, "v4", "reported version");
200	        assert_eq!(*expected, VERSION, "expected version");
201	        assert!(
202	            err.to_string().contains("tapa analyze"),
203	            "error must tell the user how to recover; got {err}",
204	        );
205	    }
206	
207	    #[test]
208	    fn unversioned_state_is_rejected() {
209	        // Pre-`version` work dirs (and hand-written files that forget the
210	        // stamp) must get the same clear message, not `missing field`.
211	        let dir = tempfile::tempdir().expect("tempdir");
212	        fs_err::write(path_in(dir.path()), br#"{"graph": {}, "flow": {}}"#).expect("write");
213	        let err = load(dir.path()).expect_err("unversioned state must fail");
214	        assert!(
215	            matches!(err, CliError::StaleWorkState { ref found, .. } if found == "unversioned"),
216	            "got {err}",
217	        );
218	    }
219	
220	    #[test]
221	    fn malformed_json_reports_the_syntax_error() {
222	        // The version probe must not swallow a real syntax error.
223	        let dir = tempfile::tempdir().expect("tempdir");
224	        fs_err::write(path_in(dir.path()), b"not json at all").expect("write");
225	        let err = load(dir.path()).expect_err("malformed state must fail");
226	        assert!(
227	            matches!(err, CliError::Schema(..)),
228	            "malformed JSON must surface as a schema error; got {err}",
229	        );
230	    }
231	
232	    #[test]
233	    fn unknown_field_is_rejected() {
234	        // `deny_unknown_fields` is what keeps the state schema honest; pin it.
235	        let dir = tempfile::tempdir().expect("tempdir");
236	        store(dir.path(), &sample_state()).expect("store");
237	        let text = fs_err::read_to_string(path_in(dir.path())).expect("read");
238	        let patched = text.replace("\"version\": 3,", "\"version\": 3,\n  \"bogus\": 1,");
239	        fs_err::write(path_in(dir.path()), patched).expect("write");
240	        let err = load(dir.path()).expect_err("unknown field must fail");
241	        assert!(
242	            matches!(err, CliError::Schema(..)),
243	            "unknown state field must be rejected; got {err}",
244	        );
245	    }
246	
247	    #[test]
248	    fn flow_settings_omit_absent_values() {
249	        // Absent optional settings must not materialize as `null`s that a
250	        // reader could mistake for "resolved to nothing".
251	        let dir = tempfile::tempdir().expect("tempdir");
252	        store(dir.path(), &sample_state()).expect("store");
253	        let raw = fs_err::read_to_string(path_in(dir.path())).expect("read");
254	        assert!(
255	            raw.contains("\"flow\": {\n    \"synthed\": false\n  }"),
256	            "unresolved flow settings must be omitted, not null; got {raw}",
257	        );
258	    }
259	}

