  1	//! `~/.taparc` YAML schema for remote Xilinx tool execution.
  2	//!
  3	//! The runtime config schema:
  4	//! - `user` defaults to the login name, not `None`;
  5	//! - `~` is expanded in `key_file` and `ssh_control_dir`;
  6	//! - unknown fields are ignored so additions do not fault the
  7	//!   Rust loader;
  8	//! - `from_env` seeds from the `REMOTE_*` names used in `VARS.local.bzl`.
  9	
 10	use camino::Utf8PathBuf;
 11	use serde::{Deserialize, Serialize};
 12	
 13	use crate::error::{Result, XilinxError};
 14	
 15	fn default_port() -> u16 {
 16	    22
 17	}
 18	
 19	fn default_work_dir() -> String {
 20	    "/tmp/tapa-remote".to_string()
 21	}
 22	
 23	fn default_ssh_control_persist() -> String {
 24	    "30m".to_string()
 25	}
 26	
 27	fn default_ssh_multiplex() -> bool {
 28	    true
 29	}
 30	
 31	fn current_username() -> String {
 32	    std::env::var("USER")
 33	        .or_else(|_| std::env::var("LOGNAME"))
 34	        .or_else(|_| std::env::var("USERNAME"))
 35	        .unwrap_or_else(|_| "unknown".to_string())
 36	}
 37	
 38	fn expand_tilde(p: &Utf8PathBuf) -> Utf8PathBuf {
 39	    let s = p.as_str();
 40	    let expanded = shellexpand::tilde(s);
 41	    Utf8PathBuf::from(expanded.as_ref())
 42	}
 43	
 44	#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
 45	pub struct RemoteConfig {
 46	    pub host: String,
 47	
 48	    #[serde(default = "current_username")]
 49	    pub user: String,
 50	
 51	    #[serde(default = "default_port")]
 52	    pub port: u16,
 53	
 54	    #[serde(default)]
 55	    pub key_file: Option<Utf8PathBuf>,
 56	
 57	    #[serde(default)]
 58	    pub xilinx_settings: Option<String>,
 59	
 60	    #[serde(default = "default_work_dir")]
 61	    pub work_dir: String,
 62	
 63	    #[serde(default)]
 64	    pub ssh_control_dir: Option<Utf8PathBuf>,
 65	
 66	    #[serde(default = "default_ssh_control_persist")]
 67	    pub ssh_control_persist: String,
 68	
 69	    #[serde(default = "default_ssh_multiplex")]
 70	    pub ssh_multiplex: bool,
 71	}
 72	
 73	impl RemoteConfig {
 74	    fn normalize_paths(&mut self) {
 75	        if let Some(p) = self.key_file.take() {
 76	            self.key_file = Some(expand_tilde(&p));
 77	        }
 78	        if let Some(p) = self.ssh_control_dir.take() {
 79	            self.ssh_control_dir = Some(expand_tilde(&p));
 80	        }
 81	    }
 82	
 83	    /// Parse a `.taparc`-style YAML document. Accepts either
 84	    /// `{remote: {...}}` (the `~/.taparc` top-level shape) or a bare
 85	    /// `RemoteConfig` mapping.
 86	    pub fn from_yaml_str(text: &str, path: impl AsRef<camino::Utf8Path>) -> Result<Self> {
 87	        let path = path.as_ref().to_path_buf();
 88	        let value: serde_yaml::Value =
 89	            serde_yaml::from_str(text).map_err(|source| XilinxError::Config {
 90	                path: path.clone(),
 91	                source,
 92	            })?;
 93	        let inner = match value {
 94	            serde_yaml::Value::Mapping(ref m) if m.contains_key("remote") => {
 95	                m.get("remote").cloned().unwrap_or(serde_yaml::Value::Null)
 96	            }
 97	            serde_yaml::Value::Null => {
 98	                return Err(XilinxError::Config {
 99	                    path,
100	                    source: missing_mapping_error(),
101	                });
102	            }
103	            serde_yaml::Value::Mapping(_)
104	            | serde_yaml::Value::Bool(_)
105	            | serde_yaml::Value::Number(_)
106	            | serde_yaml::Value::String(_)
107	            | serde_yaml::Value::Sequence(_)
108	            | serde_yaml::Value::Tagged(_) => value,
109	        };
110	        let mut cfg: Self =
111	            serde_yaml::from_value(inner).map_err(|source| XilinxError::Config {
112	                path: path.clone(),
113	                source,
114	            })?;
115	        cfg.normalize_paths();
116	        Ok(cfg)
117	    }
118	
119	    /// Build a `RemoteConfig` from environment variables matching the
120	    /// `VARS.local.bzl` naming used by the integration tests.
121	    /// `REMOTE_HOST` is required; everything else falls back to the
122	    /// same defaults as the YAML parser.
123	    pub fn from_env() -> Option<Self> {
124	        let host = std::env::var("REMOTE_HOST").ok()?;
125	        let mut cfg = Self {
126	            host,
127	            user: std::env::var("REMOTE_USER").unwrap_or_else(|_| current_username()),
128	            port: std::env::var("REMOTE_PORT")
129	                .ok()
130	                .and_then(|s| s.parse().ok())
131	                .unwrap_or_else(default_port),
132	            key_file: std::env::var("REMOTE_KEY_FILE").ok().map(Utf8PathBuf::from),
133	            xilinx_settings: resolve_xilinx_settings(
134	                std::env::var("REMOTE_XILINX_SETTINGS").ok().as_deref(),
135	                std::env::var("REMOTE_XILINX_TOOL_PATH").ok().as_deref(),
136	            ),
137	            work_dir: std::env::var("REMOTE_WORK_DIR").unwrap_or_else(|_| default_work_dir()),
138	            ssh_control_dir: std::env::var("REMOTE_SSH_CONTROL_DIR")
139	                .ok()
140	                .map(Utf8PathBuf::from),
141	            ssh_control_persist: std::env::var("REMOTE_SSH_CONTROL_PERSIST")
142	                .unwrap_or_else(|_| default_ssh_control_persist()),
143	            ssh_multiplex: std::env::var("REMOTE_SSH_MULTIPLEX").ok().is_none_or(|s| {
144	                matches!(
145	                    s.trim().to_lowercase().as_str(),
146	                    "true" | "yes" | "1" | "on"
147	                )
148	            }),
149	        };
150	        cfg.normalize_paths();
151	        Some(cfg)
152	    }
153	}
154	
155	fn missing_mapping_error() -> serde_yaml::Error {
156	    serde_yaml::from_str::<RemoteConfig>("").unwrap_err()
157	}
158	
159	/// Canonical rule used everywhere we need a remote `xilinx_settings`
160	/// path: prefer an explicit settings script, otherwise treat a
161	/// tool-root value as `<root>/settings64.sh`. The Rust layer only
162	/// ever `source`s the resulting path, so handing it a directory —
163	/// as `VARS.local.bzl`'s `REMOTE_XILINX_TOOL_PATH` commonly does —
164	/// would otherwise silently fail at bash-time.
165	#[must_use]
166	pub(crate) fn resolve_xilinx_settings(
167	    explicit_settings: Option<&str>,
168	    tool_root: Option<&str>,
169	) -> Option<String> {
170	    if let Some(s) = explicit_settings {
171	        let s = s.trim();
172	        if !s.is_empty() {
173	            return Some(s.to_string());
174	        }
175	    }
176	    if let Some(root) = tool_root {
177	        let root = root.trim();
178	        if root.is_empty() {
179	            return None;
180	        }
181	        // Already looks like a settings script (file ending in .sh)?
182	        // Leave it alone so pointing at a custom path still works.
183	        if root.ends_with(".sh") {
184	            return Some(root.to_string());
185	        }
186	        let trimmed = root.trim_end_matches('/');
187	        return Some(format!("{trimmed}/settings64.sh"));
188	    }
189	    None
190	}
191	
192	#[cfg(test)]
193	mod tests {
194	    use super::*;
195	    use std::sync::Mutex;
196	
197	    static ENV_LOCK: Mutex<()> = Mutex::new(());
198	
199	    const VALID: &str = "
200	remote:
201	  host: fpga01.example.com
202	  user: alice
203	  port: 2222
204	  key_file: ~/.ssh/id_ed25519
205	  xilinx_settings: /opt/xilinx/Vitis/2023.2/settings64.sh
206	";
207	
208	    #[test]
209	    fn parses_valid_taparc_and_expands_tilde() {
210	        let _lock = ENV_LOCK.lock().unwrap();
211	        std::env::set_var("HOME", "/home/alice");
212	        let cfg = RemoteConfig::from_yaml_str(VALID, "/tmp/.taparc").unwrap();
213	        assert_eq!(cfg.host, "fpga01.example.com");
214	        assert_eq!(cfg.user, "alice");
215	        assert_eq!(cfg.port, 2222);
216	        assert_eq!(
217	            cfg.key_file.as_deref(),
218	            Some(Utf8PathBuf::from("/home/alice/.ssh/id_ed25519").as_path())
219	        );
220	        assert!(cfg.ssh_multiplex);
221	    }
222	
223	    #[test]
224	    fn default_user_is_current_username() {
225	        let _lock = ENV_LOCK.lock().unwrap();
226	        std::env::set_var("USER", "testuser");
227	        let cfg = RemoteConfig::from_yaml_str("remote:\n  host: h\n", "/tmp/.taparc").unwrap();
228	        assert_eq!(cfg.user, "testuser");
229	    }
230	
231	    #[test]
232	    fn unknown_fields_are_accepted() {
233	        // Unknown keys are ignored so newer config files remain readable.
234	        let text = "remote:\n  host: h\n  future_field: yes\n";
235	        let cfg = RemoteConfig::from_yaml_str(text, "/tmp/.taparc").unwrap();
236	        assert_eq!(cfg.host, "h");
237	    }
238	
239	    #[test]
240	    fn round_trips_through_yaml() {
241	        let _lock = ENV_LOCK.lock().unwrap();
242	        std::env::set_var("HOME", "/home/alice");
243	        let cfg = RemoteConfig::from_yaml_str(VALID, "/tmp/.taparc").unwrap();
244	        let emitted = serde_yaml::to_string(&cfg).unwrap();
245	        let again: RemoteConfig = serde_yaml::from_str(&emitted).unwrap();
246	        assert_eq!(cfg, again);
247	    }
248	
249	    #[test]
250	    fn wrong_type_surfaces_config_error() {
251	        let text = "remote:\n  host: h\n  port: not-a-number\n";
252	        let err = RemoteConfig::from_yaml_str(text, "/tmp/.taparc").unwrap_err();
253	        assert!(matches!(err, XilinxError::Config { .. }));
254	    }
255	
256	    #[test]
257	    fn empty_document_is_error() {
258	        let err = RemoteConfig::from_yaml_str("", "/tmp/.taparc").unwrap_err();
259	        assert!(matches!(err, XilinxError::Config { .. }));
260	    }

