  1	//! Chained-subcommand dispatcher.
  2	//!
  3	//! `tapa analyze … synth … pack …` runs the three steps in order with
  4	//! per-step flags delimited by the next subcommand name. clap has no
  5	//! native chained-group derive, so each step's `Args` struct uses
  6	//! `trailing_var_arg = true` to capture everything after its own flag
  7	//! surface; the captured suffix is re-parsed here as the next [`Step`].
  8	//!
  9	//! This keeps clap responsible for option-arity decisions: a flag value
 10	//! that happens to equal a subcommand name (e.g. `--top synth`) is
 11	//! consumed by clap as the flag value, never as a chunk boundary.
 12	
 13	use clap::{Parser, Subcommand};
 14	
 15	use crate::context::CliContext;
 16	use crate::error::{CliError, Result};
 17	use crate::steps::{analyze, find_clang_binary, floorplan, gcc, meta, pack, synth, version};
 18	
 19	/// One link in the chained-step list. Each variant carries its step's
 20	/// `Args` (flags) plus a `chain_tail` positional that captures any
 21	/// remaining argv for re-parsing as the next step.
 22	#[allow(
 23	    clippy::large_enum_variant,
 24	    reason = "a clap dispatch enum: each variant must `#[command(flatten)]` its \
 25	              step's Args struct inline, so the differently-sized Args (Compile \
 26	              bundles the whole flow) cannot be boxed without breaking the derive"
 27	)]
 28	#[derive(Debug, Subcommand)]
 29	pub enum Step {
 30	    /// Analyze TAPA program and store the program description.
 31	    Analyze {
 32	        #[command(flatten)]
 33	        args: analyze::AnalyzeArgs,
 34	        #[arg(trailing_var_arg = true, allow_hyphen_values = true, hide = true)]
 35	        chain_tail: Vec<String>,
 36	    },
 37	    /// Synthesize the TAPA program into RTL.
 38	    Synth {
 39	        #[command(flatten)]
 40	        args: synth::SynthArgs,
 41	        #[arg(trailing_var_arg = true, allow_hyphen_values = true, hide = true)]
 42	        chain_tail: Vec<String>,
 43	    },
 44	    /// Coarse-grained floorplan the synthesized design.
 45	    Floorplan {
 46	        #[command(flatten)]
 47	        args: floorplan::FloorplanArgs,
 48	        #[arg(trailing_var_arg = true, allow_hyphen_values = true, hide = true)]
 49	        chain_tail: Vec<String>,
 50	    },
 51	    /// Pack the generated RTL into a Xilinx object file.
 52	    Pack {
 53	        #[command(flatten)]
 54	        args: pack::PackArgs,
 55	        #[arg(trailing_var_arg = true, allow_hyphen_values = true, hide = true)]
 56	        chain_tail: Vec<String>,
 57	    },
 58	    /// Compile a TAPA program (analyze + synth + pack) in one invocation.
 59	    Compile {
 60	        #[command(flatten)]
 61	        args: meta::CompileArgs,
 62	        #[arg(trailing_var_arg = true, allow_hyphen_values = true, hide = true)]
 63	        chain_tail: Vec<String>,
 64	    },
 65	    /// Invoke g++ with TAPA include and library paths.
 66	    ///
 67	    /// Terminal: `g++`'s own `trailing_var_arg` already consumes any
 68	    /// tokens that follow, so chaining a subsequent subcommand after
 69	    /// `g++` is not supported.
 70	    #[command(name = "g++")]
 71	    Gpp {
 72	        #[command(flatten)]
 73	        args: gcc::GccArgs,
 74	    },
 75	    /// Print TAPA version to standard output.
 76	    Version {
 77	        #[command(flatten)]
 78	        args: version::VersionArgs,
 79	        #[arg(trailing_var_arg = true, allow_hyphen_values = true, hide = true)]
 80	        chain_tail: Vec<String>,
 81	    },
 82	    /// Resolve a clang-family helper and print its absolute path.
 83	    #[command(name = "find-clang-binary", hide = true)]
 84	    FindClangBinary {
 85	        #[command(flatten)]
 86	        args: find_clang_binary::FindClangBinaryArgs,
 87	        #[arg(trailing_var_arg = true, allow_hyphen_values = true, hide = true)]
 88	        chain_tail: Vec<String>,
 89	    },
 90	}
 91	
 92	/// Standalone parser for re-parsing the trailing chain.
 93	#[derive(Debug, Parser)]
 94	#[command(name = "tapa", disable_help_subcommand = true)]
 95	struct ChainParser {
 96	    #[command(subcommand)]
 97	    step: Step,
 98	}
 99	
100	impl Step {
101	    /// Walk the chained-step linked list: parse and validate the
102	    /// *entire* chain first, then execute
103	    /// each step in order. A parse error or `--help` on a later token
104	    /// (e.g. `tapa analyze … synth --help`) must surface before any
105	    /// step mutates `work_dir` or shells out to a missing tool.
106	    pub fn execute(self, ctx: &mut CliContext) -> Result<()> {
107	        let mut steps: Vec<Self> = Vec::new();
108	        let mut current: Option<Self> = Some(self);
109	        while let Some(step) = current {
110	            let (head, tail) = step.split_chain();
111	            steps.push(head);
112	            current = if tail.is_empty() {
113	                None
114	            } else {
115	                Some(parse_chain_tail(&tail)?)
116	            };
117	        }
118	        for step in steps {
119	            step.run_one(ctx)?;
120	        }
121	        Ok(())
122	    }
123	
124	    /// Detach the trailing-vararg payload from this step and return
125	    /// the head (with an empty tail) plus the captured tail tokens.
126	    /// `g++` is terminal — its own `trailing_var_arg` already
127	    /// consumed any chained tokens.
128	    fn split_chain(mut self) -> (Self, Vec<String>) {
129	        let tail = self
130	            .chain_tail_mut()
131	            .map(std::mem::take)
132	            .unwrap_or_default();
133	        (self, tail)
134	    }
135	
136	    /// Mutable accessor for the per-variant `chain_tail` field, or
137	    /// `None` for terminal variants (`g++`).
138	    fn chain_tail_mut(&mut self) -> Option<&mut Vec<String>> {
139	        match self {
140	            Self::Analyze { chain_tail, .. }
141	            | Self::Synth { chain_tail, .. }
142	            | Self::Floorplan { chain_tail, .. }
143	            | Self::Pack { chain_tail, .. }
144	            | Self::Compile { chain_tail, .. }
145	            | Self::Version { chain_tail, .. }
146	            | Self::FindClangBinary { chain_tail, .. } => Some(chain_tail),
147	            Self::Gpp { .. } => None,
148	        }
149	    }
150	
151	    /// Dispatch a single step's side-effecting body. Called only
152	    /// after the whole chain has been parsed and validated.
153	    fn run_one(self, ctx: &mut CliContext) -> Result<()> {
154	        match self {
155	            Self::Analyze { args, .. } => analyze::run(&args, ctx),
156	            Self::Synth { args, .. } => synth::run(&args, ctx),
157	            Self::Floorplan { args, .. } => floorplan::run(&args, ctx),
158	            Self::Pack { args, .. } => pack::run(&args, ctx),
159	            Self::Compile { args, .. } => meta::run_compile_composite(&args, ctx),
160	            Self::Gpp { args } => gcc::run(&args, ctx),
161	            Self::Version { args, .. } => version::run(&args, ctx),
162	            Self::FindClangBinary { args, .. } => find_clang_binary::run(&args, ctx),
163	        }
164	    }
165	}
166	
167	fn parse_chain_tail(tail: &[String]) -> Result<Step> {
168	    // ChainParser expects argv[0] to be the program name.
169	    let mut argv: Vec<&str> = Vec::with_capacity(tail.len() + 1);
170	    argv.push("tapa");
171	    argv.extend(tail.iter().map(String::as_str));
172	    let parsed = ChainParser::try_parse_from(&argv).map_err(|e| {
173	        if matches!(
174	            e.kind(),
175	            clap::error::ErrorKind::DisplayHelp | clap::error::ErrorKind::DisplayVersion
176	        ) {
177	            // `--help` / `--version` in the chain tail are graceful
178	            // exits handled the same way as the top-level parser.
179	            let _ = e.print();
180	            std::process::exit(0);
181	        }
182	        CliError::ClapParse {
183	            step: "<chain>".to_string(),
184	            message: e.to_string(),
185	        }
186	    })?;
187	    Ok(parsed.step)
188	}
