196	        Cli::try_parse_from(std::iter::once("tapa").chain(args.iter().copied()))
197	    }
198	
199	    #[test]
200	    fn three_step_chain_parses() {
201	        let cli = parse(&[
202	            "analyze",
203	            "--input",
204	            "vadd.cpp",
205	            "--top",
206	            "VecAdd",
207	            "synth",
208	            "--platform",
209	            "xilinx_u250",
210	            "pack",
211	            "--output",
