213	        ])
214	        .expect("3-step chain must parse");
215	        match cli.step {
216	            Some(Step::Analyze { args, chain_tail }) => {
217	                assert_eq!(args.top, "VecAdd");
218	                assert_eq!(chain_tail.first().map(String::as_str), Some("synth"));
219	            }
220	            other => panic!("expected Analyze, got {other:?}"),

