  1	//! `run_native` orchestrator for `tapa synth`.
  2	//!
  3	//! Threads device resolution → state persistence → cpp-extract →
  4	//! HLS runs → RTL codegen → final state persistence. Also
  5	//! owns the unsupported-flag gating, the HLS cflag construction, and
  6	//! the recursive Verilog-file walker that feeds the codegen step.
  7	
  8	use serde_json::Value;
  9	use tapa_ir::Task;
 10	use tapa_xilinx::{CsynthReport, ToolRunner};
 11	
 12	use crate::context::CliContext;
 13	use crate::error::Result;
 14	use crate::state::work as work_io;
 15	use crate::tapacc::cflags::{get_remote_hls_cflags, get_tapacc_cflags};
 16	use crate::tapacc::discover::find_resource;
 17	
 18	use super::cpp_extract::extract_hls_sources;
 19	use super::device_resolve::resolve_device_info;
 20	use super::hls_run::{run_hls_for_leaves, HlsRunOptions};
 21	use super::post_synth_util::emit_post_synth_util;
 22	use super::report::write_top_report;
 23	use super::rtl_codegen::{generate_rtl_tree, write_templates_info, TaskHdlInputs};
 24	use super::SynthArgs;
 25	
 26	/// Validate the flag surface, resolve the device, persist settings,
 27	/// then drive cpp-extract → HLS → codegen for the leaf tasks.
 28	#[allow(
 29	    clippy::too_many_lines,
 30	    reason = "orchestrator function; refactored extract would bounce values through another builder without adding clarity"
 31	)]
 32	pub fn run_native(args: &SynthArgs, ctx: &CliContext, runner: &dyn ToolRunner) -> Result<()> {
 33	    // The flow target is typed and validated by the state parse itself, so
 34	    // there is nothing left for this step to re-check: synthesis is Xilinx
 35	    // HLS for every supported flow.
 36	    let mut state = work_io::load(&ctx.work_dir)?;
 37	
 38	    let device = resolve_device_info(args)?;
 39	    state.flow.part_num = Some(device.part_num.clone());
 40	    state.flow.platform.clone_from(&args.platform);
 41	    state.flow.clock_period = Some(device.clock_period.clone());
 42	    // A synthesis rerun may change RTL, area, device, or timing inputs. Make
 43	    // every result derived from the previous RTL inactive before the long HLS
 44	    // runs, so an interrupted rerun cannot be packed or floorplanned as if it
 45	    // had completed successfully.
 46	    state.flow.synthed = false;
 47	    state.floorplan = None;
 48	    work_io::store(&ctx.work_dir, &state)?;
 49	
 50	    extract_hls_sources(&ctx.work_dir, &state.graph)?;
 51	
 52	    let opts = HlsRunOptions {
 53	        part_num: device.part_num.clone(),
 54	        clock_period: device.clock_period.clone(),
 55	        other_configs: args.other_hls_configs.clone(),
 56	        cflags: build_hls_cflags(&state.graph.cflags, ctx.remote_config.is_some()),
 57	        skip_based_on_mtime: args.skip_hls_based_on_mtime,
 58	        jobs: args.jobs,
 59	        keep_work_dir: args.keep_hls_work_dir,
 60	    };
 61	    let hls_results = run_hls_for_leaves(runner, &ctx.work_dir, &state.graph, &opts)?;
 62	
 63	    let mut hdl_inputs: TaskHdlInputs = TaskHdlInputs::new();
 64	    for (task_name, layout, out) in &hls_results {
 65	        let mut files = out.verilog_files.clone();
 66	        files.extend(super::hls_run::list_hdl_files(&layout.hdl_dir)?);
 67	        files.sort();
 68	        files.dedup();
 69	        hdl_inputs.insert(task_name.clone(), files);
 70	
 71	        if let Some(task) = state.graph.tasks.get_mut(task_name) {
 72	            apply_hls_metrics(task, &out.csynth);
 73	        }
 74	    }
 75	    generate_rtl_tree(&ctx.work_dir, &state.graph, &hdl_inputs, None)?;
 76	
 77	    // Per-task OOC Vivado synth → hierarchical utilization → `total_area`.
 78	    // When disabled (the default), reports and topology consumers derive
 79	    // effective totals recursively from the HLS-populated `self_area` maps.
 80	    if args.enable_synth_util {
 81	        emit_post_synth_util(
 82	            &ctx.work_dir,
 83	            &mut state.graph,
 84	            &device.part_num,
 85	            args.jobs,
 86	            runner,
 87	        )?;
 88	    }
 89	
 90	    // Emit `report.{json,yaml}` at the work-dir root once area data is
 91	    // final. Both pack paths (`xilinx-vitis` `.xo` and `xilinx-hls`
 92	    // `.zip`) bundle the YAML at archive root.
 93	    write_top_report(
 94	        &ctx.work_dir,
 95	        &state.graph,
 96	        &args.override_report_schema_version,
 97	    )?;
 98	
 99	    write_templates_info(&ctx.work_dir, &state.graph)?;
100	    state.flow.synthed = true;
101	    work_io::store(&ctx.work_dir, &state)?;
102	
103	    Ok(())
104	}
