263	pub fn list_hdl_files(dir: &camino::Utf8Path) -> Result<Vec<Utf8PathBuf>> {
264	    let mut out = Vec::new();
265	    if !dir.is_dir() {
266	        return Ok(out);
267	    }
268	    for ent in walkdir::WalkDir::new(dir) {
269	        let ent = ent.map_err(|e| {
270	            CliError::Codegen(format!(
271	                "failed to inspect HDL directory `{}`: {e}",
272	                dir.as_str()
273	            ))
274	        })?;
275	        if ent.file_type().is_file() {
276	            let p = ent.path().to_path_buf();
277	            out.push(crate::util::utf8(p));
278	        }
279	    }
280	    out.sort();
281	    Ok(out)
282	}
