288	/// Reload and parse the task's top-level csynth report on an mtime-skip
289	/// cache hit.
290	///
291	/// Reads `<task>_csynth.xml` (falling back to `<task>.csynth.xml`), the
292	/// exact file the live HLS harvest parses. A task's report dir also holds
293	/// sub-module reports — e.g. `<task>_Pipeline_VITIS_LOOP_*_csynth.xml` —
294	/// which likewise end in `_csynth.xml` but carry only the sub-loop's
295	/// (smaller) area. Selecting the first `*_csynth.xml` in `read_dir` order
296	/// could therefore reload a sub-module's area, making the skip path
297	/// disagree with a full HLS run and breaking `.xo` reproducibility.
298	fn find_and_parse_csynth(
299	    reports_dir: &camino::Utf8Path,
300	    task_name: &str,
301	) -> Result<tapa_xilinx::CsynthReport> {
302	    let primary = reports_dir.join(format!("{task_name}_csynth.xml"));
303	    let fallback = reports_dir.join(format!("{task_name}.csynth.xml"));
304	    let report_xml = if primary.is_file() { primary } else { fallback };
