246	fn hdl_files_are_newer_than(hdl_files: &[Utf8PathBuf], cpp_source: &camino::Utf8Path) -> bool {
247	    if hdl_files.is_empty() {
248	        return false;
249	    }
250	    let Ok(cpp_meta) = fs::metadata(cpp_source) else {
251	        return false;
252	    };
253	    let Ok(cpp_t) = cpp_meta.modified() else {
254	        return false;
255	    };
256	    hdl_files.iter().all(|hdl| {
257	        fs::metadata(hdl)
258	            .and_then(|metadata| metadata.modified())
259	            .is_ok_and(|hdl_t| hdl_t > cpp_t)
260	    })
261	}
