  1	//! Per-task Vitis HLS invocation with parallel dispatch and
  2	//! mtime-based skipping.
  3	
  4	use camino::Utf8PathBuf;
  5	use rayon::prelude::*;
  6	use std::fs;
  7	use std::path::Path;
  8	
  9	use tapa_ir::{Design, SynthTarget};
 10	use tapa_xilinx::{run_hls_with_retry, run_hls_with_retry_in_stage, HlsJob, HlsOutput, ToolRunner};
 11	
 12	use crate::error::{CliError, Result};
 13	use crate::steps::synth::cpp_extract::cpp_path_for;
 14	
 15	use super::resolve_worker_count;
 16	
 17	/// Up to 3 attempts total. Vitis HLS occasionally fails with a
 18	/// transient `Pre-synthesis failed.` diagnostic that re-runs clean,
 19	/// so the retry wrapper keys off that substring.
 20	const HLS_MAX_ATTEMPTS: u32 = 3;
 21	
 22	#[derive(Debug, Clone)]
 23	pub struct TaskHlsLayout {
 24	    pub reports_dir: Utf8PathBuf,
 25	    pub hdl_dir: Utf8PathBuf,
 26	}
 27	
 28	impl TaskHlsLayout {
 29	    pub fn new(work_dir: &Path, task_name: &str) -> Self {
 30	        let base = work_dir.join("hls").join(task_name);
 31	        Self {
 32	            reports_dir: crate::util::utf8(base.join("report")),
 33	            hdl_dir: crate::util::utf8(base.join("verilog")),
 34	        }
 35	    }
 36	}
 37	
 38	#[derive(Debug, Clone)]
 39	pub struct HlsRunOptions {
 40	    pub part_num: String,
 41	    pub clock_period: String,
 42	    pub other_configs: String,
 43	    pub cflags: Vec<String>,
 44	    pub skip_based_on_mtime: bool,
 45	    /// Number of HLS runs executed in parallel. `None` or 1 → serial.
 46	    pub jobs: Option<u32>,
 47	    /// When `--keep-hls-work-dir` is set,
 48	    /// `run_hls` stages under `<work_dir>/hls/<task>/project` (kept
 49	    /// on disk) instead of a tempdir so the Vitis project + logs
 50	    /// survive after a failure.
 51	    pub keep_work_dir: bool,
 52	}
 53	
 54	/// Run HLS for every task that targets HLS — **all** tasks
 55	/// (not just leaves) — the upper-task shell is needed by codegen so
 56	/// the parent module's port surface is parseable. Tasks whose
 57	/// `target == "ignore"` are skipped (promotes them to
 58	/// `gen_templates`).
 59	pub fn run_hls_for_leaves(
 60	    runner: &dyn ToolRunner,
 61	    work_dir: &Path,
 62	    design: &Design,
 63	    options: &HlsRunOptions,
 64	) -> Result<Vec<(String, TaskHlsLayout, HlsOutput)>> {
 65	    // Plan pass: enumerate every task that needs HLS, resolve its
 66	    // layout + cpp source, and either record a cache-hit short-circuit
 67	    // or a live Vitis job. This keeps the parallel loop straightforward
 68	    // (just dispatch the live jobs) and preserves the original output
 69	    // order even when jobs run out-of-order.
 70	    let mut plan: Vec<(String, TaskHlsLayout, Work)> = Vec::new();
 71	    for (task_name, task) in &design.tasks {
 72	        if task.synth == SynthTarget::Ignore {
 73	            continue;
 74	        }
 75	        let layout = TaskHlsLayout::new(work_dir, task_name);
 76	
 77	        let cpp_source = cpp_path_for(work_dir, task_name);
 78	        let cpp_source = crate::util::utf8(cpp_source);
 79	        if !cpp_source.is_file() {
 80	            return Err(CliError::Codegen(format!(
 81	                "missing extracted C++ source `{}` for task `{task_name}`",
 82	                cpp_source.as_str(),
 83	            )));
 84	        }
 85	
 86	        // Check freshness before creating `layout.hdl_dir`, and require
 87	        // at least one `.v` file so a directory containing only generator
 88	        // sidecars is not a cache hit.
 89	        if options.skip_based_on_mtime && layout.hdl_dir.is_dir() {
 90	            let hdl_files = list_hdl_files(&layout.hdl_dir)?;
 91	            if hdl_files.iter().any(|path| is_verilog(path))
 92	                && hdl_files_are_newer_than(&hdl_files, &cpp_source)
 93	            {
 94	                log::info!(
 95	                    "skipping HLS for `{task_name}` (mtime cache hit at {})",
 96	                    layout.hdl_dir.as_str(),
 97	                );
 98	                // `reports_dir` must still exist for downstream
 99	                // readers; the skip path does not touch `hdl_dir`.
100	                fs::create_dir_all(&layout.reports_dir)?;
101	                // Reload existing csynth data so downstream report
102	                // generation and the persisted graph keep correct metrics.
103	                let csynth =
104	                    find_and_parse_csynth(&layout.reports_dir, task_name).unwrap_or_else(|e| {
105	                        log::warn!(
106	                            "could not reload cached csynth for `{task_name}`: {e}; using defaults"
107	                        );
108	                        tapa_xilinx::CsynthReport::default()
109	                    });
110	                let report_paths = walkdir::WalkDir::new(&layout.reports_dir)
111	                    .into_iter()
112	                    .filter_map(std::result::Result::ok)
113	                    .filter(|e| e.file_type().is_file())
114	                    .map(|e| crate::util::utf8(e.path()))
115	                    .collect();
116	                plan.push((
117	                    task_name.clone(),
118	                    layout,
119	                    Work::Skip(HlsOutput {
120	                        csynth,
121	                        verilog_files: hdl_files,
122	                        report_paths,
123	                        stdout: String::new(),
124	                        stderr: String::new(),
125	                    }),
126	                ));
127	                continue;
128	            }
129	        }
130	
131	        fs::create_dir_all(&layout.reports_dir)?;
132	        fs::create_dir_all(&layout.hdl_dir)?;
133	
134	        let job = HlsJob::builder()
135	            .task_name(task_name.clone())
136	            .cpp_source(cpp_source)
137	            .cflags(options.cflags.clone())
138	            .target_part(options.part_num.clone())
139	            .top_name(task_name.clone())
140	            .clock_period(options.clock_period.clone())

