  1	//! Direct `v++ --link` orchestration and implementation timing extraction.
  2	
  3	use camino::{Utf8Path, Utf8PathBuf};
  4	use typed_builder::TypedBuilder;
  5	
  6	use crate::error::{Result, XilinxError};
  7	use crate::runtime::process::{ToolInvocation, ToolRunner};
  8	
  9	pub mod timing;
 10	
 11	use self::timing::{parse_kernel_timing_summary, KernelTiming};
 12	
 13	const TIMING_REPORT_NAME: &str = "timing_summary.rpt";
 14	const FINAL_TIMING_HOOK_NAME: &str = "final_timing.tcl";
 15	const IMPLEMENTATION_STRATEGY: &str = "Explore";
 16	const PLACEMENT_STRATEGY: &str = "EarlyBlockPlacement";
 17	
 18	/// Convert a requested clock period to the conservative whole-MHz value that
 19	/// `v++ --kernel_frequency` accepts.
 20	pub fn target_frequency_mhz(clock_period_ns: f64) -> Result<u32> {
 21	    if !clock_period_ns.is_finite() || clock_period_ns <= 0.0 {
 22	        return Err(XilinxError::InvalidFrequency(format!(
 23	            "clock period must be finite and positive, got `{clock_period_ns}` ns"
 24	        )));
 25	    }
 26	    let floored = (1000.0 / clock_period_ns).floor();
 27	    if !floored.is_finite() || !(1.0..=f64::from(u32::MAX)).contains(&floored) {
 28	        return Err(XilinxError::InvalidFrequency(format!(
 29	            "clock period `{clock_period_ns}` ns produces unsupported target `{floored}` MHz"
 30	        )));
 31	    }
 32	    #[allow(
 33	        clippy::cast_possible_truncation,
 34	        clippy::cast_sign_loss,
 35	        reason = "the floored value was range-checked against positive u32 above"
 36	    )]
 37	    Ok(floored as u32)
 38	}
 39	
 40	/// One portable Alveo hardware-link job.
 41	///
 42	/// `platform` must be an installed platform name. Platform paths are rejected
 43	/// because they cannot be transferred safely to a remote tool host without
 44	/// also resolving the files referenced by the platform.
 45	#[derive(Debug, Clone, TypedBuilder)]
 46	pub struct VitisLinkJob {
 47	    pub kernel_name: String,
 48	    pub xo: Utf8PathBuf,
 49	    pub platform: String,
 50	    /// Whole MHz passed to `v++ --kernel_frequency`; zero is rejected.
 51	    pub target_mhz: u32,
 52	    /// Per-job directory used as the tool working directory.
 53	    pub work_dir: Utf8PathBuf,
 54	    /// Compact directory downloaded by a remote runner. It contains the
 55	    /// timing hook/report, Vitis reports, and Vitis logs.
 56	    pub artifacts_dir: Utf8PathBuf,
 57	    pub output_xclbin: Utf8PathBuf,
 58	    pub report_dir: Utf8PathBuf,
 59	    pub log_dir: Utf8PathBuf,
 60	    /// Vitis implementation project. This path must be outside
 61	    /// `artifacts_dir`, and is deliberately never downloaded.
 62	    pub temp_dir: Utf8PathBuf,
 63	    #[builder(default)]
 64	    pub floorplan_xdc: Option<Utf8PathBuf>,
 65	    #[builder(default)]
 66	    pub connectivity_config: Option<Utf8PathBuf>,
 67	    /// Parallel Vivado synthesis job count for this link, forwarded to
 68	    /// `--vivado.synth.jobs`. Acts as the per-link thread budget.
 69	    #[builder(default = 2)]
 70	    pub vivado_threads: u32,
 71	}
 72	
 73	#[derive(Debug, Clone, PartialEq)]
 74	pub struct VitisLinkOutput {
 75	    pub timing_report: Utf8PathBuf,
 76	    pub timing: KernelTiming,
 77	    pub stdout: String,
 78	    pub stderr: String,
 79	}
 80	
 81	#[derive(Debug)]
 82	struct ResolvedJob<'a> {
 83	    job: &'a VitisLinkJob,
 84	    xo: Utf8PathBuf,
 85	    work_dir: Utf8PathBuf,
 86	    artifacts_dir: Utf8PathBuf,
 87	    output_xclbin: Utf8PathBuf,
 88	    report_dir: Utf8PathBuf,
 89	    log_dir: Utf8PathBuf,
 90	    temp_dir: Utf8PathBuf,
 91	    floorplan_xdc: Option<Utf8PathBuf>,
 92	    connectivity_config: Option<Utf8PathBuf>,
 93	    timing_hook: Utf8PathBuf,
 94	    timing_report: Utf8PathBuf,
 95	}
 96	
 97	impl<'a> ResolvedJob<'a> {
 98	    fn new(job: &'a VitisLinkJob) -> Result<Self> {
 99	        if job.kernel_name.trim().is_empty() {
100	            return link_error("kernel name must not be empty");
101	        }
102	        if job.platform.trim().is_empty() {
103	            return link_error("platform must not be empty");
104	        }
105	        if platform_looks_like_path(&job.platform) {
106	            return link_error(format!(
107	                "platform `{}` must be an installed platform name, not a path",
108	                job.platform
109	            ));
110	        }
111	        if job.target_mhz == 0 {
112	            return Err(XilinxError::InvalidFrequency(
113	                "target frequency must be positive, got `0` MHz".into(),
114	            ));
115	        }
116	        if job.vivado_threads == 0 {
117	            return link_error("Vivado thread count must be greater than zero, got `0`");
118	        }
119	
120	        let xo = crate::util::absolutize(&job.xo);
121	        let work_dir = crate::util::absolutize(&job.work_dir);
122	        let artifacts_dir = crate::util::absolutize(&job.artifacts_dir);
123	        let output_xclbin = crate::util::absolutize(&job.output_xclbin);
124	        let report_dir = crate::util::absolutize(&job.report_dir);
125	        let log_dir = crate::util::absolutize(&job.log_dir);
126	        let temp_dir = crate::util::absolutize(&job.temp_dir);
127	        let floorplan_xdc = job.floorplan_xdc.as_deref().map(crate::util::absolutize);
128	        let connectivity_config = job
129	            .connectivity_config
130	            .as_deref()
131	            .map(crate::util::absolutize);
132	
133	        ensure_under(
134	            &artifacts_dir,
135	            &work_dir,
136	            "artifacts directory",
137	            "work directory",
138	        )?;
139	        ensure_under(
140	            &output_xclbin,
141	            &artifacts_dir,
142	            "xclbin",
143	            "artifacts directory",
144	        )?;
145	        if output_xclbin.extension() != Some("xclbin") {
146	            return link_error(format!(
147	                "Alveo link output `{output_xclbin}` must use the `.xclbin` extension"
148	            ));
149	        }
150	        ensure_under(
151	            &report_dir,
152	            &artifacts_dir,
153	            "report directory",
154	            "artifacts directory",
155	        )?;
156	        ensure_under(
157	            &log_dir,
158	            &artifacts_dir,
159	            "log directory",
160	            "artifacts directory",
161	        )?;
162	        ensure_under(&temp_dir, &work_dir, "temp directory", "work directory")?;
163	        if temp_dir.starts_with(&artifacts_dir) {
164	            return link_error(
165	                "temp directory must be outside the downloadable artifacts directory",
166	            );
167	        }
168	        let output_parent = output_xclbin
169	            .parent()
170	            .ok_or_else(|| XilinxError::VitisLink("xclbin path has no parent directory".into()))?;
171	        let timing_hook = output_parent.join(FINAL_TIMING_HOOK_NAME);
172	        let timing_report = output_parent.join(TIMING_REPORT_NAME);
173	
174	        Ok(Self {
175	            job,
176	            xo,
177	            work_dir,
178	            artifacts_dir,
179	            output_xclbin,
180	            report_dir,
181	            log_dir,
182	            temp_dir,
183	            floorplan_xdc,
184	            connectivity_config,
185	            timing_hook,
186	            timing_report,
187	        })
188	    }
189	}
190	
191	fn platform_looks_like_path(platform: &str) -> bool {
192	    platform.contains(['/', '\\'])
193	        || Utf8Path::new(platform)
194	            .extension()
195	            .is_some_and(|extension| extension.eq_ignore_ascii_case("xpfm"))
196	}
197	
198	fn ensure_under(path: &Utf8Path, root: &Utf8Path, item: &str, root_name: &str) -> Result<()> {
199	    if path != root && path.starts_with(root) {
200	        Ok(())
201	    } else {
202	        link_error(format!(
203	            "{item} `{path}` must be below {root_name} `{root}`"
204	        ))
205	    }
206	}
207	
208	fn link_error<T>(detail: impl Into<String>) -> Result<T> {
209	    Err(XilinxError::VitisLink(detail.into()))
210	}
211	
212	fn validate_input(path: &Utf8Path, label: &str) -> Result<()> {
213	    if path.is_file() {
214	        Ok(())
215	    } else {
216	        link_error(format!("{label} `{path}` is not a file"))
217	    }
218	}
219	
220	fn final_timing_tcl() -> &'static str {
221	    "set artifact_dir [file dirname [file normalize [info script]]]\n\
222	report_timing_summary -file [file join $artifact_dir timing_summary.rpt]\n"
223	}
224	
225	fn build_invocation(resolved: &ResolvedJob<'_>) -> ToolInvocation {
226	    let job = resolved.job;
227	    let mut inv = ToolInvocation::new("v++")
228	        .arg("--link")
229	        .arg("--target")
230	        .arg("hw")
231	        .arg("--save-temps")
