  1	//! `tapa floorplan` — coarse-grained floorplanning between `synth` and `pack`.
  2	//!
  3	//! Loads the synthesized work state, plans a placement with `tapa-floorplan`,
  4	//! stores the resulting [`FloorplanResult`](tapa_ir::FloorplanResult) back into
  5	//! `tapa.json`, and writes the pblock constraints to `<work_dir>/floorplan.xdc`.
  6	//! Its presence in the state switches codegen and `pack` onto the floorplanned
  7	//! path.
  8	
  9	use std::path::{Path, PathBuf};
 10	
 11	use clap::{Parser, ValueEnum};
 12	use tapa_codegen::rtl_state::DirectMmapInterface;
 13	use tapa_floorplan::{
 14	    dse::{explore, DseCandidate, DseOptions},
 15	    plan_with_inputs, render_xdc, ControlInterface, MemoryInterface, PartitionStrategy, PlanInputs,
 16	    PlanOptions,
 17	};
 18	use tapa_ir::{Design, MemoryBindings, PipelineScheme, WorkState};
 19	
 20	use crate::context::CliContext;
 21	use crate::error::{CliError, Result};
 22	use crate::state::{json, work as work_io};
 23	use crate::steps::synth::rtl_codegen::{
 24	    collect_hdl_inputs, emit_prepared_rtl_tree, prepare_rtl_state, TaskHdlInputs,
 25	};
 26	
 27	mod implementation;
 28	
 29	/// Name of the emitted pblock constraints file in the work directory.
 30	pub const FLOORPLAN_XDC: &str = "floorplan.xdc";
 31	/// Name of the exact Vitis connectivity input staged with a floorplan.
 32	pub const FLOORPLAN_CONNECTIVITY: &str = "floorplan-connectivity.ini";
 33	
 34	/// A connectivity input read once, syntax-checked, and retained verbatim for
 35	/// both planning and the later link step.
 36	#[derive(Debug)]
 37	pub(crate) struct ConnectivityInput {
 38	    pub bytes: Vec<u8>,
 39	    pub bindings: MemoryBindings,
 40	}
 41	
 42	pub(crate) fn read_connectivity(path: Option<&Path>) -> Result<Option<ConnectivityInput>> {
 43	    let Some(path) = path else {
 44	        return Ok(None);
 45	    };
 46	    let bytes = fs_err::read(path).map_err(|error| {
 47	        CliError::InvalidArg(format!(
 48	            "cannot read connectivity file `{}`: {error}",
 49	            path.display(),
 50	        ))
 51	    })?;
 52	    let text = std::str::from_utf8(&bytes).map_err(|error| {
 53	        CliError::InvalidArg(format!(
 54	            "connectivity file `{}` is not UTF-8: {error}",
 55	            path.display(),
 56	        ))
 57	    })?;
 58	    let bindings = MemoryBindings::parse_vitis_config(text).map_err(|error| {
 59	        CliError::InvalidArg(format!(
 60	            "invalid connectivity file `{}`: {error}",
 61	            path.display(),
 62	        ))
 63	    })?;
 64	    Ok(Some(ConnectivityInput { bytes, bindings }))
 65	}
 66	
 67	fn memory_plan_inputs(
 68	    top: &str,
 69	    interfaces: &[DirectMmapInterface],
 70	    connectivity: Option<&ConnectivityInput>,
 71	) -> Result<PlanInputs> {
 72	    let bindings = connectivity.map(|input| &input.bindings);
 73	
 74	    if interfaces.is_empty() {
 75	        if let Some(binding) = bindings.and_then(|bindings| bindings.iter().next()) {
 76	            return Err(CliError::InvalidArg(format!(
 77	                "connectivity binding `{}` does not name a direct M-AXI port of kernel `{top}`",
 78	                binding.endpoint,
 79	            )));
 80	        }
 81	        return Ok(PlanInputs::default());
 82	    }
 83	
 84	    let bindings = bindings.ok_or_else(|| {
 85	        let entries = interfaces
 86	            .iter()
 87	            .map(|interface| format!("sp={top}.{}:<bank>", interface.endpoint.top_port))
 88	            .collect::<Vec<_>>()
 89	            .join(", ");
 90	        CliError::InvalidArg(format!(
 91	            "floorplanning direct M-AXI ports requires `--connectivity` with {entries}",
 92	        ))
 93	    })?;
 94	
 95	    for binding in bindings.iter() {
 96	        let known = binding.endpoint.kernel == top
 97	            && interfaces
 98	                .iter()
 99	                .any(|interface| interface.endpoint.top_port == binding.endpoint.port);
100	        if !known {
101	            return Err(CliError::InvalidArg(format!(
102	                "connectivity binding `{}` does not name a direct M-AXI port of kernel `{top}`",
103	                binding.endpoint,
104	            )));
105	        }
106	    }
107	
108	    let memory = interfaces
109	        .iter()
110	        .map(|interface| {
111	            let bank = bindings
112	                .get(top, &interface.endpoint.top_port)
113	                .ok_or_else(|| {
114	                    CliError::InvalidArg(format!(
115	                        "connectivity is missing `sp={top}.{}:<bank>` for direct M-AXI endpoint `{}.{}`",
116	                        interface.endpoint.top_port,
117	                        interface.endpoint.instance,
118	                        interface.endpoint.port,
119	                    ))
120	                })?;
121	            Ok(MemoryInterface {
122	                endpoint: interface.endpoint.clone(),
123	                bank,
124	                channel_widths: interface.channel_widths,
125	                bridge_instance: interface.bridge_instance.clone(),
126	            })
127	        })
128	        .collect::<Result<Vec<_>>>()?;
129	
130	    Ok(PlanInputs {
131	        memory,
132	        ..PlanInputs::default()
133	    })
134	}
135	
136	/// Replace the active floorplan marker only after all dependent outputs are
137	/// ready. Removing an earlier marker first prevents `pack` from consuming RTL
138	/// or state left partially updated by a failed regeneration.
139	fn publish_floorplan_after_update(
140	    work_dir: &Path,
141	    xdc: &str,
142	    connectivity: Option<&[u8]>,
143	    update: impl FnOnce() -> Result<()>,
144	) -> Result<()> {
145	    for file_name in [
146	        FLOORPLAN_XDC,
147	        FLOORPLAN_CONNECTIVITY,
148	        implementation::LEGACY_IMPLEMENTATION_XCLBIN,
149	        implementation::IMPLEMENTATION_TIMING_REPORT,
150	        implementation::IMPLEMENTATION_METRICS,
151	    ] {
152	        match fs_err::remove_file(work_dir.join(file_name)) {
153	            Ok(()) => {}
154	            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
155	            Err(error) => return Err(error.into()),
156	        }
157	    }
158	
159	    update()?;
160	    if let Some(bytes) = connectivity {
161	        json::write_bytes_atomic(work_dir, FLOORPLAN_CONNECTIVITY, bytes)?;
162	    }
163	    // This is deliberately last: its presence is the publication marker that
164	    // all dependent RTL, state, and optional connectivity are ready.
165	    json::write_bytes_atomic(work_dir, FLOORPLAN_XDC, xdc.as_bytes())
166	}
167	
168	/// CLI spelling of [`PipelineScheme`], with `snake_case` values matching the
169	/// contract's serde tags.
170	#[derive(Debug, Clone, Copy, ValueEnum)]
171	#[value(rename_all = "snake_case")]
172	pub enum PpScheme {
173	    Single,
174	    Double,
175	    SingleHDoubleV,
176	}
177	
178	impl From<PpScheme> for PipelineScheme {
179	    fn from(scheme: PpScheme) -> Self {
180	        match scheme {
181	            PpScheme::Single => Self::Single,
182	            PpScheme::Double => Self::Double,
183	            PpScheme::SingleHDoubleV => Self::SingleHDoubleV,
184	        }
185	    }
186	}
187	
188	/// Placement subdivision schedule exposed by the CLI.
189	#[derive(Debug, Clone, Copy, PartialEq, Eq, ValueEnum)]
190	#[value(rename_all = "kebab-case")]
191	pub enum PartitionMode {
192	    /// Select flat or multilevel placement with the built-in heuristic.
193	    Auto,
194	    /// Place directly into atomic slots with one ILP.
195	    Flat,
196	    /// Place into rows first, then refine jointly into atomic slots.
197	    MultiLevel,
198	}
199	
200	impl From<PartitionMode> for PartitionStrategy {
201	    fn from(mode: PartitionMode) -> Self {
202	        match mode {
203	            PartitionMode::Auto => Self::Auto,
204	            PartitionMode::Flat => Self::Flat,
205	            PartitionMode::MultiLevel => Self::MultiLevel,
206	        }
207	    }
208	}
209	
210	#[derive(Debug, Parser)]
211	#[command(
212	    name = "floorplan",
213	    about = "Coarse-grained floorplan the synthesized design."
214	)]
215	pub struct FloorplanArgs {
216	    /// Per-slot resource utilization target for a non-DSE plan; raised on infeasibility.
217	    #[arg(
218	        long = "usage-limit",
219	        default_value_t = 0.7,
220	        value_parser = parse_usage_limit,

