 34	/// A connectivity input read once, syntax-checked, and retained verbatim for
 35	/// both planning and the later link step.
 36	#[derive(Debug)]
 37	pub(crate) struct ConnectivityInput {
 38	    pub bytes: Vec<u8>,
 39	    pub bindings: MemoryBindings,
 40	}
 41	
 42	pub(crate) fn read_connectivity(path: Option<&Path>) -> Result<Option<ConnectivityInput>> {
 43	    let Some(path) = path else {
 44	        return Ok(None);
 45	    };
 46	    let bytes = fs_err::read(path).map_err(|error| {
 47	        CliError::InvalidArg(format!(
 48	            "cannot read connectivity file `{}`: {error}",
 49	            path.display(),
 50	        ))
 51	    })?;
 52	    let text = std::str::from_utf8(&bytes).map_err(|error| {
 53	        CliError::InvalidArg(format!(
 54	            "connectivity file `{}` is not UTF-8: {error}",
 55	            path.display(),
 56	        ))
 57	    })?;
 58	    let bindings = MemoryBindings::parse_vitis_config(text).map_err(|error| {
 59	        CliError::InvalidArg(format!(
 60	            "invalid connectivity file `{}`: {error}",
 61	            path.display(),
 62	        ))
 63	    })?;
 64	    Ok(Some(ConnectivityInput { bytes, bindings }))
 65	}
