 67	fn memory_plan_inputs(
 68	    top: &str,
 69	    interfaces: &[DirectMmapInterface],
 70	    connectivity: Option<&ConnectivityInput>,
 71	) -> Result<PlanInputs> {
 72	    let bindings = connectivity.map(|input| &input.bindings);
 73	
 74	    if interfaces.is_empty() {
 75	        if let Some(binding) = bindings.and_then(|bindings| bindings.iter().next()) {
 76	            return Err(CliError::InvalidArg(format!(
 77	                "connectivity binding `{}` does not name a direct M-AXI port of kernel `{top}`",
 78	                binding.endpoint,
 79	            )));
 80	        }
 81	        return Ok(PlanInputs::default());
 82	    }
 83	
 84	    let bindings = bindings.ok_or_else(|| {
 85	        let entries = interfaces
 86	            .iter()
 87	            .map(|interface| format!("sp={top}.{}:<bank>", interface.endpoint.top_port))
 88	            .collect::<Vec<_>>()
 89	            .join(", ");
 90	        CliError::InvalidArg(format!(
 91	            "floorplanning direct M-AXI ports requires `--connectivity` with {entries}",
 92	        ))
 93	    })?;
 94	
 95	    for binding in bindings.iter() {
 96	        let known = binding.endpoint.kernel == top
 97	            && interfaces
 98	                .iter()
 99	                .any(|interface| interface.endpoint.top_port == binding.endpoint.port);
100	        if !known {
101	            return Err(CliError::InvalidArg(format!(
102	                "connectivity binding `{}` does not name a direct M-AXI port of kernel `{top}`",
103	                binding.endpoint,
104	            )));
105	        }
106	    }
107	
108	    let memory = interfaces
109	        .iter()
110	        .map(|interface| {
111	            let bank = bindings
112	                .get(top, &interface.endpoint.top_port)
113	                .ok_or_else(|| {
114	                    CliError::InvalidArg(format!(
115	                        "connectivity is missing `sp={top}.{}:<bank>` for direct M-AXI endpoint `{}.{}`",
116	                        interface.endpoint.top_port,
117	                        interface.endpoint.instance,
118	                        interface.endpoint.port,
119	                    ))
120	                })?;
121	            Ok(MemoryInterface {
122	                endpoint: interface.endpoint.clone(),
123	                bank,
124	                channel_widths: interface.channel_widths,
125	                bridge_instance: interface.bridge_instance.clone(),
126	            })
127	        })
128	        .collect::<Result<Vec<_>>>()?;
129	
130	    Ok(PlanInputs {
131	        memory,
132	        ..PlanInputs::default()
133	    })
134	}
