136	/// Replace the active floorplan marker only after all dependent outputs are
137	/// ready. Removing an earlier marker first prevents `pack` from consuming RTL
138	/// or state left partially updated by a failed regeneration.
139	fn publish_floorplan_after_update(
140	    work_dir: &Path,
141	    xdc: &str,
142	    connectivity: Option<&[u8]>,
143	    update: impl FnOnce() -> Result<()>,
144	) -> Result<()> {
145	    for file_name in [
146	        FLOORPLAN_XDC,
147	        FLOORPLAN_CONNECTIVITY,
148	        implementation::LEGACY_IMPLEMENTATION_XCLBIN,
149	        implementation::IMPLEMENTATION_TIMING_REPORT,
150	        implementation::IMPLEMENTATION_METRICS,
151	    ] {
152	        match fs_err::remove_file(work_dir.join(file_name)) {
153	            Ok(()) => {}
154	            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
155	            Err(error) => return Err(error.into()),
156	        }
157	    }
158	
159	    update()?;
160	    if let Some(bytes) = connectivity {
161	        json::write_bytes_atomic(work_dir, FLOORPLAN_CONNECTIVITY, bytes)?;
162	    }
163	    // This is deliberately last: its presence is the publication marker that
164	    // all dependent RTL, state, and optional connectivity are ready.
165	    json::write_bytes_atomic(work_dir, FLOORPLAN_XDC, xdc.as_bytes())
166	}
