126	/// Validate the implementation-only parts of the persisted synthesis target.
127	pub(super) fn validate_target(
128	    state: &WorkState,
129	    vivado_threads: u32,
130	) -> Result<ImplementationTarget> {
131	    if state.graph.target != Target::XilinxVitis {
132	        return Err(CliError::InvalidArg(
133	            "`--run-impl` and `--dse` require the `xilinx-vitis` target".to_string(),
134	        ));
135	    }
136	
137	    let part_num = state.flow.part_num.as_deref().ok_or_else(|| {
138	        CliError::InvalidArg(
139	            "implementation requires a synthesized target part; rerun `tapa synth`".to_string(),
140	        )
141	    })?;
142	    let device = select_device(part_num).map_err(|error| CliError::Floorplan(error.to_string()))?;
143	    if device.is_versal {
144	        return Err(CliError::InvalidArg(format!(
145	            "implementation from `tapa floorplan` is not supported for Versal device `{}`",
146	            device.key,
147	        )));
148	    }
149	
150	    let platform = state.flow.platform.as_deref().ok_or_else(|| {
151	        CliError::InvalidArg(
152	            "implementation requires synthesis with `--platform <installed-platform-name>`"
153	                .to_string(),
154	        )
155	    })?;
156	    if !is_logical_platform_name(platform) {
157	        return Err(CliError::InvalidArg(format!(
158	            "implementation platform `{platform}` must be an installed platform name, not a path",
159	        )));
160	    }
161	
162	    let clock_period = state.flow.clock_period.as_deref().ok_or_else(|| {
163	        CliError::InvalidArg(
164	            "implementation requires a synthesized target clock period; rerun `tapa synth`"
165	                .to_string(),
166	        )
167	    })?;
168	    let clock_period = crate::util::parse_clock_period_ns(clock_period)
169	        .map_err(|message| CliError::InvalidArg(format!("invalid synthesized target {message}")))?;
170	    let target_mhz = target_frequency_mhz(clock_period)
171	        .map_err(|error| CliError::InvalidArg(error.to_string()))?;
172	
173	    Ok(ImplementationTarget {
174	        platform: platform.to_string(),
175	        target_mhz,
176	        vivado_threads,
177	    })
178	}
