182	    let device =
183	        select_device(&floorplan.device).map_err(|error| CliError::Floorplan(error.to_string()))?;
184	    tapa_floorplan::dse::maximum_realized_utilization(floorplan, &device)
185	        .map_err(|error| CliError::Floorplan(error.to_string()))
186	}
