188	fn is_logical_platform_name(platform: &str) -> bool {
189	    !platform.is_empty()
190	        && platform == platform.trim()
191	        && !platform.contains(['/', '\\'])
192	        && !platform.to_ascii_lowercase().ends_with(".xpfm")
193	}
