283	    }
284	    let mut reports = Vec::<(Utf8PathBuf, String)>::new();
285	    for file in ["report.json", "report.yaml"] {
286	        let path = work_dir.join(file);
287	        if path.is_file() {
288	            reports.push((crate::util::utf8(path), file.to_owned()));
289	        }
290	    }
291	    for (task_name, report_dir) in super::hls_task_report_dirs(work_dir)? {
292	        let Ok(entries) = fs_err::read_dir(&report_dir) else {
293	            continue;
294	        };
295	        for entry in entries.flatten() {
296	            let path = entry.path();
297	            let Some(ext) = path.extension().and_then(|s| s.to_str()) else {
298	                continue;
299	            };
300	            if !matches!(ext, "xml" | "rpt") {
301	                continue;
302	            }
303	            let Some(file) = path.file_name().and_then(|s| s.to_str()) else {
304	                continue;
305	            };
306	            let staged_path = staged_root.join(&task_name).join(file);
307	            if let Some(parent) = staged_path.parent() {
308	                fs_err::create_dir_all(parent)?;
309	            }
310	            let text = fs_err::read_to_string(&path)?;
311	            fs_err::write(&staged_path, sanitize_hls_report_text(&text, work_dir))?;
312	            let arcname = format!("report/{task_name}/{file}");
313	            reports.push((crate::util::utf8(staged_path), arcname));
314	        }
315	    }
316	    reports.sort();
317	    Ok(reports)
318	}
