239	/// Replace the per-HLS-run `Date:` line with a fixed 1980 stamp so
240	/// the archive is reproducible. Non-UTF-8 bytes are returned
241	/// unchanged; valid HLS reports are UTF-8.
242	fn redact_rpt(bytes: &[u8]) -> Vec<u8> {
243	    use std::sync::OnceLock;
244	    static RE: OnceLock<regex::Regex> = OnceLock::new();
245	    let re = RE.get_or_init(|| {
246	        regex::Regex::new("Date:           ... ... .. ..:..:.. ....")
247	            .expect("static date regex must compile")
248	    });
249	    match std::str::from_utf8(bytes) {
250	        Ok(text) => re
251	            .replace_all(text, "Date:           Tue Jan 01 00:00:00 1980")
252	            .into_owned()
253	            .into_bytes(),
254	        Err(_) => bytes.to_vec(),
255	    }
256	}
