261	/// (`.zip` for HLS pack, `.xo` for Vitis pack).
262	fn enforce_path_suffix(output: Option<&PathBuf>, ext: &str, default: &str) -> PathBuf {
263	    match output {
264	        None => PathBuf::from(default),
265	        Some(p) if p.extension().and_then(|s| s.to_str()) == Some(ext) => p.clone(),
266	        Some(p) => {
