 16	/// When `floorplan_xdc` is set, the pblock constraints are sourced as an
 17	/// `OPT_DESIGN.TCL.PRE` hook so v++ applies the floorplan during
 18	/// implementation; `connectivity_ini` adds a `--config` for memory
 19	/// connectivity.
 20	pub(super) fn render_vitis_script(
 21	    top: &str,
 22	    output_file: &Path,
 23	    platform: Option<&str>,
 24	    clock_period: Option<&str>,
 25	    floorplan_xdc: Option<&Path>,
 26	    connectivity_ini: Option<&Path>,
 27	) -> Result<String> {
 28	    let xo = absolutize_lexical(output_file).display().to_string();
 29	    let floorplan_xdc = floorplan_xdc.map(|p| absolutize_lexical(p).display().to_string());
 30	    let connectivity_ini = connectivity_ini.map(|p| absolutize_lexical(p).display().to_string());
 31	    let target_frequency = clock_period
 32	        .map(|clock| {
 33	            let period = crate::util::parse_clock_period_ns(clock).map_err(|message| {
 34	                CliError::InvalidArg(format!("cannot emit bitstream script: invalid {message}"))
 35	            })?;
 36	            tapa_xilinx::target_frequency_mhz(period)
 37	                .map(|frequency| frequency.to_string())
 38	                .map_err(|error| {
 39	                    CliError::InvalidArg(format!(
 40	                        "cannot emit bitstream script for clock period `{clock}` ns: {error}"
 41	                    ))
 42	                })
 43	        })
 44	        .transpose()?;
 45	
 46	    Ok(format!(
 47	        "#!/bin/bash\n{}",
 48	        crate::util::render_template(
 49	            "vitis_script",
 50	            include_str!("templates/vitis_script.sh.j2"),
 51	            minijinja::context! {
 52	                top,
 53	                xo,
 54	                target_frequency,
 55	                platform,
 56	                floorplan_xdc,
 57	                connectivity_ini,
 58	            },
 59	        )
 60	    ))
 61	}
 62	
 63	/// Write the script to `dest`, making it executable on Unix
 64	/// (`chmod 0o755`).
 65	pub(super) fn write_vitis_script(
 66	    dest: &Path,
 67	    top: &str,
 68	    output_file: &Path,
 69	    platform: Option<&str>,
 70	    clock_period: Option<&str>,
 71	    floorplan_xdc: Option<&Path>,
 72	    connectivity_ini: Option<&Path>,
 73	) -> Result<()> {
 74	    if let Some(parent) = dest.parent() {
 75	        if !parent.as_os_str().is_empty() {
 76	            fs::create_dir_all(parent)?;
 77	        }
 78	    }
 79	    let body = render_vitis_script(
 80	        top,
 81	        output_file,
 82	        platform,
 83	        clock_period,
 84	        floorplan_xdc,
 85	        connectivity_ini,
 86	    )?;
 87	    fs::write(dest, body)?;
 88	    set_executable(dest)?;
 89	    Ok(())
 90	}
 91	
 92	#[cfg(unix)]
 93	fn set_executable(dest: &Path) -> Result<()> {
 94	    let mut perms = fs::metadata(dest)?.permissions();
 95	    perms.set_mode(0o755);
 96	    fs::set_permissions(dest, perms)?;
 97	    Ok(())
 98	}
 99	
100	#[cfg(not(unix))]
101	fn set_executable(_dest: &Path) -> Result<()> {
102	    Ok(())
103	}
104	
105	/// Absolute paths stay; relative paths are resolved against
106	/// `std::env::current_dir()` with no symlink resolution. We
107	/// intentionally do not use `std::fs::canonicalize` because the
108	/// target `.xo` may not yet exist when the script is emitted.
109	fn absolutize_lexical(p: &Path) -> PathBuf {
110	    if p.is_absolute() {
111	        return p.to_path_buf();
112	    }
113	    std::env::current_dir().map_or_else(|_| p.to_path_buf(), |cwd| cwd.join(p))
114	}
115	
