  1	//! Remote tool runner: tar-pipe uploads / downloads and remote
  2	//! invocation through a shared `SshSession`.
  3	//!
  4	//! Each `RemoteToolRunner::run` call opens a per-invocation
  5	//! `<work_dir>/<session_id>` directory on the remote, mirrors the
  6	//! caller's `cwd` + uploads under `rootfs/`, rewrites every absolute
  7	//! local path in the command args / env / stdin to its
  8	//! session-scoped remote equivalent, executes the tool with the
  9	//! remote working directory pointed at the rewritten `cwd`, then
 10	//! tar-pipes each requested download path back from its rootfs
 11	//! counterpart. On a transient mux failure `run_with_mux_retry`
 12	//! tears the master down, re-establishes the control socket, and
 13	//! retries the in-flight command once.
 14	
 15	mod transport;
 16	
 17	use std::io::Write;
 18	use std::process::{Command, Stdio};
 19	use std::sync::Arc;
 20	
 21	use camino::Utf8PathBuf;
 22	
 23	use self::transport::{cleanup_session, local_to_remote_path, unique_session_id, upload_batch};
 24	pub(crate) use self::transport::{download_tree, shell_quote};
 25	use crate::error::{Result, XilinxError};
 26	use crate::runtime::process::{ToolInvocation, ToolOutput, ToolRunner};
 27	use crate::runtime::ssh::{classify_ssh_error, SshErrorKind, SshSession};
 28	
 29	pub struct RemoteToolRunner {
 30	    session: Arc<SshSession>,
 31	}
 32	
 33	impl RemoteToolRunner {
 34	    pub fn new(session: Arc<SshSession>) -> Self {
 35	        Self { session }
 36	    }
 37	
 38	    pub fn session(&self) -> &SshSession {
 39	        &self.session
 40	    }
 41	
 42	    /// Build the base `ssh <target>` command populated with the
 43	    /// session's multiplexing args.
 44	    fn ssh_cmd(&self, remote_cmd: &str) -> Command {
 45	        self.session.exec_cmd(remote_cmd)
 46	    }
 47	
 48	    fn classify_remote_failure(&self, stderr: &str) -> XilinxError {
 49	        match classify_ssh_error(stderr) {
 50	            SshErrorKind::TransientMux => {
 51	                self.session.invalidate();
 52	                XilinxError::SshMuxLost {
 53	                    detail: stderr.to_string(),
 54	                }
 55	            }
 56	            _ => XilinxError::RemoteTransfer(stderr.to_string()),
 57	        }
 58	    }
 59	}
 60	
 61	/// Rewrite every occurrence of a local absolute path in `text` to its
 62	/// session-scoped remote equivalent. Longest-match-first ensures a
 63	/// path that is a prefix of another (e.g. `/a/b` vs `/a/b/c`) is not
 64	/// double-replaced.
 65	fn rewrite_abs_paths(text: &str, local_paths: &[Utf8PathBuf], session_dir: &str) -> String {
 66	    if local_paths.is_empty() {
 67	        return text.to_string();
 68	    }
 69	    let mut sorted: Vec<&Utf8PathBuf> = local_paths.iter().collect();
 70	    sorted.sort_by_key(|p| std::cmp::Reverse(p.as_str().len()));
 71	    let mut out = String::with_capacity(text.len());
 72	    let mut cursor = 0usize;
 73	    let bytes = text.as_bytes();
 74	    'outer: while cursor < bytes.len() {
 75	        for p in &sorted {
 76	            let ps = p.as_str();
 77	            if ps.is_empty() {
 78	                continue;
 79	            }
 80	            if bytes[cursor..].starts_with(ps.as_bytes()) {
 81	                out.push_str(&local_to_remote_path(p, session_dir));
 82	                cursor += ps.len();
 83	                continue 'outer;
 84	            }
 85	        }
 86	        let rest = &text[cursor..];
 87	        let ch = rest.chars().next().unwrap();
 88	        out.push(ch);
 89	        cursor += ch.len_utf8();
 90	    }
 91	    out
 92	}
 93	
 94	/// Environment variables forwarded to the remote. Anything else is
 95	/// dropped unless the key begins with `TAPA_`.
 96	const REMOTE_ENV_ALLOWLIST: &[&str] = &["HOME", "LANG", "LC_ALL", "LC_CTYPE"];
 97	
 98	fn is_forwardable_env(key: &str) -> bool {
 99	    REMOTE_ENV_ALLOWLIST.contains(&key) || key.starts_with("TAPA_")
100	}
101	
102	impl RemoteToolRunner {
103	    #[allow(
104	        clippy::too_many_lines,
105	        reason = "sequential session lifecycle: upload, rewrite, exec, download"
106	    )]
107	    /// Opens a per-invocation session directory with a `rootfs/`
108	    /// subtree, mirrors the local `cwd` plus any extra uploads under
109	    /// that rootfs, rewrites absolute local paths in the command
110	    /// args / env / stdin to their session-relative remote
111	    /// equivalents, executes the command with the remote working
112	    /// directory pointed at the rewritten cwd, and then tar-pipes
113	    /// each requested download path back from its rootfs
114	    /// counterpart.
115	    fn run_once(&self, inv: &ToolInvocation) -> Result<ToolOutput> {
116	        self.session.ensure_established()?;
117	        let cfg = self.session.config();
118	        let session_dir = format!("{}/{}", cfg.work_dir, unique_session_id());
119	
120	        // Accept relative `--work-dir ./work.out` and
121	        // relative upload/download paths by absolutizing against the
122	        // caller's cwd. Without this, the default `tapa synth` / `pack`
123	        // invocation drops the work tree + RTL + C++ sources from the
124	        // upload batch, leaving the remote Vitis HLS with nothing to
125	        // compile.
126	        let absolutize = |p: &Utf8PathBuf| crate::util::absolutize(p);
127	        let cwd_abs: Option<Utf8PathBuf> = inv.cwd.as_ref().map(absolutize);
128	        let uploads_abs: Vec<Utf8PathBuf> = inv.uploads.iter().map(absolutize).collect();
129	        let downloads_abs: Vec<Utf8PathBuf> = inv.downloads.iter().map(absolutize).collect();
130	
131	        let mut referenced: Vec<Utf8PathBuf> = Vec::new();
132	        if let Some(cwd) = cwd_abs.as_ref() {
133	            referenced.push(cwd.clone());
134	        }
135	        referenced.extend(uploads_abs.iter().cloned());
136	        referenced.extend(downloads_abs.iter().cloned());
137	        let mut seen: std::collections::HashSet<Utf8PathBuf> = std::collections::HashSet::new();
138	        referenced.retain(|p| seen.insert(p.clone()));
139	
140	        let mut to_upload: Vec<Utf8PathBuf> = Vec::new();
141	        if let Some(cwd) = cwd_abs.as_ref() {
142	            if cwd.exists() {
143	                to_upload.push(cwd.clone());
144	            }
145	        }
146	        for p in &uploads_abs {
147	            if p.exists() {
148	                to_upload.push(p.clone());
149	            }
150	        }
151	        let mut seen2: std::collections::HashSet<Utf8PathBuf> = std::collections::HashSet::new();
152	        to_upload.retain(|p| seen2.insert(p.clone()));
153	        upload_batch(&self.session, &session_dir, &to_upload)?;
154	
155	        let remote_cwd = match cwd_abs.as_ref() {
156	            Some(cwd) => local_to_remote_path(cwd, &session_dir),
157	            None => format!("{session_dir}/rootfs"),
158	        };
159	
160	        let mut parts: Vec<String> = Vec::new();
161	        for dl in &downloads_abs {
162	            let remote_dl = local_to_remote_path(dl, &session_dir);
163	            parts.push(format!("mkdir -p {}", shell_quote(&remote_dl)));
164	        }
165	        if let Some(xs) = cfg.xilinx_settings.as_ref() {
166	            if !xs.trim().is_empty() {
167	                parts.push(format!("source {}", shell_quote(xs)));
168	            }
169	        }
170	        for (k, v) in &inv.env {
171	            if !is_forwardable_env(k) {
172	                continue;
173	            }
174	            let rv = rewrite_abs_paths(v, &referenced, &session_dir);
175	            parts.push(format!("export {}={}", k, shell_quote(&rv)));
176	        }
177	        let rewritten_args: Vec<String> = inv
178	            .args
179	            .iter()
180	            .map(|a| rewrite_abs_paths(a, &referenced, &session_dir))
181	            .collect();
182	        let exec = std::iter::once(shell_quote(&inv.program))
183	            .chain(rewritten_args.iter().map(|a| shell_quote(a)))
184	            .collect::<Vec<_>>()
185	            .join(" ");
186	        parts.push(format!("cd {} && exec {}", shell_quote(&remote_cwd), exec));
187	        let full_cmd = parts.join(" ; ");
188	        let wrapped = format!("bash -c {}", shell_quote(&full_cmd));
189	
190	        let mut ssh = self.ssh_cmd(&wrapped);
191	        ssh.stdout(Stdio::piped());
192	        ssh.stderr(Stdio::piped());
193	        if inv.stdin.is_some() {
194	            ssh.stdin(Stdio::piped());
195	        }
196	        let mut child = ssh
197	            .spawn()
198	            .map_err(|e| XilinxError::RemoteTransfer(format!("spawn ssh exec: {e}")))?;
199	        if let Some(bytes) = &inv.stdin {
200	            if let Some(mut si) = child.stdin.take() {
201	                si.write_all(bytes)
202	                    .map_err(|e| XilinxError::RemoteTransfer(format!("write stdin: {e}")))?;
203	            }
204	        }
205	        let out = child
206	            .wait_with_output()
207	            .map_err(|e| XilinxError::RemoteTransfer(format!("wait ssh exec: {e}")))?;
208	        let stdout = String::from_utf8_lossy(&out.stdout).into_owned();
209	        let stderr = String::from_utf8_lossy(&out.stderr).into_owned();
210	        let code = out.status.code().unwrap_or(-1);
211	        if code != 0
212	            && !stderr.is_empty()
213	            && classify_ssh_error(&stderr) == SshErrorKind::TransientMux
214	        {
215	            cleanup_session(&self.session, &session_dir);
216	            return Err(self.classify_remote_failure(&stderr));
217	        }
218	
219	        // Download artifacts regardless of exit code so that failure logs
220	        // and `--keep-hls-work-dir` project trees are preserved locally.
221	        for (raw, abs) in inv.downloads.iter().zip(downloads_abs.iter()) {
222	            let remote_src = local_to_remote_path(abs, &session_dir);
223	            // Download back to the caller's requested path (raw), which
224	            // may be relative — keeping the caller-facing contract.
225	            download_tree(&self.session, &remote_src, raw.as_std_path())?;
226	        }
227	
228	        cleanup_session(&self.session, &session_dir);
229	
230	        Ok(ToolOutput {
231	            exit_code: code,
232	            stdout,
233	            stderr,
234	        })
235	    }
236	}
237	
238	/// Pure mux-retry driver. Takes two callbacks — the attempt and the
239	/// recovery — so the retry branch is unit-testable without a live
240	/// `SshSession`. `attempt` is invoked once; if it returns a
241	/// recoverable mux error (per [`is_recoverable_mux_error`]) the
242	/// caller runs `recover` (typically `reset_mux` + `ensure_established`)
243	/// and then retries `attempt` exactly once. Non-recoverable errors pass
244	/// through unchanged.
245	fn run_with_mux_retry<A, R>(mut attempt: A, mut recover: R) -> Result<ToolOutput>
246	where
247	    A: FnMut() -> Result<ToolOutput>,
248	    R: FnMut() -> Result<()>,
249	{
250	    match attempt() {
251	        Ok(out) => Ok(out),
252	        Err(err) if is_recoverable_mux_error(&err) => {
253	            recover()?;
254	            attempt()
255	        }
256	        Err(e) => Err(e),
257	    }
258	}
