138	/// Walks
139	/// the parents of the binary looking for a `tapa.runfiles` tree and
140	/// returns the external library directories Bazel stages there
141	/// (gflags, glog, boost). Outside of Bazel, no `tapa.runfiles` exists
142	/// and the helper returns an empty vector.
143	fn find_external_lib_in_runfiles() -> Vec<PathBuf> {
144	    let anchor = std::env::var_os("TAPA_CLI_SEARCH_ANCHOR")
145	        .map(PathBuf::from)
146	        .or_else(|| std::env::current_exe().ok())
147	        .unwrap_or_else(|| PathBuf::from("."));
148	
149	    let mut cursor: Option<&Path> = Some(anchor.as_path());
150	    while let Some(parent) = cursor {
151	        let candidate = parent.join("tapa.runfiles");
152	        if candidate.is_dir() {
153	            return [
154	                "gflags+",
155	                "glog+",
156	                "rules_boost++non_module_dependencies+boost",
157	            ]
158	            .iter()
159	            .map(|leaf| candidate.join(leaf))
160	            .filter(|p| p.exists())
161	            .collect();
162	        }
163	        cursor = parent.parent();
164	    }
165	    Vec::new()
166	}
