183	fn vendor_gcc_paths(hls_root: &Path) -> Vec<PathBuf> {
184	    let tps = hls_root.join("tps").join("lnx64");
185	    let mut versions: Vec<(semver::Version, PathBuf)> = Vec::new();
186	    let Ok(entries) = std::fs::read_dir(&tps) else {
187	        return Vec::new();
188	    };
189	    for entry in entries.flatten() {
190	        let name = entry.file_name();
191	        let s = name.to_string_lossy();
192	        if let Some(rest) = s.strip_prefix("gcc-") {
193	            if let Ok(ver) = semver::Version::parse(rest) {
194	                versions.push((ver, entry.path()));
195	            }
196	        }
197	    }
198	    versions.sort_by(|a, b| a.0.cmp(&b.0));
199	    let Some((latest, dir)) = versions.pop() else {
200	        return Vec::new();
201	    };
202	
203	    let cpp_include = dir.join("include").join("c++").join(latest.to_string());
204	    if !cpp_include.exists() {
205	        return Vec::new();
206	    }
207	    let mut out = vec![cpp_include.clone()];
208	    for arch in ["x86_64-pc-linux-gnu", "x86_64-linux-gnu"] {
209	        let p = cpp_include.join(arch);
210	        if p.exists() {
211	            out.push(p);
212	            break;
213	        }
214	    }
215	    out
216	}
